              "settings_general_auto_refresh_field_value": "5s,10s,30s,1m,5m,15m,30m,1h,2h,1d",
              "saved_json_model_refresh": "1m",
              "saved_json_model_tags": "bench",
              "save_dialog_initially_disabled": "true (drawer showed \"No changes to save\")",
              "save_button_aria_disabled_after_ticking_update_default_refresh": "false ({{v5}} enabled)",
