// Shared execution source: text.ts. Regenerate to update.
/**
 * Text rules both execution targets share: the volatile-token mask, the
 * bounded identity matcher, and the regex escape they are built on. The
 * daemon imports this module; a compiled `.flow.ts` artifact embeds its exact
 * source (spec/runtime-source.ts), so it must stay self-contained — no imports
 * beyond a sibling shared module or a Playwright type.
 */

/** `text` cut to `max` characters with an ellipsis, or unchanged when it fits. */
function clip(text: string, max: number): string {
  return text.length <= max ? text : text.slice(0, max) + '…';
}

/**
 * Clock and calendar tokens are the RECORDING's moment, not part of what a
 * page element IS: kanboard names its due-date textbox after the current
 * minute ("09/03/2026 07:22") and labels a summary row "Due date:
 * 12/31/2026 07:40". Recorded verbatim, such a name matches nothing nine
 * minutes later. maskVolatile() turns each token into the `{{*}}` wildcard
 * for stored expectations; volatileMatcher() turns a recorded locator name
 * into a RegExp that treats the same tokens as wildcards.
 */
const WILDCARD = '{{*}}';
const VOLATILE_TOKEN = /\b\d{1,2}:\d{2}(?::\d{2})?\b|\b\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}\b/g;

function maskVolatile(line: string): string {
  return line.replace(VOLATILE_TOKEN, WILDCARD);
}

/** A value interpolated into a pattern is DATA: its own metacharacters must not become pattern. */
function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * The recorded string itself when it carries no volatile token, else an
 * anchored RegExp in which each token matches any token of the same shape —
 * another time, another date — and nothing else, so the rest of the name is
 * still matched exactly.
 */
/**
 * What one masked token stood for, as regex SOURCE. Exported because a
 * compiled spec has to rebuild the same matcher from a line the store already
 * masked (see spec/locators.ts, maskedMatcherSource) and a second copy of this
 * shape would be free to drift away from this one.
 */
const VOLATILE_TOKEN_SHAPE = '(?:\\d{1,2}:\\d{2}(?::\\d{2})?|\\d{1,4}[/.-]\\d{1,2}[/.-]\\d{1,4})';

/**
 * What may NOT sit against an identity marker: a letter or a digit.
 *
 * An identity marker is the only thing in the system that can tell ticket t15
 * from ticket t14 — a url pattern and a page fingerprint match every record of
 * a template, so when the url gate proceeds optimistically on a disagreeing
 * segment, this is the gate the decision falls to. Matched by plain substring
 * it does not decide anything: `fwgr25-n1` is satisfied by a page showing
 * `fwgr25-n10`, `RD-1015` by `RD-10150`, and a bare runid is the commonest
 * marker shape there is.
 *
 * So a marker matches only where neither edge is glued to another letter or
 * digit. BOTH lookarounds, unconditionally — not "when the marker looks like
 * an identifier". The shape is not a property of the MARKER but of what the
 * page may put beside it: `fwod28-n1 Bench Customer` is prose-shaped and
 * `…Bench Customers` is a different record. Punctuation is not a letter or a
 * digit, so `(INV-2024/17)` still matches while `INV-2024/170` does not, and
 * `\p{L}` (with `u`) keeps `Ångström` and `田中` right.
 *
 * Exported as SOURCE because a compiled spec must rebuild the same rule inside
 * the emitted artifact, and a second copy of the class would be free to drift
 * away from this one — the same reason VOLATILE_TOKEN_SHAPE is exported.
 */
const IDENTITY_EDGE = '[\\p{L}\\p{N}]';

/**
 * `marker` as regex SOURCE for the bounded identity rule: whitespace-normalised,
 * every literal run of spaces matching any whitespace (the daemon's snapshot and
 * a DOM's textContent space things differently), `{{*}}` matching anything
 * within one line, and both edges guarded by IDENTITY_EDGE.
 */
function identitySource(marker: string): string {
  const body = marker
    .replace(/\s+/g, ' ')
    .trim()
    .split(WILDCARD)
    .map((part) => escapeRe(part).replace(/ /g, '\\s+'))
    .join('[^\\n]*?');
  return `(?<!${IDENTITY_EDGE})${body}(?!${IDENTITY_EDGE})`;
}

/**
 * identitySource as a RegExp. Case-INSENSITIVE: the daemon was case-sensitive
 * here and the emitted artifact was not, and a case-insensitive BOUNDED match
 * is strictly tighter than the case-sensitive SUBSTRING it replaces — so
 * unifying on `i` is not a loosening, and it settles a real parity gap (a
 * rendered value is not always cased as it was typed).
 */
function identityRe(marker: string): RegExp {
  return new RegExp(identitySource(marker), 'iu');
}
function volatileMatcher(text: string): string | RegExp {
  const masked = maskVolatile(text);
  if (masked === text) return text;
  return new RegExp(`^${masked.split(WILDCARD).map(escapeRe).join(VOLATILE_TOKEN_SHAPE)}$`);
}

// Shared execution source: url.ts. Regenerate to update.
/**
 * Url rules both execution targets share: how a url is reduced to the shape
 * that identifies its page, how a stored pattern is judged against a live url,
 * and how the addressable parts of a url are labelled for derived values.
 *
 * The daemon imports this module (through skills/compile.ts) and a compiled
 * `.flow.ts` artifact embeds its exact source (spec/runtime-source.ts), so it
 * must stay self-contained: nothing but a sibling shared module or a
 * Playwright type may be imported. `urlPattern`, which needs the slot
 * substitution and id-shape heuristics of compile.ts, deliberately stays there.
 */

/** Inverse of substitute(): fill "{{vN}}" (caller param) and "{{dN}}" (derived,
 * bound from the live run's own urls) markers from a param map. */
function fillParams(text: string, params: Record<string, string>): string {
  return text.replace(/\{\{([vd]\d+)\}\}/g, (m, name: string) => (name in params ? params[name] : m));
}

function fillParamsDeep(value: unknown, params: Record<string, string>): unknown {
  if (typeof value === 'string') return fillParams(value, params);
  if (Array.isArray(value)) return value.map((v) => fillParamsDeep(v, params));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([k, v]) => [k, fillParamsDeep(v, params)]));
  }
  return value;
}

/**
 * The origin a url (or a stored url pattern) is "home" to: `http(s)://host`,
 * the opaque `file://` for a local page, null for anything else or for text
 * that is not a url. Both runners derive a step's `stayOnOrigin` from this —
 * the recorded url pattern first, the live page otherwise — so it lives here
 * rather than in the skill store, which re-exports it.
 */
function originOf(url: string): string | null {
  try {
    const u = new URL(url);
    if (!/^https?:$/.test(u.protocol)) return u.protocol === 'file:' ? 'file://' : null;
    return u.origin;
  } catch {
    return null;
  }
}

/**
 * A url decomposed for structural matching: origin, path segments, query
 * pairs, and the hash fragment as either route segments or state pairs.
 * Parses stored patterns (which may carry `:id` / `:var` / `{{…}}` markers)
 * and live urls alike.
 *
 * The query string used to be dropped, so `edit?id=123` and `edit?id=999`
 * were one page and kanboard's every `?controller=…&action=…` route read as
 * `/` (ROBUSTNESS.md, finding 3). It is kept now, less the keys `noiseQueryKey`
 * names: tracking tags and cache busters say nothing about which page it is.
 */
interface UrlShape {
  origin: string;
  path: string[];
  query: Map<string, string>;
  hashKind: 'none' | 'path' | 'state';
  hashPath: string[];
  hashState: Map<string, string>;
  /** Whether a path-shaped fragment began with '/', for round-tripping. */
  hashSlash: boolean;
}

/** A query key that never identifies a page: campaign tags, click ids, a cache buster. */
function noiseQueryKey(key: string): boolean {
  return /^utm_/i.test(key) || /^(fbclid|gclid|msclkid|_|_t|cb)$/i.test(key);
}

/**
 * A url key whose value is a credential: OAuth tokens, codes, sessions,
 * signatures. Its value is masked wherever a url is shown, and a recorded
 * pattern stores it as a wildcard, never the value.
 */
const CREDENTIAL_KEY = /token|secret|passw|session|auth|code|sig|key|credential|nonce|jwt/i;

/** The query string's pairs, decoded, noise keys dropped; a repeated key keeps every value, comma-joined. */
function queryPairs(search: string): Map<string, string> {
  const out = new Map<string, string>();
  const body = search.startsWith('?') ? search.slice(1) : search;
  for (const pair of body.split('&').filter(Boolean)) {
    const eq = pair.indexOf('=');
    const key = safeDecode(eq < 0 ? pair : pair.slice(0, eq));
    if (!key || noiseQueryKey(key)) continue;
    const value = eq < 0 ? '' : safeDecode(pair.slice(eq + 1).replace(/\+/g, ' '));
    out.set(key, out.has(key) ? `${out.get(key)},${value}` : value);
  }
  return out;
}

function safeDecode(s: string): string {
  try {
    return decodeURIComponent(s);
  } catch {
    return s;
  }
}

function urlShapeOf(s: string): UrlShape | null {
  let u: URL;
  try {
    u = new URL(s);
  } catch {
    return null;
  }
  const origin = u.protocol === 'file:' ? 'file://' : u.origin;
  const shape: UrlShape = {
    origin,
    path: u.pathname.split('/').filter(Boolean).map(safeDecode),
    query: queryPairs(u.search),
    hashKind: 'none',
    hashPath: [],
    hashState: new Map(),
    hashSlash: false,
  };
  const body = u.hash && u.hash.length > 1 ? u.hash.slice(1).split('?')[0] : '';
  if (!body) return shape;
  if (body.startsWith('/') || !body.includes('=')) {
    shape.hashKind = 'path';
    shape.hashSlash = body.startsWith('/');
    shape.hashPath = body.split('/').filter(Boolean).map(safeDecode);
    return shape;
  }
  shape.hashKind = 'state';
  for (const pair of body.split('&').filter(Boolean)) {
    const eq = pair.indexOf('=');
    if (eq < 0) shape.hashState.set(pair, '');
    else shape.hashState.set(pair.slice(0, eq), safeDecode(pair.slice(eq + 1)));
  }
  return shape;
}

function serializeShape(s: UrlShape): string {
  let hash = '';
  if (s.hashKind === 'path') hash = '#' + (s.hashSlash ? '/' : '') + s.hashPath.join('/');
  else if (s.hashKind === 'state') {
    hash = '#' + [...s.hashState].map(([k, v]) => `${k}=${v}`).sort().join('&');
  }
  const query = s.query.size ? '?' + [...s.query].map(([k, v]) => `${k}=${v}`).sort().join('&') : '';
  return `${s.origin}/${s.path.join('/')}${query}${hash}`;
}

/** A pattern segment that stands for "any value here". */
function isWildcardSeg(seg: string): boolean {
  return seg === ':id' || seg === ':var' || /\{\{[\w.-]+\}\}/.test(seg);
}

/** One segment where a pattern's literal disagrees with the live url. */
interface UrlSegDiff {
  where: 'path' | 'query' | 'hashPath' | 'hashState';
  index?: number;
  key?: string;
  expected: string;
  actual: string;
}

/**
 * Structural comparison of a stored pattern against a live url: `null` when
 * the two are not even the same page shape (different origin, path length,
 * route, or a required state key missing), otherwise the list of segments
 * where a literal in the pattern disagrees with the live value — empty list
 * means a match. Wildcard segments (`:id`, `:var`, unfilled `{{…}}`) match
 * anything: matching consults the pattern's own markers, never a shape
 * heuristic on the live value (that is what made the url shape test load-bearing).
 *
 * A query-shaped fragment is application STATE, and state accumulates (Odoo
 * lands on "#cids=1" and has grown "#action=…&menu_id=…" by the next
 * segment) — so it is a necessary condition: every pair the pattern names
 * must be present, extra live pairs are allowed, and a pattern with no hash
 * requires nothing of a live state fragment. A path-shaped fragment is a
 * route and must match segment for segment.
 *
 * The query is judged on the keys BOTH urls carry: a value that disagrees
 * there is a segment that disagrees (`?status=success` against
 * `?status=failure`). A key only one side has is not evidence of a different
 * page — grafana adds and drops `refresh=1m` on the same dashboard, and a
 * recording can catch its url before or after the app rewrites it — with one
 * exception: a key in `boundKeys`, which the pattern fills from a caller or
 * derived value (`edit?id={{v1}}`), names the record, and a live url without
 * it is not that record. `urlMatches` and `softUrlMatch` pass those keys,
 * read off the pattern before its markers are filled.
 */
function urlDiff(pattern: string, url: string, boundKeys: ReadonlySet<string> = new Set()): UrlSegDiff[] | null {
  const p = urlShapeOf(pattern);
  const l = urlShapeOf(url);
  if (!p || !l) return pattern === url ? [] : null;
  if (p.origin !== l.origin || p.path.length !== l.path.length) return null;
  const diffs: UrlSegDiff[] = [];
  p.path.forEach((seg, i) => {
    if (!isWildcardSeg(seg) && seg !== l.path[i]) diffs.push({ where: 'path', index: i, expected: seg, actual: l.path[i] });
  });
  for (const [key, val] of p.query) {
    if (!l.query.has(key)) {
      if (boundKeys.has(key)) return null;
      continue;
    }
    const lv = l.query.get(key)!;
    if (!isWildcardSeg(val) && val !== lv) diffs.push({ where: 'query', key, expected: val, actual: lv });
  }
  if (p.hashKind === 'path') {
    if (l.hashKind !== 'path' || p.hashPath.length !== l.hashPath.length) return null;
    p.hashPath.forEach((seg, i) => {
      if (!isWildcardSeg(seg) && seg !== l.hashPath[i]) diffs.push({ where: 'hashPath', index: i, expected: seg, actual: l.hashPath[i] });
    });
  } else if (p.hashKind === 'state') {
    if (l.hashKind !== 'state') return null;
    for (const [key, val] of p.hashState) {
      // A key the pattern only knows as a wildcard (`:id`, a {{dN}} it never
      // learned a value for) is app-minted state, not identity: odoo adds
      // `cids=1` to a url on one run and not the next, and fwod32's sign-in
      // stopped on every replay because the live url lacked it. A missing
      // key with a LITERAL value is still a different page.
      if (!l.hashState.has(key)) {
        if (isWildcardSeg(val)) continue;
        return null;
      }
      const lv = l.hashState.get(key)!;
      if (!isWildcardSeg(val) && val !== lv) diffs.push({ where: 'hashState', key, expected: val, actual: lv });
    }
  } else if (l.hashKind === 'path' && l.hashPath.length) {
    return null; // pattern names no route; the live url is on one
  }
  return diffs;
}

/** Whether a live url matches a stored pattern exactly (wildcards aside). */
function urlMatches(pattern: string, url: string, params: Record<string, string> = {}): boolean {
  return urlDiff(fillParams(pattern, params), url, boundQueryKeys(pattern, params))?.length === 0;
}

/** The query keys a pattern fills from a marker `params` binds — see urlDiff. */
function boundQueryKeys(pattern: string, params: Record<string, string>): Set<string> {
  const shape = urlShapeOf(pattern);
  // Typed on the binding, not the constructor: execution-echo.test.ts tells a
  // ledger-free artifact by the constructor spelling a ledger uses.
  const out: Set<string> = new Set();
  if (!shape) return out;
  for (const [key, val] of shape.query) {
    if ([...val.matchAll(/\{\{([vd]\d+)\}\}/g)].some((m) => params[m[1]])) out.add(key);
  }
  return out;
}

const MAX_SOFT_DIFFS = 2;

/**
 * Whether a url value has the shape of something an environment MINTS: one
 * unbroken token carrying a digit (`rec-1`, `afw6yy5xx9`, `133`), or with no
 * '-'/'_' at least twelve characters or eight hex letters. A word or a slug of
 * words (`edit`, `success`, `order-history`) is a route an application chose,
 * and a different one is a different page. The generous arm of
 * skills/shape.ts's `generatedToken`, restated because this module may import
 * nothing.
 */
function mintedShape(value: string): boolean {
  if (!value || /\s/.test(value)) return false;
  if (/\d/.test(value)) return true;
  if (/[_-]/.test(value)) return false;
  return value.length >= 12 || /^[0-9a-f]{8,}$/i.test(value);
}

/**
 * Mechanism-2 tolerance (PLAN-replay-v2): the live url is the same page
 * SHAPE as the pattern but 1–2 literal segments disagree — the signature of
 * an environment-minted identifier (a Grafana uid, an Odoo action id) that
 * this run minted differently. Returns the pattern with exactly the
 * disagreeing segments generalised to `:var`, for the caller to proceed
 * optimistically and PERSIST only once the run past this point succeeds —
 * the segment has then demonstrated volatility. Null when the urls differ in
 * shape, everything matched already, or a slot value broke segmentation.
 *
 * A disagreement alone is not evidence of volatility, so two kinds are never
 * soft (ROBUSTNESS.md, finding 3):
 *  - a segment where either side is a WORD rather than a minted shape:
 *    `/orders/success` against `/orders/failure`, `/items/7/edit` against
 *    `/items/7/view`, are different pages, and generalising them to `:var`
 *    would have let the url gate — and every later run — accept either;
 *  - a segment the pattern fills from a PARAMETER (`{{v1}}`, a bound
 *    `{{d1}}`): the caller named that record, and a different value there is
 *    a different record, not a volatile one.
 */
function softUrlMatch(
  pattern: string,
  url: string,
  params: Record<string, string> = {},
): { generalised: string; diffs: UrlSegDiff[] } | null {
  const filled = fillParams(pattern, params);
  const diffs = urlDiff(filled, url, boundQueryKeys(pattern, params));
  if (!diffs || !diffs.length || diffs.length > MAX_SOFT_DIFFS) return null;
  // Generalise in the ORIGINAL pattern (markers intact). A param value
  // containing '/' would shift segment positions between the two — bail.
  const orig = urlShapeOf(pattern);
  const fld = urlShapeOf(filled);
  if (!orig || !fld || orig.path.length !== fld.path.length || orig.hashPath.length !== fld.hashPath.length) return null;
  for (const d of diffs) {
    if (!mintedShape(d.expected) || !mintedShape(d.actual)) return null;
    const recorded =
      d.where === 'path' ? orig.path[d.index!] : d.where === 'hashPath' ? orig.hashPath[d.index!] : d.where === 'query' ? orig.query.get(d.key!) : orig.hashState.get(d.key!);
    if (recorded === undefined || recorded.includes('{{')) return null;
  }
  for (const d of diffs) {
    if (d.where === 'path') orig.path[d.index!] = ':var';
    else if (d.where === 'query') orig.query.set(d.key!, ':var');
    else if (d.where === 'hashPath') orig.hashPath[d.index!] = ':var';
    else orig.hashState.set(d.key!, ':var');
  }
  return { generalised: serializeShape(orig), diffs };
}

/**
 * The addressable parts of a url, labelled stably so a value observed at
 * record time can be re-extracted from the live run's url at the same
 * position: path segments `p<i>`, hash-route segments `h<i>`, hash-state
 * values `q.<key>`.
 */
function urlParts(url: string): { label: string; value: string }[] {
  const s = urlShapeOf(url);
  if (!s) return [];
  const out: { label: string; value: string }[] = [];
  s.path.forEach((value, i) => out.push({ label: `p${i}`, value }));
  s.hashPath.forEach((value, i) => out.push({ label: `h${i}`, value }));
  for (const [k, value] of s.hashState) out.push({ label: `q.${k}`, value });
  return out;
}

function urlPart(url: string, label: string): string | undefined {
  return urlParts(url).find((p) => p.label === label)?.value;
}

// Shared execution source: gates.ts. Regenerate to update.
/**
 * The step and segment GATES both execution targets judge by, as pure
 * verdicts over observations the caller supplies: an error page, where a step
 * left the url, a live-region alert, where a segment starts, and whether a
 * goal's markers are bound at all.
 *
 * Each verdict is one function called by daemon replay (src/skills/replay.ts)
 * AND by the compiled `.flow.ts` artifact, which embeds this exact source
 * (spec/runtime-source.ts). What differs per runner is only HOW it waits and
 * observes, never what it decides — a rule only one runner applies is the class
 * of defect the parity harness exists to catch. So this module must stay
 * self-contained: sibling shared modules and Playwright types only.
 *
 * `where` in every message is the caller's name for the step ("step 3" in the
 * daemon, "<stepId> <segmentId>/<n>" in the artifact).
 */

/**
 * How a LIVE url reads in a verdict's message. The message travels: into a
 * recovery prompt, onto the persisted run record, into a refusals list. The
 * url's shape (origin, path, hash route or state) is all any of those need;
 * the query string and a free-form fragment are where `?token=…` and
 * `#access_token=…` live, and they must not travel with it. A state-shaped
 * fragment is kept (its keys are app routing — odoo's `#action=9&cids=1`).
 * Of the query, only the keys `against` — the pattern the url was judged by —
 * names are kept, since those are the pairs the verdict is about
 * (`?status=failure` where `?status=success` was expected); every other query
 * pair is dropped. Either way the VALUE of any key that names a credential is
 * replaced by `***`. A url that does not parse is shown as it is.
 */
function describeUrl(url: string, against?: string): string {
  const shape = urlShapeOf(url);
  if (!shape) return url;
  const named = (against && urlShapeOf(against)?.query) || new Map<string, string>();
  for (const key of shape.query.keys()) {
    if (!named.has(key)) shape.query.delete(key);
  }
  for (const pairs of [shape.query, shape.hashState]) {
    for (const key of pairs.keys()) {
      if (CREDENTIAL_KEY.test(key)) pairs.set(key, '***');
    }
  }
  return serializeShape(shape);
}

/** The tab is on a browser error page: a crashed renderer, a navigation the network refused. */
function isErrorPageUrl(url: string): boolean {
  return /^chrome-error:|^about:neterror/.test(url);
}

/**
 * Nothing recorded can hold on an error page, and every later step would
 * resolve nothing while the run pressed on. fwgr26-n2 ran eleven more steps
 * on chrome-error://chromewebdata/ before the next segment refused with the
 * unreadable "browser is at null/".
 */
function errorPageVerdict(url: string, where: string): string | null {
  return isErrorPageUrl(url) ? `after ${where} the browser is on an error page (${url}) — the tab crashed or a navigation failed` : null;
}

interface UrlEffectVerdict {
  stop?: string;
  warnings: string[];
  /** The pattern with the disagreeing segments generalised, to persist once the run past here succeeds. */
  generalised?: string;
  diffs?: UrlSegDiff[];
}

/**
 * Hard expectation: where the step was supposed to leave the browser. A
 * strict match passes. A same-shape url whose 1–2 literal segments disagree is
 * the signature of an environment-minted identifier (a Grafana uid, an Odoo
 * action id) — treated as volatile: warn, hand back the generalisation,
 * continue. Anything else stops. The WAIT for a navigation still in flight
 * belongs to the caller: judge only once the url has had its window.
 */
function urlEffectVerdict(
  pattern: string | undefined,
  liveUrl: string,
  params: Record<string, string>,
  where: string,
): UrlEffectVerdict {
  if (!pattern || urlMatches(pattern, liveUrl, params)) return { warnings: [] };
  const soft = softUrlMatch(pattern, liveUrl, params);
  if (!soft) return { warnings: [], stop: `after ${where} expected url ${fillParams(pattern, params)} but browser is at ${describeUrl(liveUrl, pattern)}` };
  return {
    warnings: [`${where}: url segment(s) differ from recorded (${describeDiffs(soft.diffs)}) — treated as volatile`],
    generalised: soft.generalised,
    diffs: soft.diffs,
  };
}

function describeDiffs(diffs: UrlSegDiff[]): string {
  return diffs.map((d) => `${d.expected}→${d.actual}`).join(', ');
}

interface AlertVerdict {
  stop?: string;
  warnings: string[];
  /** The alert evidence could not be captured; nothing here was proven either way. */
  unobserved?: true;
}

/**
 * An alert the recording never saw cannot, on its own, be told apart: it may
 * be the app talking back — a rejection ("Ticket is not ready…") that leaves
 * the page superficially intact, as fwrd4l-n3 clicked into, the step counted
 * as run and only external verification catching that the ticket never
 * reached Ready — or it may be ambient page content that simply rendered late,
 * like fwgr34's "Error loading RSS feed" on a Grafana home page whose feed an
 * offline box cannot reach (the recording's after-look came before it did).
 *
 * So an unrecorded alert is always REPORTED, and whether the run continues is
 * decided by the step's own state evidence, not by the alert:
 * - `effectConfirmed` (expect.ts ChangeVerdict.confirmed — the recorded page
 *   changes appeared in what the action added): the step demonstrably did what
 *   it was recorded doing, so the alert is a warning and the run goes on; a
 *   later gate or step stops it if the state is in fact broken.
 * - otherwise the alert is the only evidence there is about whether the step
 *   worked, and a state-changing step stops on it (the rejected Mark that
 *   would otherwise go on to Remove the item).
 * A recorded-but-missing alert stays soft — toasts are volatile — and never
 * stops; a recorded alert (`expectedContains`) is what the step is expected
 * to raise, and is checked, not treated as unexpected.
 *
 * `before`/`after` are the visible live-region texts around the action (the
 * daemon's diff already holds the surplus, so it passes `before: []`); `after`
 * is null when the page could not be captured, which is reported as
 * unobserved rather than read as "no alert was raised".
 *
 * `afterComplete` false says the after-look did not see every live region
 * (the alert cap was reached, or a rendered frame could not be read). An
 * alert it DID see still stops the step — that is evidence — but "nothing new
 * was raised" and "the expected alert is missing" are then not established:
 * both are reported unobserved, never as a clean step.
 */
function alertVerdict(
  before: string[],
  after: string[] | null,
  ctx: { where: string; isRead: boolean; expectedContains?: string; params: Record<string, string>; effectConfirmed?: boolean },
  afterComplete = true,
): AlertVerdict {
  const warnings: string[] = [];
  let unobserved: true | undefined;
  const want = ctx.expectedContains ? fillParams(ctx.expectedContains, ctx.params) : undefined;
  if (after === null) {
    // Detecting a NEW alert needs both captures; with either missing there is
    // no answer to give. Say so rather than the silent nothing that reads,
    // downstream, exactly like "no alert was raised".
    if (!ctx.isRead) {
      unobserved = true;
      warnings.push(`${ctx.where}: the page could not be captured after the action — whether it raised an alert is unknown, not clear`);
    }
    if (want !== undefined) {
      unobserved = true;
      warnings.push(`${ctx.where}: expected alert containing ${JSON.stringify(want)} could not be observed`);
    }
    return unobserved ? { warnings, unobserved } : { warnings };
  }
  const raised = after.filter((a) => !before.includes(a));
  if (raised.length && !ctx.isRead && want === undefined) {
    const seen = `${ctx.where} raised an alert the recording never saw: ${clip(raised.join(' | '), 200)}`;
    if (!ctx.effectConfirmed) return { warnings, stop: seen };
    warnings.push(`${seen} — reported, not stopped: the step's recorded page changes appeared`);
    return { warnings };
  }
  if (!afterComplete) {
    if (!ctx.isRead && !raised.length) {
      unobserved = true;
      warnings.push(`${ctx.where}: the page's alerts could not be observed in full after the action — whether it raised an alert is unknown, not clear`);
    }
    if (want !== undefined && !raised.some((a) => a.includes(want))) {
      unobserved = true;
      warnings.push(`${ctx.where}: expected alert containing ${JSON.stringify(want)} could not be observed in full`);
    }
    return unobserved ? { warnings, unobserved } : { warnings };
  }
  if (want !== undefined && !raised.some((a) => a.includes(want))) {
    warnings.push(`${ctx.where}: expected alert containing ${JSON.stringify(want)}`);
  }
  return { warnings };
}

/**
 * A soft-matched precondition needs the page's structural fingerprint to
 * agree before a run proceeds on it. Same-template-different-record pages
 * measured 0.94–1.0 in the swg sweeps; the different-template fixture pair
 * measures 0.57.
 */
const SOFT_MATCH_MIN_SIMILARITY = 0.8;

interface PreconditionVerdict {
  refuse?: string;
  /** The url is the same page shape with 1–2 disagreeing segments, and the run proceeds on it. */
  soft?: { diffs: UrlSegDiff[]; generalised: string };
  warnings: string[];
}

/**
 * What a caller knows about the page's structural fingerprint when it asks
 * where a segment starts:
 *  - a number: the cosine similarity it measured between the recording's
 *    fingerprint and the live page;
 *  - null: the recording kept NO fingerprint, so there is nothing to measure
 *    against and the url is the only evidence there is;
 *  - 'unmeasured': the recording kept one and this caller CANNOT measure it
 *    (a compiled artifact from before the vector travelled in the spec, with
 *    only a `fingerprinted` flag). Evidence exists that the caller cannot
 *    consult, which is not the same as no evidence.
 *
 * Both runners measure the same way (src/execution/fingerprint.ts): the
 * cosine of the recorded vector and the live page's fingerprint, where a page
 * that could not be read gives null and the url alone decides. (No call is
 * spelled out here: the emitter embeds a module whose export this text names.)
 */
type FingerprintSimilarity = number | null | 'unmeasured';

/**
 * Where a segment starts. A strict url match passes. Same page shape with 1–2
 * disagreeing segments is likely an environment-minted id (an Odoo action id,
 * a Grafana uid): proceed optimistically instead of refusing — a hard fail
 * here is what turned a one-segment difference into a dead flow, and it also
 * makes the volatility evidence uncollectible. But "likely" is not evidence,
 * so when the caller measured the page's structural fingerprint against the
 * recording's (`similarity`), that second gate decides: a different RECORD of
 * the same template fingerprints close; a different TEMPLATE does not. Only a
 * close page proceeds.
 *
 * With no fingerprint recorded (null) the url alone decides and a soft match
 * proceeds, as the daemon does for such a skill. When a fingerprint WAS
 * recorded but this caller cannot measure it ('unmeasured'), a soft match is
 * refused: the daemon would have consulted the fingerprint here, and a runner
 * that cannot must not proceed on less evidence than the daemon requires —
 * only a strict match passes. That is an old compiled artifact's case; the
 * emitter says so per segment (the `unmeasured-precondition` diagnostic).
 *
 * A segment whose first step navigates carries its own precondition and must
 * not be asked this at all — that is the caller's `navigatesItself` rule.
 */
function preconditionVerdict(
  pattern: string,
  url: string,
  params: Record<string, string>,
  similarity: FingerprintSimilarity,
): PreconditionVerdict {
  if (urlMatches(pattern, url, params)) return { warnings: [] };
  const soft = softUrlMatch(pattern, url, params);
  const structurallySame = similarity === null || (typeof similarity === 'number' && similarity >= SOFT_MATCH_MIN_SIMILARITY);
  if (!soft || !structurallySame) {
    const because =
      !soft || structurallySame
        ? ''
        : similarity === 'unmeasured'
          ? '; the url shape is close, but the recording fingerprinted this page and this runner cannot measure the live page against it — only a strict url match can pass here'
          : `; the url shape is close but the page structure is not — similarity ${similarity}`;
    return {
      warnings: [],
      refuse: `not on the page this procedure starts from (expects ${fillParams(pattern, params)}, browser is at ${describeUrl(url, pattern)}${because})`,
    };
  }
  return {
    soft: { diffs: soft.diffs, generalised: soft.generalised },
    warnings: [`start url differs from the recorded pattern in ${soft.diffs.length} segment(s) (${describeDiffs(soft.diffs)}) — proceeding optimistically`],
  };
}

/**
 * Whether every marker is BOUND: each slot it names has a nonempty value in
 * `params`, and the filled text is nonempty with no marker left in it. An
 * unbound marker proves nothing, so a goal check over one must fail rather
 * than pass — and a slot bound to '' (a derived value the run never minted)
 * renders `Order {{d1}}` as `Order `, which a page shows for every order. Both
 * runners ask this at run time; a compile-time check cannot see the value.
 */
function markersBound(markers: string[], params: Record<string, string>): boolean {
  return markers.every((marker) => {
    for (const m of marker.matchAll(/\{\{([vd]\d+)\}\}/g)) {
      if (!params[m[1]]) return false;
    }
    const filled = fillParams(marker, params);
    return Boolean(filled.trim()) && !/\{\{/.test(filled);
  });
}

// Shared execution source: browser.ts. Regenerate to update.
/** Browser execution shared by replay and the standalone spec bundle. */

/**
 * What is known about an action once it has been attempted (ROBUSTNESS.md
 * finding 2). The four are different facts, and every caller that decides
 * whether something may be tried again needs to tell them apart:
 *  - `not-dispatched`: there is PROOF nothing reached the app (Playwright's
 *    actionability wait gave up before the pointer event, the control is
 *    disabled, the deadline ran out before a tier began). Another attempt
 *    repeats nothing.
 *  - `dispatched`: the action went out; whether it had its effect is for the
 *    effect gates to say.
 *  - `effect-verified`: it went out and its expected effect was seen.
 *  - `unknown`: it may or may not have reached the app (the page was torn down
 *    under it, or the failure carries no proof either way). Never repeat it.
 *
 * Carried on the error a failed action throws (`actionFailure`), never parsed
 * out of its words: the message is written for a model and a person, and is
 * free to change.
 */
type ActionOutcome = 'not-dispatched' | 'dispatched' | 'effect-verified' | 'unknown';

/** Which way a dispatched action went out. */
type DispatchVia = 'actionable' | 'forced' | 'synthetic' | 'rerender-window' | 'native';

/** Why an action failed, for a caller that wants more than its outcome. */
type ActionFailureReason = 'disabled' | 'teardown' | 'strict' | 'never-attached' | 'rerender' | 'timeout' | 'deadline';

/** An error that says what is known about the action that threw it. */
interface ActionFailure extends Error {
  actionOutcome: 'not-dispatched' | 'unknown';
  actionReason: ActionFailureReason;
}

/**
 * Tag a failure with its outcome. Given an Error, that same object is tagged
 * and returned — a caller that compares identity (or reads Playwright's own
 * message) sees the error it would have seen untagged.
 */
function actionFailure(outcome: 'not-dispatched' | 'unknown', reason: ActionFailureReason, error: string | Error): ActionFailure {
  const failure = (typeof error === 'string' ? new Error(error) : error) as ActionFailure;
  failure.actionOutcome = outcome;
  failure.actionReason = reason;
  return failure;
}

/**
 * The outcome a thrown error establishes. Only a tagged failure can say
 * `not-dispatched`: anything else carries no proof that nothing happened, so
 * it is `unknown`, the direction that never repeats an action.
 */
function outcomeOfError(err: unknown): 'not-dispatched' | 'unknown' {
  const tagged = err && typeof err === 'object' ? (err as Partial<ActionFailure>).actionOutcome : undefined;
  return tagged === 'not-dispatched' ? 'not-dispatched' : 'unknown';
}

/** The outcome as it reads beside a failure: `[outcome: not dispatched]`. */
function outcomeLabel(outcome: ActionOutcome): string {
  return `[outcome: ${outcome.replace(/-/g, ' ')}]`;
}

/**
 * What a click is told about the action it belongs to (src/execution/action.ts
 * `beginAction`): how much of the action's deadline is left, which clamps every
 * tier, and where to report the way the click went out.
 */
interface ClickObservation {
  remaining(): number;
  dispatched?(via: DispatchVia): void;
}

type ClickOpts = { timeout: number; dbl?: boolean; obs?: ClickObservation };
type ClickAct = (o: { timeout: number; force?: boolean }) => Promise<void>;

/**
 * One way to land a click. `note` is appended to the result so the agent (and
 * a post-mortem) can see which tier did the work.
 */
interface ClickTier {
  note: string;
  via: DispatchVia;
  run: (loc: Locator, opts: ClickOpts, act: ClickAct) => Promise<void>;
}

/**
 * The tiers a click falls through, in order. Each is tried when the one
 * before it failed; the window tier (fireWhenAttached) comes last and its own
 * error is what the agent sees, because it is the only tier that can explain
 * WHY nothing landed.
 */
const CLICK_TIERS: ClickTier[] = [
  // Playwright's own click, actionability checks and all.
  { note: '', via: 'actionable', run: (_loc, opts, act) => act({ timeout: opts.timeout }) },
  // Scroll into view and skip the checks: a control under a sticky header,
  // or one an overlay covers in a way the app treats as fine.
  {
    note: ' (forced past actionability checks)',
    via: 'forced',
    run: async (loc, opts, act) => {
      await loc.scrollIntoViewIfNeeded({ timeout: opts.timeout }).catch(() => {});
      await act({ timeout: opts.timeout, force: true });
    },
  },
  // A synthetic event straight at the element: React's delegated handlers see
  // it even when the element is not "clickable" by Playwright's rules.
  { note: ' (dispatched DOM event — element was not normally clickable)', via: 'synthetic', run: (loc, opts) => loc.evaluate(fireClick, Boolean(opts.dbl), { timeout: opts.timeout }) },
];

/**
 * The budget one tier (or the window tier) may spend: its own timeout, cut to
 * what is left of the action's deadline. Never 0 — Playwright reads a zero
 * timeout as "no timeout" — so a spent deadline is reported by the caller
 * before the tier starts, not passed down.
 */
function tierBudget(opts: ClickOpts): number {
  const left = opts.obs ? Math.floor(opts.obs.remaining()) : Infinity;
  return Math.min(opts.timeout, left);
}

/** The refusal for a deadline that ran out before the next way of clicking could start: nothing was dispatched. */
function deadlineSpent(label: string, because: string): ActionFailure {
  const cause = because ? ` (after: ${because.split('\n')[0].slice(0, 120)})` : '';
  return actionFailure(
    'not-dispatched',
    'deadline',
    `${label === 'clicked' ? 'click' : 'double-click'} NOT dispatched: the action's deadline ran out before the control could be clicked${cause}. Observe the page — something it was waiting on (an overlay, a load) never finished.`,
  );
}

async function robustClick(loc: Locator, opts: ClickOpts): Promise<string> {
  const label = opts.dbl ? 'double-clicked' : 'clicked';
  const act: ClickAct = (o) => (opts.dbl ? loc.dblclick(o) : loc.click(o));
  let firstFailure = '';
  for (const tier of CLICK_TIERS) {
    // Every tier before this one failed in a way that proves nothing went out
    // (the throws below end the loop otherwise), so a deadline spent here is
    // a click that was never dispatched.
    const budget = tierBudget(opts);
    if (budget < 1) throw deadlineSpent(label, firstFailure);
    try {
      await tier.run(loc, { ...opts, timeout: budget }, act);
      opts.obs?.dispatched?.(tier.via);
      return `${label}${tier.note}`;
    } catch (err) {
      const failure = err instanceof Error ? err.message : String(err);
      firstFailure ||= failure;
      // Two or more matches is the agent's problem to fix, not a tier's.
      if (/strict mode violation/i.test(failure)) throw err instanceof Error ? actionFailure('not-dispatched', 'strict', err) : err;
      // A DISABLED control refused the click by design, and the tiers below
      // do not get past that: a forced click on a disabled button dispatches
      // nothing the app handles, yet returned "clicked (forced past
      // actionability checks)". Asked only once Playwright's own click has
      // failed, so an ordinary click costs nothing extra; an element that
      // cannot be asked (gone, re-rendering) goes on down the tiers as before.
      if (tier === CLICK_TIERS[0] && (await loc.isDisabled({ timeout: DISABLED_PROBE_MS }).catch(() => false))) {
        throw actionFailure(
          'not-dispatched',
          'disabled',
          `${label === 'clicked' ? 'click' : 'double-click'} NOT dispatched: the control is disabled, so the app would ignore it. ` +
            'Make whatever enables it true first (a required field, a selection, a finished load), then click it.',
        );
      }
      // The page went out from under the click. Whether it landed is unknown,
      // so no further tier may fire: see UNCERTAIN_DISPATCH.
      if (UNCERTAIN_DISPATCH.test(failure)) {
        throw actionFailure(
          'unknown',
          'teardown',
          `${label === 'clicked' ? 'click' : 'double-click'} outcome UNKNOWN: the page was torn down during the action (${failure.split('\n')[0].slice(0, 160)}). It may already have taken effect. Do not repeat it — observe the app's state and continue from what you find.`,
        );
      }
      // A control the app re-mounts on every render never passes the
      // attached→visible→stable check, and a forced click needs it attached
      // at the instant of the action just the same — so both tiers lose the
      // race and burn their full timeout (rpgr4-r2 spent 74 turns on
      // grafana's viz-picker toggle this way). Only Playwright's own detach
      // evidence sends a click straight to the window tier: its generic
      // timeout log reads "waiting for element to be visible, enabled and
      // stable" for EVERY stalled click, and matching on that routed 15
      // ordinary replay clicks per run past the tiers that had been landing
      // them (rpgr5).
      if (DETACHED.test(failure)) break;
    }
  }
  return fireWhenAttached(loc, opts, label, firstFailure);
}

/** How long robustClick asks whether a control that refused a click is disabled. */
const DISABLED_PROBE_MS = 500;

/** Playwright's own words for an element that left the DOM mid-action — never its generic actionability wording. */
const DETACHED = /element was detached|not attached to the DOM|element is not attached|element is not stable/i;

/**
 * Failures that mean the PAGE moved, not that the element was unready: the
 * context went away, the frame detached, the tab closed. Escalating through
 * the click tiers is safe only because an actionability timeout proves
 * Playwright never dispatched — it waits for visible/enabled/stable BEFORE
 * the pointer event, so nothing happened and trying harder repeats nothing.
 * These failures carry no such proof. They are the shape a click that
 * committed and then tore its own page down leaves behind, and a second,
 * forced, synthetic click would be a second commit. Stop instead, and say the
 * outcome is unknown rather than guessing either way.
 */
const UNCERTAIN_DISPATCH =
  /execution context was destroyed|target.*(?:has been|was) closed|target closed|browser has been closed|frame was detached|navigating and changing the content|page closed/i;

/** Runs in the page: a synthetic click (React's delegated handlers see it). */
function fireClick(el: Element, dbl: boolean): void {
  const fire = (type: string) => el.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true, view: window }));
  fire('click');
  if (dbl) {
    fire('click');
    fire('dblclick');
  }
}

/**
 * Click a control that keeps re-mounting. Polls for the element and, the
 * moment a handle resolves, dispatches the click in the same tick — no
 * actionability wait at all. A flickering element is attached for a good
 * fraction of every cycle; the normal tiers never act inside that window.
 * If no window is found within the budget, the error says what the agent is
 * fighting and what to try instead of the same click again.
 */
async function fireWhenAttached(loc: Locator, opts: ClickOpts, label = 'clicked', because = ''): Promise<string> {
  // The first line of the failure that sent us here rides along in the
  // result, so a post-mortem can see WHY a click took this route.
  const cause = because ? ` after: ${because.split('\n')[0].slice(0, 120)}` : '';
  // Cut to the action's deadline like every tier before it; one already spent
  // means no window was ever tried.
  const budget = tierBudget(opts);
  if (budget < 1) throw deadlineSpent(label, because);
  const deadline = Date.now() + budget;
  let polls = 0;
  let attached = 0;
  while (Date.now() < deadline) {
    polls++;
    const handle = await loc.elementHandle({ timeout: 100 }).catch((err: unknown) => {
      const message = err instanceof Error ? err.message : String(err);
      if (err instanceof Error && /strict mode violation/i.test(message)) throw actionFailure('not-dispatched', 'strict', err);
      if (err instanceof Error && UNCERTAIN_DISPATCH.test(message)) throw actionFailure('unknown', 'teardown', err);
      if (/strict mode violation/i.test(message) || UNCERTAIN_DISPATCH.test(message)) throw err;
      return null;
    });
    if (handle) {
      attached++;
      try {
        await handle.evaluate(fireClick, Boolean(opts.dbl));
        opts.obs?.dispatched?.('rerender-window');
        return `${label} (dispatched during a re-render window${cause} — the element re-mounts continuously, so a normal click could not land; if the app did not respond, it may need a keyboard route or a wait_for on the state that settles it)`;
      } catch (err) {
        // The element going again between resolve and fire is the ordinary
        // case: nothing was dispatched, so the next window is safe. A context
        // that was DESTROYED is not — the click may have landed and navigated
        // the page, and polling on would fire it a second time.
        const message = err instanceof Error ? err.message : String(err);
        if (UNCERTAIN_DISPATCH.test(message)) {
          throw actionFailure(
            'unknown',
            'teardown',
            `${label === 'clicked' ? 'click' : 'double-click'} outcome UNKNOWN: dispatched into a page that was being torn down (${message.split('\n')[0].slice(0, 160)}). It may already have taken effect. Do not repeat it — observe the app's state and continue from what you find.`,
          );
        }
      } finally {
        await handle.dispose().catch(() => {});
      }
    }
    await new Promise((r) => setTimeout(r, 25));
  }
  // Every window either never came or was gone before the event fired: nothing went out.
  throw actionFailure(
    'not-dispatched',
    attached ? 'rerender' : 'never-attached',
    attached
      ? `target re-rendered continuously: attached on ${attached} of ${polls} polls but never long enough to click. The app re-mounts it on every render. Do not repeat this click — wait_for an element that appears once the state settles, or drive it by keyboard (focus a stable neighbour, Tab to it, press Enter).`
      : `target was never attached during ${Math.round(budget / 1000)}s of polling after an initial detach — it was removed by a re-render. Re-snapshot and locate it afresh rather than repeating this click.`,
  );
}

/**
 * React-safe input helpers (friction #5). Plain `locator.fill()` bypasses the
 * native value setter, so React controlled components never see the change
 * (or number inputs end up appending). We set the value through the native
 * prototype setter and dispatch input/change so React's synthetic event
 * system picks it up. Invisible to the agent: `fill` just works.
 */
async function reactSafeFill(locator: Locator, value: string): Promise<void> {
  await locator.waitFor({ state: 'visible', timeout: 10_000 });
  await locator.scrollIntoViewIfNeeded().catch(() => {});
  await locator.click({ timeout: 5_000 }).catch(() => {}); // focus; some widgets need it
  const handled = await locator.evaluate((el, val) => {
    const input = el as HTMLInputElement | HTMLTextAreaElement;
    if (!('value' in input)) return false;
    const proto =
      input instanceof HTMLTextAreaElement
        ? HTMLTextAreaElement.prototype
        : input instanceof HTMLInputElement
          ? HTMLInputElement.prototype
          : null;
    if (!proto) return false;
    const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
    if (!setter) return false;
    setter.call(input, ''); // clear-then-set: number inputs otherwise append
    input.dispatchEvent(new Event('input', { bubbles: true }));
    setter.call(input, val);
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    return true;
  }, value);
  if (!handled) {
    // contenteditable or non-standard widget — fall back to Playwright fill
    await locator.fill(value);
  }
}

/**
 * Select an option and fire change through the native setter, for React
 * controlled <select> elements.
 */
async function reactSafeSelect(locator: Locator, value: string, fallbackValue?: string): Promise<string[]> {
  // Look before waiting: an option present NOW is chosen at once, and the
  // recorded fallback value is tried without first sitting out the label's
  // full timeout. Only when nothing matches yet does the label wait for
  // options that may still be loading.
  const present = await locator
    .evaluate(
      (el, [v, f]) => {
        if (!(el instanceof HTMLSelectElement)) return null;
        const opts = Array.from(el.options);
        if (opts.some((o) => o.label.trim() === v)) return 'label';
        if (opts.some((o) => o.value === v)) return 'value';
        if (f && opts.some((o) => o.value === f)) return 'fallback';
        return null;
      },
      [value, fallbackValue ?? ''] as [string, string],
    )
    .catch(() => null);
  if (present === 'fallback') return locator.selectOption(fallbackValue!);
  if (present === 'value') return locator.selectOption(value);
  const result = await locator.selectOption({ label: value }).catch(() => null);
  if (result) return result;
  return locator.selectOption(value); // fall back to value/index matching
}

/**
 * Hover with synthetic mouse events for autocomplete/listbox widgets that key
 * off mouseenter rather than CSS :hover.
 */
async function syntheticHover(locator: Locator): Promise<void> {
  await locator.hover().catch(() => {});
  await locator.evaluate((el) => {
    for (const type of ['pointerover', 'mouseover', 'mouseenter', 'mousemove']) {
      el.dispatchEvent(new MouseEvent(type, { bubbles: type !== 'mouseenter' }));
    }
  });
}

/**
 * Tools whose effect may be a navigation the app performs on the answer to a
 * request — or a second one after the first (an app that routes to a
 * placeholder id and then replaces it with the real one). Daemon replay waits
 * on the url after each of them before it reads the step's effect (tools.ts
 * runStep, for the state-changing ones); the artifact waits in the step's
 * settle phase. Both through `urlHeldStill` below.
 */
const NAVIGATING_ACTIONS: readonly string[] = ['click', 'dblclick', 'press', 'submit', 'select'];

/**
 * The window a session records in when it is given no other: `--viewport` and
 * `--device` choose another (daemon/browser.ts `resolveBrowserProfile`).
 */
const RECORDING_VIEWPORT = { width: 1280, height: 900 } as const;

/**
 * The browser a flow was recorded in: its window, and for an emulated device
 * the rest of what Playwright's device descriptor sets. Stored on the flow
 * (`Flow.browser`), carried into the compiled artifact (`RECORDED_BROWSER`),
 * and judged at run time by `profileMismatch`.
 *
 * WHY IT TRAVELS. A page's layout is part of what a recording captured: a
 * `point` candidate is coordinates in this window, and an app that lays out by
 * size (Odoo's list columns and form panes, a responsive nav that becomes a
 * menu button) renders a different page in another one — a different
 * procedure, not merely different pixels. Playwright Test's default window is
 * 1280×720, and fwod39's compiled spec ran there: its 02-create reads found
 * nothing, a click fell to a point candidate, and 03-open resolved no quantity
 * input — steps daemon replay ran cleanly twice at 1280×900. A mobile flow is
 * the same problem from the other side, and a desktop default would override
 * the device a caller's project configured to exercise it.
 *
 * `device` is the Playwright device name it was resolved from, for people;
 * the other fields are what was applied. Chromium only: a descriptor's
 * `defaultBrowserType` (webkit, for iPhones) is not honoured.
 */
interface BrowserProfile {
  device?: string;
  viewport: { width: number; height: number };
  deviceScaleFactor?: number;
  isMobile?: boolean;
  hasTouch?: boolean;
  userAgent?: string;
}

/** What a flow recorded before profiles were stored was recorded in. */
const DEFAULT_BROWSER_PROFILE: BrowserProfile = { viewport: { ...RECORDING_VIEWPORT } };

/** What a runner can observe of the browser it was handed. `null` viewport: the page has none (it follows the window). */
interface LiveBrowser {
  viewport: { width: number; height: number } | null;
  userAgent?: string;
  hasTouch?: boolean;
}

/**
 * The device facts profileMismatch compares, read off the live page the same
 * way by both runners. A page that cannot be evaluated yet (about:blank before
 * the first navigation evaluates fine; a crashed one does not) gives only its
 * size, and the facts it could not read are not compared.
 */
async function readLiveBrowser(page: Pick<Page, 'viewportSize' | 'evaluate'>): Promise<LiveBrowser> {
  const facts = await page
    .evaluate(() => ({ userAgent: navigator.userAgent, hasTouch: navigator.maxTouchPoints > 0 }))
    .catch(() => ({}));
  return { viewport: page.viewportSize(), ...facts };
}

/**
 * Why the browser a flow is about to run in is not the one it was recorded in,
 * or null when it is. Width and height, the user agent and touch support are
 * compared — the device facts a page can act on; scale factor and `isMobile`
 * cannot be read back from a page and are applied, never judged. A field the
 * recording did not set is not compared.
 *
 * Both runners warn with it and neither refuses: a flow run at another size
 * may still work (role and text candidates survive most reflows), and when it
 * does not, the failure then says why.
 */
function profileMismatch(recorded: BrowserProfile, live: LiveBrowser): string | null {
  const diffs: string[] = [];
  const size = (v: { width: number; height: number }) => `${v.width}x${v.height}`;
  if (live.viewport && (live.viewport.width !== recorded.viewport.width || live.viewport.height !== recorded.viewport.height)) {
    diffs.push(`window ${size(live.viewport)} (recorded ${size(recorded.viewport)})`);
  }
  if (recorded.userAgent !== undefined && live.userAgent !== undefined && live.userAgent !== recorded.userAgent) {
    diffs.push('a different user agent');
  }
  if (recorded.hasTouch !== undefined && live.hasTouch !== undefined && live.hasTouch !== recorded.hasTouch) {
    diffs.push(live.hasTouch ? 'touch input (recorded without)' : 'no touch input (recorded with)');
  }
  if (!diffs.length) return null;
  const was = recorded.device ? ` on ${recorded.device}` : '';
  return `the browser has ${diffs.join(', ')} — the flow was recorded${was} at ${size(recorded.viewport)}, and locators that depend on layout may not hold`;
}

function isNavigatingAction(tool: string): boolean {
  return NAVIGATING_ACTIONS.includes(tool);
}

/** How long a click's late navigation is given before its effect is captured as final. */
const LATE_NAV_MS = 1_500;
/** A url that has not moved for this long, after moving, is where the step left the page. */
const URL_STILL_MS = 500;
/**
 * How long "no request in flight" must hold before it means "no navigation
 * coming". Zero: the DOM settle that precedes this wait (≥250ms quiet) is the
 * grace, and a request the click started is already counted by then.
 */
const LATE_NAV_GRACE_MS = 0;

/**
 * Where a navigating tool left the url once it has held still. A late
 * navigation rides on a request the tool started, so a page with no request
 * in flight and the url it began on is not going anywhere: the wait ends
 * there rather than at the deadline. Set 30's zero-model replays ran at
 * twice set 28's wall clock because every non-navigating click sat out the
 * full LATE_NAV_MS (78 actions, ~30s of nothing on repairdesk).
 *
 * A url that moved and then moves AGAIN is followed: the value a step's
 * derived binding needs is on the url the step settles on, and a DOM settle
 * alone cannot see a redirect that changes nothing on the page first.
 */
async function urlHeldStill(
  page: Pick<Page, 'url'>,
  beforeUrl: string,
  inFlightNow: () => number,
  timing: { lateNavMs?: number; stillMs?: number; graceMs?: number; pollMs?: number } = {},
): Promise<string> {
  const lateNavMs = timing.lateNavMs ?? LATE_NAV_MS;
  const stillMs = timing.stillMs ?? URL_STILL_MS;
  const graceMs = timing.graceMs ?? LATE_NAV_GRACE_MS;
  const pollMs = timing.pollMs ?? 100;
  const start = Date.now();
  const deadline = start + lateNavMs;
  let seen = page.url();
  let stillSince = start;
  // Check first, sleep after: the caller has already let the DOM settle, so
  // a request the click started is registered by now, and the common case
  // (a click that navigates nowhere) should cost nothing here.
  for (;;) {
    const now = page.url();
    if (now !== seen) {
      seen = now;
      stillSince = Date.now();
    } else if (now !== beforeUrl) {
      if (Date.now() - stillSince >= stillMs) break;
    } else if (Date.now() - start >= graceMs && inFlightNow() === 0) {
      break; // nothing asked of the server, so nothing to route on
    }
    if (Date.now() >= deadline) break;
    await new Promise((r) => setTimeout(r, pollMs));
  }
  return seen;
}

const SETTLE_QUIET_MS = 250;
const SETTLE_MAX_MS = 2_000;
/**
 * How long a page gets to show it is busy before it is called quiet. The
 * quiet window used to be the floor too — 250ms per step even on a static
 * page, ~20s across an 80-step replay that was otherwise at the engine's
 * floor. Now the full quiet window is demanded only once a mutation shows.
 */
const SETTLE_PROBE_MS = 60;

/** Resolve once no DOM mutation has happened for SETTLE_QUIET_MS, or after `maxMs` (SETTLE_MAX_MS). */
async function settleDom(page: Page, maxMs: number = SETTLE_MAX_MS): Promise<void> {
  await domQuiet(page, { maxMs });
}

/**
 * settleDom that says what it saw: whether the DOM mutated at all while it
 * watched, and how long before it returned the last mutation was. An action's
 * observation (src/execution/action.ts) reads the second as evidence — a page
 * that changed a moment ago may be about to ask the server for something.
 * Null when the page could not be evaluated (navigating, detached, closed).
 */
async function domQuiet(
  page: Page,
  timing: { probeMs?: number; quietMs?: number; maxMs?: number } = {},
): Promise<{ mutated: boolean; sinceMs: number } | null> {
  try {
    return await page.evaluate(
      ({ probe, quiet, max }) =>
        new Promise<{ mutated: boolean; sinceMs: number }>((resolve) => {
          let last = 0;
          const finish = () => {
            observer.disconnect();
            clearTimeout(timer);
            clearTimeout(stop);
            resolve({ mutated: last > 0, sinceMs: last > 0 ? Date.now() - last : 0 });
          };
          let timer = setTimeout(finish, probe);
          const stop = setTimeout(finish, max);
          const observer = new MutationObserver(() => {
            last = Date.now();
            clearTimeout(timer);
            timer = setTimeout(finish, quiet);
          });
          observer.observe(document, { childList: true, subtree: true, attributes: true, characterData: true });
        }),
      { probe: timing.probeMs ?? SETTLE_PROBE_MS, quiet: timing.quietMs ?? SETTLE_QUIET_MS, max: timing.maxMs ?? SETTLE_MAX_MS },
    );
  } catch {
    // navigating / detached — the locator resolution will report it
    return null;
  }
}

// Shared execution source: snapshot.ts. Regenerate to update.
/**
 * The page-observation model both execution targets share: one STRUCTURED
 * observation of the live page (roles, names, values, states, where each
 * element sits, and how much of the page the look actually covered), the
 * snapshot-line dialects rendered from it (`- role "name": value`), and the
 * matchers that read those lines. The daemon imports this module (through
 * daemon/diff.ts and skills/replay.ts); a compiled `.flow.ts` artifact embeds
 * its exact source (spec/runtime-source.ts), so both runners ask their effect
 * and identity questions of the same observation. It must stay
 * self-contained: nothing but a sibling shared module or a Playwright type may
 * be imported.
 *
 * WHY TWO DIALECTS. Recorded lines are persisted — in recordings, in stored
 * step expectations, in compiled artifacts — and matched as substrings. The
 * first dialect named a `<label for>` input `""`, walked no frame or shadow
 * root, and carried no disabled state; fixing any of that in place would make
 * every stored line for such an element disagree with the live page. So a
 * recorded step says which dialect its lines are in (StepExpectation
 * .lineDialect, absent = 1), and each runner renders the live observation in
 * THAT dialect before comparing. Dialect 1 is byte-identical to the capture it
 * replaced (test/observation.browser.test.ts keeps the old function as its
 * oracle); dialect 2 is what new recordings are written in.
 *
 * WHY COVERAGE. A capture that walked 4,000 of 9,000 elements, stopped at the
 * line cap, could not read a visible iframe, or looked at a virtualised grid
 * showing 20 of 340 rows, has NOT established that something is absent. Every
 * absence question goes through `presence`, which answers 'unknown' there
 * instead of 'absent'.
 */

/** Which rendering of an observation a set of recorded lines is in. Absent on a stored step means 1. */
type LineDialect = 1 | 2;

/** What new recordings are written in. */
const CURRENT_DIALECT = 2 as const;

/** What a capture is allowed to walk and return — passed INTO the page, since observeDocumentInPage is serialised. */
const SNAPSHOT_LIMITS = { maxAlerts: 5, maxAlertChars: 200, maxNodes: 4_000, maxLines: 400 };

/**
 * The budget open shadow roots are walked under, ON TOP of SNAPSHOT_LIMITS: a
 * separate budget, so the dialect-1 walk (and so every dialect-1 line) is
 * untouched by how much shadow content a page carries.
 */
const SHADOW_LIMITS = { maxExtraNodes: 4_000, maxExtraLines: 400 };

/** A capture that has not answered in this long is a navigating or hung page: null, never a wait. */
const CAPTURE_TIMEOUT_MS = 2_000;

/** How many visible child frames one observation evaluates; a visible frame past this is a coverage gap. */
const MAX_FRAMES = 10;

/** The least time frames are given once the main document has answered, however long it took. */
const FRAME_MIN_BUDGET_MS = 500;

/** Where an element sits: `frame` is the child-index path from the main frame ([] = main document); `shadow` the open shadow hosts above it, as `tag#id`. */
interface NodeContext {
  frame: number[];
  shadow: string[];
}

interface ObservedNode {
  role: string;
  /** The dialect-2 name: dialect 1's, except that an element with no name of its own is named by its `<label>`s and a shadow-scoped aria-labelledby resolves. */
  name: string;
  /** The dialect-1 name, exactly as the first capture computed it. */
  legacyName: string;
  /** Present when the element carries a nonempty string value (not for a checkbox or radio). */
  value?: string;
  /** Present for a checkbox or radio input: whether it is checked. */
  checked?: boolean;
  disabled?: boolean;
  context: NodeContext;
  /** Part of the dialect-1 walk: the main document, light DOM, within SNAPSHOT_LIMITS. */
  legacy: boolean;
}

interface ObservedAlert {
  text: string;
  legacy: boolean;
}

interface ObservationCoverage {
  nodesWalked: number;
  nodeCap: number;
  /** More elements existed than any walk was allowed to look at. */
  nodesTruncated: boolean;
  /** A walk stopped at its line cap. */
  linesTruncated: boolean;
  /** More visible live regions existed than were kept. */
  alertsTruncated: boolean;
  shadowRootsWalked: number;
  frames: {
    observed: number;
    /** Not rendered (no box): nothing in them is on screen, so not a gap. */
    hidden: number;
    /** Visible, or of unknown visibility, and past MAX_FRAMES: a gap. */
    overCap: number;
    /** Visible and could not be evaluated: a gap. */
    inaccessible: { path: number[]; url: string; reason: string }[];
  };
  /** A collection the page says is larger than what it rendered (aria-rowcount, aria-setsize) or still loading (aria-busy). */
  collections: { partial: boolean; evidence: string[] };
}

interface PageObservation {
  url: string;
  nodes: ObservedNode[];
  alerts: ObservedAlert[];
  coverage: ObservationCoverage;
}

/** One document's half of an observation, as the page function returns it; frames are the caller's. */
interface DocumentObservation {
  nodes: ObservedNode[];
  alerts: ObservedAlert[];
  coverage: Omit<ObservationCoverage, 'frames'>;
}

/** The answer to "is this on the page?": `unknown` when the look could not establish absence. */
type Presence = 'present' | 'absent' | 'unknown';

interface ObserveDocumentOptions {
  maxAlerts: number;
  maxAlertChars: number;
  maxNodes: number;
  maxLines: number;
  maxExtraNodes: number;
  maxExtraLines: number;
  /** This document is the main one, whose light-DOM walk is dialect 1's. False inside a frame. */
  legacy: boolean;
}

/**
 * Runs in the page (or a frame's document): the roles, names, values and
 * states currently on screen, plus live-region text and how much of the
 * document the walk covered. Deliberately hand-rolled rather than delegated
 * to ariaSnapshot — see daemon/diff.ts captureSignature. Everything it needs
 * is passed in: it is serialised into the page, so nothing at module level is
 * in scope there.
 *
 * ORDER IS WHAT KEEPS DIALECT 1 EXACT. Pass A is the first capture's loop,
 * unchanged — the first `maxNodes` elements of `querySelectorAll('*')`, the
 * line counter, the visibility and role rules, the name and value rules — so
 * the legacy nodes it produces render to the very lines it produced. Pass B
 * (open shadow roots) and the frames the caller adds come after, on their own
 * budgets, and are never legacy.
 */
function observeDocumentInPage(opts: ObserveDocumentOptions): DocumentObservation {
  const clean = (s: string | null | undefined) => (s ?? '').replace(/\s+/g, ' ').trim();

  const roleOf = (el: Element): string | null => {
    const explicit = clean(el.getAttribute('role'));
    if (explicit) return explicit.split(' ')[0];
    const tag = el.tagName.toLowerCase();
    const type = (el.getAttribute('type') || '').toLowerCase();
    if (tag === 'button') return 'button';
    if (tag === 'a') return el.hasAttribute('href') ? 'link' : null;
    if (tag === 'select') return el.hasAttribute('multiple') ? 'listbox' : 'combobox';
    if (tag === 'textarea') return 'textbox';
    if (tag === 'option') return 'option';
    if (tag === 'td' || tag === 'th') return 'cell';
    if (tag === 'tr') return 'row';
    if (tag === 'dialog') return 'dialog';
    if (/^h[1-6]$/.test(tag)) return 'heading';
    if (tag === 'input') {
      if (type === 'checkbox') return 'checkbox';
      if (type === 'radio') return 'radio';
      if (type === 'range') return 'slider';
      if (type === 'search') return 'searchbox';
      if (type === 'number') return 'spinbutton';
      if (type === 'submit' || type === 'button' || type === 'reset') return 'button';
      if (type === 'hidden' || type === 'file') return null;
      return 'textbox';
    }
    return null;
  };

  // The attribute half of a name. `byRoot` resolves aria-labelledby ids in
  // the element's own root (a shadow root has its own id space); the first
  // capture resolved them in the owner document, and dialect 1 still does.
  const ownName = (el: Element, byRoot: boolean): string => {
    const labelledBy = el.getAttribute('aria-labelledby');
    const root = el.getRootNode() as Document | ShadowRoot;
    const lookup = (id: string) =>
      byRoot && typeof root.getElementById === 'function' ? root.getElementById(id) : el.ownerDocument.getElementById(id);
    const fromIds = labelledBy
      ? labelledBy
          .split(/\s+/)
          .map((id) => lookup(id)?.textContent ?? '')
          .join(' ')
      : '';
    return clean(
      el.getAttribute('aria-label') ||
        fromIds ||
        el.getAttribute('alt') ||
        el.getAttribute('title') ||
        el.getAttribute('placeholder'),
    );
  };

  // The text of the element's own <label>s — `for` and enclosing alike — with
  // the control's own subtree left out (a select's options are not its name).
  const labelsText = (el: Element): string => {
    const labels = (el as HTMLInputElement).labels;
    if (!labels || !labels.length) return '';
    const parts: string[] = [];
    for (const label of Array.from(labels)) {
      if (!label.contains(el)) {
        parts.push(label.textContent ?? '');
        continue;
      }
      let text = '';
      const walker = label.ownerDocument.createTreeWalker(label, NodeFilter.SHOW_TEXT);
      for (let t = walker.nextNode(); t; t = walker.nextNode()) if (!el.contains(t)) text += t.textContent ?? '';
      parts.push(text);
    }
    return clean(parts.join(' '));
  };

  const namesOf = (el: Element): { name: string; legacyName: string } => {
    const own = ownName(el, false);
    const labelledBy = el.hasAttribute('aria-labelledby');
    const own2 = labelledBy ? ownName(el, true) : own;
    let label: string | undefined;
    let text: string | undefined;
    const enclosing = () => (label ??= clean(el.closest('label')?.textContent));
    // Only a short subtree reads as this element's own name; anything longer is
    // a container's text and would make the line churn on unrelated changes.
    const inner = () => (text ??= clean((el as HTMLElement).innerText));
    const fallback = () => (enclosing() ? enclosing().slice(0, 80) : inner().length <= 80 ? inner() : '');
    const legacyName = own ? own.slice(0, 80) : fallback();
    let name: string;
    if (own2) name = own2.slice(0, 80);
    else {
      const labels = labelsText(el);
      name = labels ? labels.slice(0, 80) : fallback();
    }
    return { name, legacyName };
  };

  const describe = (el: Element, shadow: string[], legacy: boolean): ObservedNode | null => {
    const role = roleOf(el);
    if (!role) return null;
    if (el.getClientRects().length === 0) return null;
    const { name, legacyName } = namesOf(el);
    const node: ObservedNode = { role, name, legacyName, context: { frame: [], shadow }, legacy };
    const input = el as HTMLInputElement;
    if (input.type === 'checkbox' || input.type === 'radio') {
      node.checked = Boolean(input.checked);
    } else if (typeof input.value === 'string' && input.value) {
      node.value = clean(input.value).slice(0, 80);
    }
    if (el.matches(':disabled') || el.getAttribute('aria-disabled') === 'true') node.disabled = true;
    return node;
  };

  const LIVE_REGION = '[role=alert],[role=status]';
  const visibleText = (els: Element[]) =>
    els.map((el) => clean((el as HTMLElement).innerText).slice(0, opts.maxAlertChars)).filter((text) => text.length > 0);

  const coverage: DocumentObservation['coverage'] = {
    nodesWalked: 0,
    nodeCap: opts.maxNodes,
    nodesTruncated: false,
    linesTruncated: false,
    alertsTruncated: false,
    shadowRootsWalked: 0,
    collections: { partial: false, evidence: [] },
  };
  const nodes: ObservedNode[] = [];

  // Pass A: the dialect-1 walk, exactly as the first capture walked.
  const all = Array.from(document.querySelectorAll('*'));
  coverage.nodesTruncated = all.length > opts.maxNodes;
  const walked = all.slice(0, opts.maxNodes);
  let lines = 0;
  for (const el of walked) {
    if (lines >= opts.maxLines) {
      coverage.linesTruncated = true;
      break;
    }
    coverage.nodesWalked++;
    const node = describe(el, [], opts.legacy);
    if (node) {
      nodes.push(node);
      lines++;
    }
  }

  // Pass B: open shadow roots, on their own budget. A CLOSED root reports
  // `shadowRoot === null` and cannot be seen from script at all — it is
  // invisible here, and nothing can count it as a gap.
  let extraNodes = 0;
  let extraLines = 0;
  const shadowAlerts: Element[] = [];
  const hostKey = (el: Element) => `${el.tagName.toLowerCase()}${el.id ? `#${el.id}` : ''}`;
  const walkShadow = (host: Element, path: string[]): void => {
    const root = host.shadowRoot;
    if (!root) return;
    coverage.shadowRootsWalked++;
    const inner = [...path, hostKey(host)];
    for (const el of Array.from(root.querySelectorAll('*'))) {
      if (extraNodes >= opts.maxExtraNodes) {
        coverage.nodesTruncated = true;
        return;
      }
      extraNodes++;
      coverage.nodesWalked++;
      const node = extraLines < opts.maxExtraLines ? describe(el, inner, false) : null;
      if (node) {
        nodes.push(node);
        extraLines++;
      }
      if (extraLines >= opts.maxExtraLines && !node && roleOf(el)) coverage.linesTruncated = true;
      if (el.matches(LIVE_REGION) && el.getClientRects().length > 0) shadowAlerts.push(el);
      if (el.shadowRoot) walkShadow(el, inner);
    }
  };
  for (const el of walked) if (el.shadowRoot) walkShadow(el, []);

  const lightAlerts = Array.from(document.querySelectorAll(LIVE_REGION)).filter((el) => el.getClientRects().length > 0);
  coverage.alertsTruncated = lightAlerts.length > opts.maxAlerts || shadowAlerts.length > opts.maxAlerts;
  const alerts: ObservedAlert[] = [
    ...visibleText(lightAlerts.slice(0, opts.maxAlerts)).map((text) => ({ text, legacy: opts.legacy })),
    ...visibleText(shadowAlerts.slice(0, opts.maxAlerts)).map((text) => ({ text, legacy: false })),
  ];

  // A collection the page itself says is bigger than what it rendered: a
  // virtualised grid (aria-rowcount), a windowed listbox (aria-setsize), or
  // one still loading (aria-busy). What is not rendered cannot be found
  // absent.
  const evidence: string[] = [];
  const nameForEvidence = (el: Element) => clean(el.getAttribute('aria-label')) || ownName(el, true);
  for (const el of Array.from(document.querySelectorAll('[aria-rowcount]'))) {
    if (el.getClientRects().length === 0) continue;
    const total = parseInt(el.getAttribute('aria-rowcount') ?? '', 10);
    if (!Number.isFinite(total)) continue;
    const rendered = el.querySelectorAll('[role=row],tr').length;
    if (total === -1 || total > rendered) {
      evidence.push(`${roleOf(el) ?? el.tagName.toLowerCase()} '${nameForEvidence(el)}' ${rendered}/${total === -1 ? '?' : total}`);
    }
  }
  const sized = new Set<Element>();
  for (const item of Array.from(document.querySelectorAll('[aria-setsize]'))) {
    const parent = item.parentElement;
    if (!parent || sized.has(parent) || item.getClientRects().length === 0) continue;
    sized.add(parent);
    const total = parseInt(item.getAttribute('aria-setsize') ?? '', 10);
    if (!Number.isFinite(total)) continue;
    const rendered = Array.from(parent.children).filter((c) => c.hasAttribute('aria-setsize')).length;
    if (total === -1 || total > rendered) {
      evidence.push(`${roleOf(parent) ?? parent.tagName.toLowerCase()} '${nameForEvidence(parent)}' ${rendered}/${total === -1 ? '?' : total}`);
    }
  }
  for (const el of Array.from(document.querySelectorAll('[aria-busy="true"]'))) {
    const role = roleOf(el) ?? '';
    if (!/^(grid|treegrid|table|list|listbox|tree|feed|rowgroup)$/.test(role) || el.getClientRects().length === 0) continue;
    evidence.push(`${role} '${nameForEvidence(el)}' busy`);
  }
  coverage.collections = { partial: evidence.length > 0, evidence: evidence.slice(0, 5) };

  return { nodes, alerts, coverage };
}

function isDocumentObservation(value: unknown): value is DocumentObservation {
  const v = value as DocumentObservation | null;
  return Boolean(v && Array.isArray(v.nodes) && Array.isArray(v.alerts) && v.coverage && typeof v.coverage === 'object');
}

/** A promise's value, or why it did not produce one within `ms` — never a throw. */
async function within<T>(work: Promise<T>, ms: number): Promise<{ value: T } | { error: string }> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      work.then((value) => ({ value })),
      new Promise<{ error: string }>((resolve) => {
        timer = setTimeout(() => resolve({ error: `did not answer within ${ms}ms` }), Math.max(1, ms));
      }),
    ]);
  } catch (err) {
    return { error: (err instanceof Error ? err.message : String(err)).split('\n')[0].slice(0, 120) };
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Playwright's Frame, named through Page: the artifact imports only `Page`
 * (and `Locator`) from @playwright/test, so this module may not name a third
 * Playwright type.
 */
type PageFrame = ReturnType<Page['mainFrame']>;

/** A frame's child-index path from the main frame. */
function framePath(frame: PageFrame): number[] {
  const path: number[] = [];
  for (let f: PageFrame | null = frame; f; ) {
    const parent: PageFrame | null = f.parentFrame();
    if (!parent) break;
    path.unshift(parent.childFrames().indexOf(f));
    f = parent;
  }
  return path;
}

/**
 * The page's child frames, observed: each rendered frame's document through
 * the same page function (cross-origin frames included — Playwright evaluates
 * out-of-process iframes), under what is left of the capture deadline. A
 * frame with no box is hidden and skipped; a visible frame that cannot be
 * evaluated, or one past MAX_FRAMES, is recorded as a gap.
 */
async function observeFrames(
  page: Page,
  budgetMs: number,
): Promise<{ nodes: ObservedNode[]; alerts: ObservedAlert[]; frames: ObservationCoverage['frames']; documents: DocumentObservation['coverage'][] }> {
  const frames: ObservationCoverage['frames'] = { observed: 0, hidden: 0, overCap: 0, inaccessible: [] };
  const out = { nodes: [] as ObservedNode[], alerts: [] as ObservedAlert[], frames, documents: [] as DocumentObservation['coverage'][] };
  // A stand-in page (a unit test's) has no frame tree; a real page always does.
  if (typeof (page as Partial<Page>).frames !== 'function' || typeof (page as Partial<Page>).mainFrame !== 'function') return out;
  let children: PageFrame[];
  try {
    const main = page.mainFrame();
    children = page.frames().filter((f) => f !== main && !f.isDetached());
  } catch (err) {
    frames.inaccessible.push({ path: [], url: '', reason: `the frame tree could not be listed: ${err instanceof Error ? err.message.split('\n')[0] : String(err)}` });
    return out;
  }
  if (!children.length) return out;
  const deadline = Date.now() + budgetMs;
  const remaining = () => Math.max(1, deadline - Date.now());
  const url = (f: PageFrame) => {
    try {
      return f.url();
    } catch {
      return '';
    }
  };

  // Which are rendered. Checked for a bounded number of frames: a page with
  // dozens of iframes past that is not claimed to be covered.
  const checked = children.slice(0, MAX_FRAMES * 3);
  frames.overCap += children.length - checked.length;
  const visibility = await Promise.all(
    checked.map(async (frame) => {
      const seen = await within(
        (async () => {
          const handle = await frame.frameElement();
          try {
            const box = await handle.boundingBox();
            return Boolean(box && box.width > 0 && box.height > 0);
          } finally {
            await handle.dispose().catch(() => {});
          }
        })(),
        remaining(),
      );
      return { frame, seen };
    }),
  );
  const visible: PageFrame[] = [];
  for (const { frame, seen } of visibility) {
    if ('error' in seen) {
      if (frame.isDetached()) continue; // gone, not hidden from us
      frames.inaccessible.push({ path: framePath(frame), url: url(frame), reason: `its visibility could not be read (${seen.error})` });
    } else if (!seen.value) frames.hidden++;
    else if (visible.length >= MAX_FRAMES) frames.overCap++;
    else visible.push(frame);
  }

  const looks = await Promise.all(
    visible.map(async (frame) => ({
      frame,
      look: await within(frame.evaluate(observeDocumentInPage, { ...SNAPSHOT_LIMITS, ...SHADOW_LIMITS, legacy: false }), remaining()),
    })),
  );
  for (const { frame, look } of looks) {
    if ('error' in look || !isDocumentObservation(look.value)) {
      if (frame.isDetached()) continue;
      frames.inaccessible.push({ path: framePath(frame), url: url(frame), reason: 'error' in look ? look.error : 'it answered with something other than an observation' });
      continue;
    }
    const path = framePath(frame);
    frames.observed++;
    for (const node of look.value.nodes) out.nodes.push({ ...node, legacy: false, context: { ...node.context, frame: path } });
    for (const alert of look.value.alerts) out.alerts.push({ text: alert.text, legacy: false });
    out.documents.push(look.value.coverage);
  }
  return out;
}

/**
 * One structured look at the live page — the main document, its open shadow
 * roots and its rendered frames — or null when the main document cannot be
 * read (navigating, closed, a renderer that does not answer within
 * CAPTURE_TIMEOUT_MS). Null is "unavailable", never "empty". A frame that
 * cannot be read does not null the observation: it is recorded in the
 * coverage, which is what stops the observation proving an absence.
 */
async function observePage(page: Page): Promise<PageObservation | null> {
  const started = Date.now();
  const main = await within(page.evaluate(observeDocumentInPage, { ...SNAPSHOT_LIMITS, ...SHADOW_LIMITS, legacy: true }), CAPTURE_TIMEOUT_MS);
  // A page that answered with something other than a capture (a frame torn
  // down mid-evaluate) is as unreadable as one that did not answer.
  if ('error' in main || !isDocumentObservation(main.value)) return null;
  const doc = main.value;
  const framed = await observeFrames(page, Math.max(FRAME_MIN_BUDGET_MS, CAPTURE_TIMEOUT_MS - (Date.now() - started)));
  const coverage: ObservationCoverage = { ...doc.coverage, collections: { ...doc.coverage.collections, evidence: [...doc.coverage.collections.evidence] }, frames: framed.frames };
  for (const c of framed.documents) {
    coverage.nodesWalked += c.nodesWalked;
    coverage.shadowRootsWalked += c.shadowRootsWalked;
    coverage.nodesTruncated ||= c.nodesTruncated;
    coverage.linesTruncated ||= c.linesTruncated;
    coverage.alertsTruncated ||= c.alertsTruncated;
    coverage.collections.partial ||= c.collections.partial;
    coverage.collections.evidence.push(...c.collections.evidence);
  }
  coverage.collections.evidence = coverage.collections.evidence.slice(0, 5);
  let url = '';
  try {
    url = page.url();
  } catch {
    // a stand-in page with no url; the observation is still one
  }
  return { url, nodes: [...doc.nodes, ...framed.nodes], alerts: [...doc.alerts, ...framed.alerts], coverage };
}

const INTERACTIVE_ROLES =
  /\b(button|link|textbox|searchbox|combobox|checkbox|radio|switch|slider|spinbutton|menu|menubar|menuitem|option|tab|listbox|grid|row|cell|dialog|alertdialog|heading|alert|status)\b/;

/**
 * The per-line heuristic behind the daemon's filterInteractive; shared with
 * signature capture, so the lines a step is judged against are the same lines
 * the recording kept. Matches any ref, in-frame ones included — testing for
 * "[@e" silently dropped every line inside an iframe, so an embedded editor or
 * payment form was invisible in the snapshot the agent works from.
 */
function isInteractiveLine(line: string): boolean {
  return line.includes('[@') || INTERACTIVE_ROLES.test(line);
}

/**
 * An observation as snapshot lines, interactive lines only.
 *
 * Dialect 1 is the first capture's exact text: legacy nodes only (main
 * document, light DOM), the legacy name, ` [checked]` for a checked
 * checkbox/radio or `: value` otherwise. Dialect 2 is every node — shadow and
 * frame content included — with the dialect-2 name, ` [checked]`,
 * ` [disabled]`, then `: value`. Where an element sits (its frame, its shadow
 * host) is never part of the line text: a line says what is shown, and the
 * same control in an iframe reads as it does in the page.
 */
function renderLines(o: PageObservation, d: LineDialect): string[] {
  const out: string[] = [];
  for (const n of o.nodes) {
    if (d === 1) {
      if (!n.legacy) continue;
      let line = `- ${n.role} ${JSON.stringify(n.legacyName)}`;
      if (n.checked !== undefined) line += n.checked ? ' [checked]' : '';
      else if (n.value !== undefined) line += `: ${n.value}`;
      out.push(line);
      continue;
    }
    let line = `- ${n.role} ${JSON.stringify(n.name)}`;
    if (n.checked) line += ' [checked]';
    if (n.disabled) line += ' [disabled]';
    if (n.checked === undefined && n.value !== undefined) line += `: ${n.value}`;
    out.push(line);
  }
  return out.filter(isInteractiveLine);
}

/** The observation's live-region texts in a dialect: dialect 1 keeps the main document's light DOM only. */
function renderAlerts(o: PageObservation, d: LineDialect): string[] {
  return o.alerts.filter((a) => d === 2 || a.legacy).map((a) => a.text);
}

/**
 * Whether the observation covered enough of the page for a missing LINE to
 * mean absent: every element walked, no line cap reached, every rendered
 * frame read and none past the cap, and no collection the page says is only
 * partly rendered. A hidden frame is not a gap — nothing in it is on screen.
 */
function coverageComplete(c: ObservationCoverage): boolean {
  return !c.nodesTruncated && !c.linesTruncated && c.frames.inaccessible.length === 0 && c.frames.overCap === 0 && !c.collections.partial;
}

/** The same question for live regions: every visible alert kept, and every rendered frame read. */
function alertsComplete(c: ObservationCoverage): boolean {
  return !c.alertsTruncated && c.frames.inaccessible.length === 0 && c.frames.overCap === 0;
}

/** Why an observation is not complete, in a few words for a verdict message; '' when it is. */
function describeCoverage(c: ObservationCoverage): string {
  const parts: string[] = [];
  if (c.nodesTruncated) parts.push(`the element cap was reached (${c.nodesWalked} walked)`);
  if (c.linesTruncated) parts.push('the line cap was reached');
  if (c.frames.inaccessible.length) {
    parts.push(`${c.frames.inaccessible.length} visible frame(s) could not be read (${c.frames.inaccessible.map((f) => f.reason).slice(0, 2).join('; ')})`);
  }
  if (c.frames.overCap) parts.push(`${c.frames.overCap} frame(s) past the frame cap`);
  if (c.collections.partial) parts.push(`a collection is only partly rendered (${c.collections.evidence.join(', ')})`);
  if (c.alertsTruncated) parts.push('the alert cap was reached');
  return parts.join('; ');
}

/**
 * One look at the live page in a dialect — its lines, its live-region
 * alerts, and the coverage behind them — or null when the page cannot be
 * read. Null is "unavailable", never "empty": a caller deciding whether an
 * effect landed, or whether an alert was raised, must not read a failed look
 * as a clean one. The single capture `capturePageLines`, `captureLines` and
 * the alert observation (observe.ts liveAlerts) are views of, so the walk,
 * the caps and the timeout exist once.
 */
async function capturePage(page: Page, d: LineDialect = 1): Promise<{ lines: string[]; alerts: string[]; coverage: ObservationCoverage } | null> {
  const o = await observePage(page);
  return o ? { lines: renderLines(o, d), alerts: renderAlerts(o, d), coverage: o.coverage } : null;
}

/**
 * The lines the page shows right now, in a dialect (dialect 1 unless asked),
 * or null when the page cannot be read (see capturePage).
 */
async function capturePageLines(page: Page, d: LineDialect = 1): Promise<string[] | null> {
  const captured = await capturePage(page, d);
  return captured ? captured.lines : null;
}

/** The lines, and whether the look covered enough of the page for a missing line to mean absent. */
async function captureLines(page: Page, d: LineDialect): Promise<{ lines: string[]; complete: boolean; coverage: ObservationCoverage } | null> {
  const captured = await capturePage(page, d);
  return captured ? { lines: captured.lines, complete: coverageComplete(captured.coverage), coverage: captured.coverage } : null;
}

/** How many added lines a step diff keeps — the recorder's own cap, so a replay diff and an artifact diff carry the same evidence. */
const MAX_ADDED_LINES = 20;

/**
 * The lines a step ADDED, as the recorder diffs its before/after signatures:
 * every after-line not present before, capped. Null when either capture
 * failed — a diff needs both legs, and a missing leg is not an empty change.
 */
function addedLines(before: string[] | null, after: string[] | null): string[] | null {
  if (before === null || after === null) return null;
  return after.filter((l) => !before.includes(l)).slice(0, MAX_ADDED_LINES);
}

interface LineShowsOptions {
  /**
   * Identity matching: the want must sit at a letter/digit boundary on both
   * sides (see IDENTITY_EDGE) instead of anywhere inside a longer run of
   * characters. Only for "is this the right RECORD" — the effect gate asks
   * whether a change LANDED, which is a substring question and stays one.
   */
  whole?: boolean;
}

const normWs = (s: string) => s.replace(/\s+/g, ' ').trim();

/**
 * Does any of `wants` appear in `haystack` (recorded page lines, or a diff's
 * added lines)? Whitespace-insensitive on both sides — a marker copied with
 * a trailing space is the same word — and a `{{*}}` wildcard (see
 * maskVolatile) matches anything within one line.
 *
 * `opts.whole` switches to the IDENTITY rule: same wildcards, but bounded at
 * both edges so `fwgr25-n1` is no longer satisfied by `fwgr25-n10`. Only the
 * identity callers pass it; the effect gate asks a different question.
 */
function lineShows(haystack: string[], wants: string[], opts: LineShowsOptions = {}): boolean {
  const all = haystack.map(normWs).join('\n');
  return wants.some((raw) => {
    const want = normWs(raw);
    if (!want) return false;
    if (opts.whole) return identityRe(want).test(all);
    if (!want.includes(WILDCARD)) return all.includes(want);
    const re = new RegExp(want.split(WILDCARD).map(escapeRe).join('[^\\n]*?'));
    return re.test(all);
  });
}

/**
 * Is any of `lines` on the live page, in dialect `d`? 'present' needs only a
 * match. 'absent' needs a look that covered the page (coverageComplete);
 * a look that did not, or a page that could not be read at all, is
 * 'unknown' — a missing line there is not evidence of anything.
 */
async function presence(page: Page, lines: string[], d: LineDialect, opts: LineShowsOptions = {}): Promise<Presence> {
  return (await lookFor(page, lines, d, opts)).presence;
}

/** presence, with why an 'unknown' is unknown. */
async function lookFor(page: Page, lines: string[], d: LineDialect, opts: LineShowsOptions): Promise<{ presence: Presence; why?: string }> {
  const live = await captureLines(page, d);
  if (!live) return { presence: 'unknown', why: 'the page could not be read' };
  if (lineShows(live.lines, lines, opts)) return { presence: 'present' };
  return live.complete ? { presence: 'absent' } : { presence: 'unknown', why: describeCoverage(live.coverage) };
}

/**
 * presence, asked once more after sweeping the page when the first answer is
 * 'unknown' — a lazily rendered page paints what it has once scrolled end to
 * end (sweepPage). Still 'unknown' after that is the answer; `why` says what
 * the look could not cover.
 */
async function confirmPresence(page: Page, lines: string[], d: LineDialect, opts: LineShowsOptions = {}): Promise<{ presence: Presence; why?: string }> {
  const first = await lookFor(page, lines, d, opts);
  if (first.presence !== 'unknown' || !(await sweepPage(page))) return first;
  return lookFor(page, lines, d, opts);
}

/**
 * A parameterised line that did not *appear* may still be *there*: filling a
 * field with the value it already held produces no diff. One fresh look at the
 * live page settles it; only a match is a yes — a page that cannot be read,
 * or a look that could not cover it, shows nothing. Dialect 1 unless asked.
 */
async function presentOnPage(page: Page, lines: string[], opts: LineShowsOptions = {}, d: LineDialect = 1): Promise<boolean> {
  return (await presence(page, lines, d, opts)) === 'present';
}

/**
 * Runs in the page: do the identity and the goal hold of the SAME record?
 *
 * The record's container is the OUTERMOST ancestor of the goal text that is
 * one of several siblings of its kind — the row among rows, the card among
 * cards. Outermost, not nearest: a cell is one of several cells too, and
 * stopping there would ask whether the identity is inside the status cell,
 * which it never is. The row above it is the scope the page itself asserts is
 * one record, and it is what a `scoped` locator names. If the goal text has
 * no repeated ancestor at all the page is not listing records, and page-wide
 * agreement is the right answer there (a detail page's heading and its status
 * field share no small container).
 *
 * `identity` arrives as regex SOURCE (identitySource), already bounded: this
 * function is serialised into the page, so it cannot call identityRe, and a
 * second hand-written copy of the boundary rule here would be free to drift.
 */
function scopeCheckInPage(opts: { identity: string[]; goal: string[] }): boolean {
  const norm = (s: string | null | undefined) => (s ?? '').replace(/\s+/g, ' ').trim();
  const textOf = (el: Element) => norm((el as HTMLElement).innerText || el.textContent);
  const all = Array.from(document.querySelectorAll('*'));

  // The smallest elements that show a goal string: a container shows it too,
  // and starting from the container would skip the record scope below it.
  const holders: Element[] = [];
  for (const raw of opts.goal) {
    const want = norm(raw);
    if (!want) continue;
    const hits = all.filter((el) => textOf(el).includes(want));
    for (const el of hits) if (!hits.some((other) => other !== el && el.contains(other))) holders.push(el);
  }
  if (!holders.length) return false;

  // Siblings of a kind means STRUCTURALLY alike, not merely same-tag: two
  // unrelated buttons that happen to sit side by side are not a record list,
  // and treating them as one would scope a lone control to itself. Rows of a
  // list are rendered by one template and carry the same classes.
  const kindOf = (el: Element) => `${el.tagName}.${norm(el.getAttribute('class'))}`;
  const oneOfSeveral = (el: Element): boolean => {
    const parent = el.parentElement;
    // A direct child of <body> is a section of the page, not a record: a list
    // of records sits inside something. Without this, two unrelated top-level
    // controls make either of them its own "record" scope.
    if (!parent || parent === document.body) return false;
    const kind = kindOf(el);
    let same = 0;
    for (const sib of Array.from(parent.children)) if (kindOf(sib) === kind) same++;
    return same >= 2;
  };

  for (const holder of holders) {
    let node: Element | null = holder;
    let record: Element | null = null;
    while (node && node !== document.body) {
      if (oneOfSeveral(node)) record = node;
      node = node.parentElement;
    }
    if (!record) return true; // not a list: the whole page is about one record
    const inside = textOf(record);
    if (opts.identity.some((src) => new RegExp(src, 'iu').test(inside))) return true;
  }
  return false;
}

/**
 * Scroll the page end to end so a virtualised or lazily rendered UI paints
 * everything it has, then let the DOM settle. Returns false when the page
 * cannot be scripted (gone, cross-origin frame), in which case the caller
 * simply does not retry.
 */
async function sweepPage(page: Page): Promise<boolean> {
  try {
    await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
    await settleDom(page);
    await page.evaluate(() => window.scrollTo(0, 0));
    await settleDom(page);
    return true;
  } catch {
    return false;
  }
}

// Shared execution source: observe.ts. Regenerate to update.
/**
 * Observations both execution targets take of a live page, so that a shared
 * verdict (./gates.ts) is asked the same question in the same dialect by the
 * daemon and by a compiled `.flow.ts` artifact. Self-contained: this module is
 * embedded verbatim in the artifact (spec/runtime-source.ts), so nothing but
 * a sibling shared module or a Playwright type may be imported.
 */

/** What a recorded read takes off its element. A page url read has no element and is not one of these. */
type ReadWhat = 'text' | 'value' | 'attr' | 'count';

function isElementRead(what: unknown): what is ReadWhat {
  return what === 'text' || what === 'value' || what === 'attr' || what === 'count';
}

/**
 * A recorded `read` (one element) or `read_all` (every match), as the daemon's
 * read tools take it and a compiled artifact replays it. `read_all` reads
 * EVERY match: an artifact that took `inputValue()` threw Playwright's
 * strict-mode error on a selector made to match many (odoo's
 * `tr.o_data_row input`, four reads skipped on every compiled run of fwod41
 * while the daemon read them each time). Text is `innerText`, the rendered
 * text the recording saw, never `textContent`. A count is plural by nature,
 * whichever tool asked.
 */
async function readElements(
  loc: Locator,
  plural: boolean,
  what: ReadWhat,
  opts: { attr?: string; timeout?: number } = {},
): Promise<string | number | null | (string | null)[]> {
  const { attr = '', timeout } = opts;
  if (what === 'count') return await loc.count();
  if (plural) {
    if (what === 'text') return await loc.allInnerTexts();
    if (what === 'value') return await loc.evaluateAll((els) => els.map((e) => (e as HTMLInputElement).value ?? null));
    return await loc.evaluateAll((els, a) => els.map((e) => e.getAttribute(a)), attr);
  }
  if (what === 'text') return await loc.innerText({ timeout });
  if (what === 'value') return await loc.inputValue({ timeout });
  return await loc.getAttribute(attr, { timeout });
}

/** A read as the one string a step publishes: every match of a `read_all`, in page order, joined by ` | `. */
function flattenRead(value: unknown): string {
  return Array.isArray(value) ? value.map(String).join(' | ') : String(value);
}

/**
 * Where a read's target is, for an OBSERVATION: the runner's own resolution,
 * and when that finds nothing, one sweep of the page and the resolution once
 * more with no wait (`again`), the wait having already been spent. A
 * virtualised page renders below-the-fold content only once it has been
 * scrolled to, and the agent's scrolls were evals, which never compile
 * (fwgr23 01-open lost the third panel heading without it). A page that
 * cannot be swept is not asked again.
 *
 * The runner supplies `resolve` because what it books around a resolution
 * differs (replay's candidate evidence and misses, the artifact's drift lines
 * and loop sink); WHEN it is asked, and how often, is this rule. Whatever
 * `resolve` throws (a loop progress guard stopping the pass) is not a miss and
 * propagates.
 */
async function resolveForRead<H>(page: Page, resolve: (again: boolean) => Promise<H | null>): Promise<H | null> {
  const hit = await resolve(false);
  if (hit || !(await sweepPage(page))) return hit;
  return resolve(true);
}

type ReadTaken = { ok: true; value: string } | { ok: false; message: string };

/**
 * A resolved read, taken. A read is an observation and never fails the step:
 * a read that throws (the element detached, a strict-mode match, a closed
 * page) comes back as `ok: false` with the error's first part, and the
 * runner skips it with that message. Values are flattened (flattenRead) so
 * both runners publish the same string for the same page.
 */
async function takeRead(read: () => Promise<unknown>): Promise<ReadTaken> {
  try {
    return { ok: true, value: flattenRead(await read()) };
  } catch (err) {
    return { ok: false, message: (err instanceof Error ? err.message : String(err)).split('\nCall log:')[0] };
  }
}

/**
 * The visible live-region texts on the page right now — the alerts half of
 * the ONE page capture the daemon diffs (observeDocumentInPage under
 * SNAPSHOT_LIMITS, src/execution/snapshot.ts), rendered in the step's line
 * dialect: the same elements, visibility rule, caps and whitespace cleaning
 * by construction, not by a second copy kept in step. An alert the daemon
 * would diff is one the artifact sees. These are toasts and status lines, not
 * native `window.alert` dialogs. Null when the page cannot be read
 * (navigating, closed, not answering): "unobserved", never "no alert".
 */
async function liveAlerts(page: Page, d: LineDialect = 1): Promise<string[] | null> {
  const captured = await capturePage(page, d);
  return captured ? captured.alerts : null;
}

/** Live-region texts with whether the look saw every one of them (alertsComplete) — what alertVerdict needs to tell "none raised" from "none seen". */
interface ObservedAlerts {
  alerts: string[];
  complete: boolean;
}

/** liveAlerts, with its coverage: null when the page cannot be read. */
async function liveAlertsObserved(page: Page, d: LineDialect = 1): Promise<ObservedAlerts | null> {
  const captured = await capturePage(page, d);
  return captured ? { alerts: captured.alerts, complete: alertsComplete(captured.coverage) } : null;
}

// Shared execution source: action.ts. Regenerate to update.
/**
 * One observation per action (ROBUSTNESS.md finding 6): begun BEFORE the
 * action dispatches, it owns the action's whole deadline, its baseline of the
 * page's traffic, and what it expects to see, and it says afterwards how the
 * action ended — not dispatched, dispatched, effect verified, or unknown.
 *
 * It replaces two request trackers that disagreed about what "busy" means
 * (every request since the page was adopted, in the old shared counter;
 * fetch/XHR minus paths NAMED like streams, in the daemon's settle). Traffic
 * is recorded once per page here, and whether a request is long-lived is
 * decided by what it does — its transport, its content type, a body that
 * keeps streaming, a request that was already open before the action, one
 * that has waited far longer than an answer takes — never by its url. An app
 * whose ordinary endpoint is called `/api/notifications` is waited for like
 * any other; an event stream on `/api/save` is not.
 *
 * Waiting is evidence, not a sleep: the DOM going quiet, requests the action
 * started landing, a request that starts in the moment after an input (a
 * debounced save), the url holding still after a navigating action, and the
 * expected effect when the caller has one. Completion is the expectation when
 * there is one; quiet alone never verifies an effect.
 *
 * Daemon: tools.ts runStep, around every state-changing tool. Artifact: the
 * emitted step, around its action. Self-contained: sibling shared modules and
 * Playwright types only. Every port (clock, page events, DOM) can be faked, so
 * the policy is tested without a browser or a wall clock.
 */

/**
 * What counts as an action's traffic, and when an open request stops being
 * something to wait for.
 *  - `countedTypes`: resource types an action can be waiting on. Images,
 *    fonts, media and beacons are recorded but never waited for.
 *  - `streamBodyMs`: a fetch/XHR whose headers arrived and whose body is
 *    still open this long later is streaming, not answering.
 *  - `longOpenMs`: a fetch/XHR open this long with no answer at all is a
 *    long-poll, not a save.
 *  - `recentMs`: a request started this long or less before the action began
 *    may still be the action's (a click handler's fetch races the click call
 *    returning); an older one still open is the page's own.
 */
interface TrafficPolicy {
  countedTypes: readonly string[];
  streamBodyMs: number;
  longOpenMs: number;
  recentMs: number;
}

const DEFAULT_TRAFFIC_POLICY: TrafficPolicy = {
  countedTypes: ['fetch', 'xhr', 'document', 'script'],
  streamBodyMs: 1_000,
  longOpenMs: 5_000,
  recentMs: 300,
};

/** Why an open request is not one an action waits for. */
type LongLivedWhy = 'transport' | 'event-stream' | 'streaming-body' | 'open-at-baseline' | 'open-too-long' | 'known-long-poll';

/** One request as the page's traffic recorded it. Times are the traffic clock's. */
interface RequestRecord {
  type: string;
  method: string;
  /** origin + pathname: the endpoint, without the query a poll varies. */
  endpoint: string;
  url: string;
  startedAt: number;
  responseAt?: number;
  contentType?: string;
  finishedAt?: number;
}

interface ActionClock {
  now(): number;
  sleep(ms: number): Promise<void>;
}

/** The page events traffic is recorded from — a Playwright Page, or a fake. */
interface PageEventsPort {
  on(event: string, listener: (arg: never) => void): unknown;
  off(event: string, listener: (arg: never) => void): unknown;
  url(): string;
  mainFrame?(): unknown;
}

/** The DOM as an action's observation asks it: go quiet within `maxMs`, and say when it last changed. */
interface DomPort {
  quiet(quietMs: number, maxMs: number): Promise<{ mutated: boolean; lastMutationAt?: number }>;
}

/** An action's expected effect: true when it holds, false when it does not, null when it could not be observed. */
interface ActionExpectation {
  holds(): Promise<boolean | null>;
}

/** One page's recorded traffic, installed once and shared by every action on that page. */
interface PageTraffic {
  readonly policy: TrafficPolicy;
  readonly clock: ActionClock;
  /** Requests still open, in start order. */
  pending(): RequestRecord[];
  /** When a counted request last finished (-Infinity before any did). */
  lastFinish(): number;
  /** Endpoints (`METHOD origin/path`) that have behaved as long-polls or streams on this page. */
  readonly knownLongPoll: ReadonlySet<string>;
  /** classifyLongLived over this page's learned endpoints; learns the endpoint of a request that proves long-lived by behaviour. */
  classify(r: RequestRecord, now: number, baselineAt: number): LongLivedWhy | null;
  /** Called on every request, response, finish and main-frame navigation; returns the unsubscribe. */
  subscribe(listener: () => void): () => void;
}

const realClock: ActionClock = {
  now: () => Date.now(),
  sleep: (ms) => new Promise<void>((resolve) => setTimeout(resolve, Math.max(0, ms))),
};

/** The endpoint key a long-poll is remembered by. */
function endpointKey(r: Pick<RequestRecord, 'method' | 'endpoint'>): string {
  return `${r.method} ${r.endpoint}`;
}

/** Transports a poll or a stream rides on: the only ones judged by how long they stay open. */
function polling(r: RequestRecord): boolean {
  return r.type === 'fetch' || r.type === 'xhr';
}

/**
 * Whether an open request is long-lived, and why — in this order:
 *  1. a stream transport (`eventsource`, `websocket`);
 *  2. a response that says it streams (`text/event-stream`,
 *     `multipart/x-mixed-replace`);
 *  3. a fetch/XHR whose headers came and whose body has stayed open past
 *     `streamBodyMs`;
 *  4. a request older than the action (started more than `recentMs` before
 *     `baselineAt`) and still open at it: the page's, not the action's;
 *  5. a fetch/XHR open past `longOpenMs` with no answer;
 *  6. a fetch/XHR to an endpoint this page has already shown to be a
 *     long-poll or a stream (`known`).
 * Null: an ordinary request, whatever its url says.
 */
function classifyLongLived(
  r: RequestRecord,
  now: number,
  baselineAt: number,
  policy: TrafficPolicy = DEFAULT_TRAFFIC_POLICY,
  known: ReadonlySet<string> = new Set(),
): LongLivedWhy | null {
  if (r.type === 'eventsource' || r.type === 'websocket') return 'transport';
  if (r.contentType && /^\s*(text\/event-stream|multipart\/x-mixed-replace)/i.test(r.contentType)) return 'event-stream';
  if (polling(r) && r.responseAt !== undefined && r.finishedAt === undefined && now - r.responseAt > policy.streamBodyMs) return 'streaming-body';
  if (r.startedAt < baselineAt - policy.recentMs && (r.finishedAt === undefined || r.finishedAt > baselineAt)) return 'open-at-baseline';
  if (polling(r) && r.responseAt === undefined && r.finishedAt === undefined && now - r.startedAt > policy.longOpenMs) return 'open-too-long';
  if (polling(r) && known.has(endpointKey(r))) return 'known-long-poll';
  return null;
}

const traffics = new WeakMap<object, PageTraffic>();

/** A Playwright request/response, as far as traffic reads one. */
interface RequestLike {
  resourceType(): string;
  method(): string;
  url(): string;
}
interface ResponseLike {
  request(): RequestLike;
  headers(): Record<string, string>;
}

/**
 * The page's traffic, recorded from its own request events: installed on the
 * first call for a page and returned as-is after that, so the daemon installs
 * it when its session adopts a page and every action (daemon or artifact)
 * reads the same record. A page with no request events (a test stub) reads as
 * idle. `opts` apply only to the call that installs it.
 */
function pageTraffic(page: Page | PageEventsPort, opts: { policy?: TrafficPolicy; clock?: ActionClock } = {}): PageTraffic {
  const port = page as unknown as PageEventsPort;
  const existing = traffics.get(port);
  if (existing) return existing;
  const policy = opts.policy ?? DEFAULT_TRAFFIC_POLICY;
  const clock = opts.clock ?? realClock;
  const open = new Map<unknown, RequestRecord>();
  const known: Set<string> = new Set();
  const listeners = new Set<() => void>();
  let lastFinish = -Infinity;
  const notify = () => {
    for (const listener of [...listeners]) listener();
  };
  // A request that proved long-lived by what it did is remembered by its
  // endpoint, so the next poll to it is not waited out for `longOpenMs` again.
  // Only the behavioural rules teach: a request that was merely open before an
  // action says nothing about its endpoint.
  const learn = (r: RequestRecord, why: LongLivedWhy | null) => {
    if (polling(r) && (why === 'event-stream' || why === 'streaming-body' || why === 'open-too-long')) known.add(endpointKey(r));
  };
  const traffic: PageTraffic = {
    policy,
    clock,
    pending: () => [...open.values()],
    lastFinish: () => lastFinish,
    knownLongPoll: known,
    classify: (r, now, baselineAt) => {
      const why = classifyLongLived(r, now, baselineAt, policy, known);
      learn(r, why);
      return why;
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
  traffics.set(port, traffic);
  if (typeof port.on !== 'function') return traffic;
  port.on('request', (req: RequestLike) => {
    let url = '';
    let endpoint = '';
    try {
      url = req.url();
      const parsed = new URL(url);
      endpoint = `${parsed.origin}${parsed.pathname}`;
    } catch {
      endpoint = url;
    }
    open.set(req, { type: req.resourceType(), method: req.method(), endpoint, url, startedAt: clock.now() });
    notify();
  });
  port.on('response', (res: ResponseLike) => {
    const r = open.get(res.request());
    if (!r) return;
    // Judged once as it stood unanswered (a long-poll's wait), then as answered.
    const now = clock.now();
    learn(r, classifyLongLived(r, now, -Infinity, policy));
    r.responseAt = now;
    try {
      r.contentType = res.headers()['content-type'];
    } catch {
      // headers unreadable: judged by behaviour alone
    }
    learn(r, classifyLongLived(r, r.responseAt, -Infinity, policy));
    notify();
  });
  const done = (req: unknown) => {
    const r = open.get(req);
    if (!r) return;
    open.delete(req);
    const now = clock.now();
    // Judged at the moment before it finished: a body that streamed for
    // seconds, or an answer that took a long-poll's time, taught something.
    learn(r, classifyLongLived(r, now, -Infinity, policy));
    r.finishedAt = now;
    if (policy.countedTypes.includes(r.type)) lastFinish = now;
    notify();
  };
  port.on('requestfinished', done);
  port.on('requestfailed', done);
  // A navigation abandons the old document's requests; without this a stale
  // entry would hold the next action to its cap.
  port.on('framenavigated', (frame: unknown) => {
    if (typeof port.mainFrame === 'function' && frame !== port.mainFrame()) return;
    for (const [req, r] of open) if (r.type !== 'document') open.delete(req);
    notify();
  });
  return traffic;
}

/**
 * How many ordinary requests `page` has in flight: counted types, not
 * long-lived by behaviour. 0 for a page whose traffic was never installed.
 */
function inFlightRequests(page: Page | PageEventsPort): number {
  const traffic = traffics.get(page as unknown as object);
  if (!traffic) return 0;
  const now = traffic.clock.now();
  return traffic.pending().filter((r) => traffic.policy.countedTypes.includes(r.type) && traffic.classify(r, now, -Infinity) === null).length;
}

interface ActionOptions {
  /** The whole action — dispatch, every wait, the effect — ends by this long after beginAction. */
  deadlineMs: number;
  /** When given, completion: polled after the page settles, within `effectWaitMs`. */
  expect?: ActionExpectation;
  /** A tool whose effect may be a navigation: the url is waited on to hold still (urlHeldStill). */
  navigating?: boolean;
  /**
   * An input (fill, type, press, select, check): the start grace runs from
   * the dispatch itself, because an input's own save is commonly debounced
   * and changes nothing on the page before it asks. Otherwise the grace runs
   * only from a mutation or a request finishing.
   */
  graceFromDispatch?: boolean;
  /** How long after the last evidence a request may still start and be the action's. */
  startGraceMs?: number;
  /** The most one network wait may cost. */
  networkCapMs?: number;
  /** The most the expected effect is polled for. */
  effectWaitMs?: number;
  clock?: ActionClock;
  dom?: DomPort;
  policy?: TrafficPolicy;
}

/** How an action ended, and what its settle waited on. */
interface SettleVerdict {
  outcome: ActionOutcome;
  /** Where the page is once the action settled. */
  url: string;
  via?: DispatchVia;
  waited: { domMs: number; networkMs: number; urlMs: number; effectMs: number };
  /** Open requests that were not waited for, and why. */
  ignored: { url: string; why: LongLivedWhy }[];
  /** A wait was cut short by the action's deadline. */
  deadlineHit: boolean;
}

interface ActionObservation {
  /** Milliseconds left of the action's deadline (never negative). */
  remaining(): number;
  /** The action went out, this way. */
  dispatched(via: DispatchVia): void;
  /** The action threw: its outcome is what the error proves (outcomeOfError), and the error is rethrown. */
  failed(err: unknown): never;
  /** Wait for the action's evidence; the same promise on a second call. */
  settle(): Promise<SettleVerdict>;
  /** Stop every wait now and release what the observation subscribed to. */
  cancel(): void;
}

/** DOM quiet window an action's settle demands once a mutation shows (settleDom's). */
const ACTION_QUIET_MS = 250;
/** The most one DOM settle may cost inside an action (settleDom's). */
const ACTION_DOM_MAX_MS = 2_000;
/** How long after the last evidence a request may start and still be the action's. */
const ACTION_START_GRACE_MS = 250;
/** The most one network wait may cost (the old settlePage deadline). */
const ACTION_NETWORK_CAP_MS = 2_000;
/** The most an expected effect is polled for once the page has settled. */
const ACTION_EFFECT_WAIT_MS = 3_000;
/** How often an expected effect is asked again while nothing else is happening. */
const ACTION_EFFECT_POLL_MS = 100;
/** Settle rounds (DOM, network, grace) before the observation stops looking for more. */
const MAX_SETTLE_ROUNDS = 8;

/** The page's own DOM, through the shared settle: the load event first, then quiet. */
function pageDom(page: Page, clock: ActionClock): DomPort {
  return {
    quiet: async (quietMs, maxMs) => {
      const started = clock.now();
      if (typeof page.waitForLoadState === 'function') {
        await page.waitForLoadState('domcontentloaded', { timeout: Math.max(1, maxMs) }).catch(() => {});
      }
      const left = maxMs - (clock.now() - started);
      if (left <= 0) return { mutated: false };
      const seen = await domQuiet(page, { quietMs, maxMs: left });
      return seen && seen.mutated ? { mutated: true, lastMutationAt: clock.now() - seen.sinceMs } : { mutated: false };
    },
  };
}

/**
 * Begin observing an action. Call it BEFORE the action dispatches — the
 * baseline is this moment, and a request the action starts must not be
 * mistaken for one that was already open — then dispatch, then `settle()`.
 * A page opener's popup listener (context.ts armPageEffect) is armed before
 * this too; the two share nothing but the moment.
 */
function beginAction(page: Page, opts: ActionOptions): ActionObservation {
  const clock = opts.clock ?? realClock;
  const port = page as unknown as PageEventsPort;
  const traffic = pageTraffic(port, { policy: opts.policy, clock });
  const policy = traffic.policy;
  const dom = opts.dom ?? pageDom(page, clock);
  const baselineAt = clock.now();
  const deadline = baselineAt + opts.deadlineMs;
  const startGraceMs = opts.startGraceMs ?? ACTION_START_GRACE_MS;
  const networkCapMs = opts.networkCapMs ?? ACTION_NETWORK_CAP_MS;
  const effectWaitMs = opts.effectWaitMs ?? ACTION_EFFECT_WAIT_MS;
  const readUrl = () => {
    try {
      return port.url();
    } catch {
      return '';
    }
  };
  const urlBefore = readUrl();
  let via: DispatchVia | undefined;
  let dispatchedAt: number | undefined;
  let failedOutcome: 'not-dispatched' | 'unknown' | undefined;
  let cancelled = false;
  let settling: Promise<SettleVerdict> | null = null;
  const wakers = new Set<() => void>();
  const remaining = () => Math.max(0, deadline - clock.now());

  // A wait that ends at `ms`, at the next traffic event, or on cancel —
  // whichever is first. The event is only a reason to look again.
  const wake = (ms: number) =>
    new Promise<void>((resolve) => {
      let done = false;
      const finish = () => {
        if (done) return;
        done = true;
        unsubscribe();
        wakers.delete(finish);
        resolve();
      };
      const unsubscribe = traffic.subscribe(finish);
      wakers.add(finish);
      void clock.sleep(Math.max(1, ms)).then(finish);
    });

  const run = async (): Promise<SettleVerdict> => {
    const waited = { domMs: 0, networkMs: 0, urlMs: 0, effectMs: 0 };
    const ignored = new Map<RequestRecord, LongLivedWhy>();
    let deadlineHit = false;
    let lastMutationAt = -Infinity;
    const dispatchEnd = dispatchedAt ?? clock.now();

    // Open requests this action waits for: counted types, not long-lived.
    const relevant = (): RequestRecord[] => {
      const now = clock.now();
      const out: RequestRecord[] = [];
      for (const r of traffic.pending()) {
        if (!policy.countedTypes.includes(r.type)) continue;
        const why = traffic.classify(r, now, baselineAt);
        if (why) ignored.set(r, why);
        else out.push(r);
      }
      return out;
    };

    const quietDom = async () => {
      if (cancelled) return;
      const left = remaining();
      const budget = Math.min(ACTION_DOM_MAX_MS, left);
      if (budget <= 0) {
        deadlineHit = true;
        return;
      }
      const started = clock.now();
      const seen = await dom.quiet(ACTION_QUIET_MS, budget).catch(() => ({ mutated: false, lastMutationAt: undefined }));
      const took = clock.now() - started;
      waited.domMs += took;
      if (seen.mutated && seen.lastMutationAt !== undefined) lastMutationAt = Math.max(lastMutationAt, seen.lastMutationAt);
      if (left < ACTION_DOM_MAX_MS && took >= budget) deadlineHit = true;
    };

    // Wait while a request the action may be waiting on is open. Woken by any
    // traffic event, and by a timer at the moment the earliest open request
    // would turn long-lived, so a stream is let go as soon as it shows itself.
    // `networkCapMs` is ONE budget for the whole settle, not per wait: an app
    // that never stops asking costs it once. 'capped': requests were still
    // open when the budget or the deadline ran out.
    let networkSpent = 0;
    const waitNetwork = async (): Promise<'idle' | 'waited' | 'capped'> => {
      const started = clock.now();
      const capEnd = started + Math.max(0, networkCapMs - networkSpent);
      let state: 'idle' | 'waited' | 'capped' = 'idle';
      for (;;) {
        if (cancelled) break;
        const open = relevant();
        if (!open.length) break;
        const now = clock.now();
        const end = Math.min(capEnd, deadline);
        if (now >= end) {
          if (deadline <= capEnd) deadlineHit = true;
          state = 'capped';
          break;
        }
        let next = end;
        for (const r of open) {
          if (!polling(r)) continue;
          next = Math.min(next, r.responseAt !== undefined ? r.responseAt + policy.streamBodyMs + 1 : r.startedAt + policy.longOpenMs + 1);
        }
        await wake(next - now);
        state = 'waited';
      }
      const took = clock.now() - started;
      networkSpent += took;
      waited.networkMs += took;
      return state;
    };

    // The debounce: shortly after the last evidence (a mutation, a request
    // landing, or — for an input — the dispatch itself) a request may still
    // start and be the action's. Wait out what is left of that grace for one;
    // true when one started.
    const graceStart = async (): Promise<boolean> => {
      const finished = traffic.lastFinish();
      const anchor = Math.max(lastMutationAt, finished >= baselineAt ? finished : -Infinity, opts.graceFromDispatch ? dispatchEnd : -Infinity);
      const started = clock.now();
      let startedOne = false;
      for (;;) {
        if (cancelled) break;
        if (relevant().length) {
          startedOne = true;
          break;
        }
        const left = Math.min(anchor + startGraceMs - clock.now(), remaining());
        if (left <= 0) break;
        await wake(left);
      }
      waited.networkMs += clock.now() - started;
      return startedOne;
    };

    for (let round = 0; round < MAX_SETTLE_ROUNDS && !cancelled && remaining() > 0; round++) {
      await quietDom();
      const network = await waitNetwork();
      if (network === 'capped') break;
      // An answer landed: let the DOM take it, then look again.
      if (network === 'waited') continue;
      if (await graceStart()) continue;
      break;
    }

    if (opts.navigating && !cancelled) {
      const started = clock.now();
      const lateNavMs = Math.min(LATE_NAV_MS, remaining());
      const settledUrl = readUrl();
      const seen = await urlHeldStill(port, urlBefore, () => relevant().length, { lateNavMs });
      waited.urlMs += clock.now() - started;
      if (lateNavMs < LATE_NAV_MS && clock.now() - started >= lateNavMs) deadlineHit = true;
      if (seen !== settledUrl) {
        await quietDom();
        await waitNetwork();
      }
    }

    let verified = false;
    let observed = false;
    if (opts.expect && !cancelled) {
      const started = clock.now();
      const end = Math.min(started + effectWaitMs, deadline);
      for (;;) {
        const holds = await opts.expect.holds().catch(() => null);
        if (holds === true) {
          verified = true;
          observed = true;
          break;
        }
        if (holds === false) observed = true;
        if (cancelled) break;
        const now = clock.now();
        if (now >= end) {
          if (deadline < started + effectWaitMs) deadlineHit = true;
          break;
        }
        // Traffic still open is the effect still on its way: wait on it
        // (within what is left of the network budget) rather than on the clock.
        if (relevant().length && (await waitNetwork()) === 'waited') {
          await quietDom();
          continue;
        }
        await clock.sleep(Math.min(ACTION_EFFECT_POLL_MS, end - now));
      }
      waited.effectMs += clock.now() - started;
    }

    const outcome: ActionOutcome = failedOutcome ?? (verified ? 'effect-verified' : opts.expect && !observed ? 'unknown' : 'dispatched');
    return {
      outcome,
      url: readUrl(),
      ...(via ? { via } : {}),
      waited,
      ignored: [...ignored].map(([r, why]) => ({ url: r.url, why })),
      deadlineHit,
    };
  };

  return {
    remaining,
    dispatched: (how) => {
      via ??= how;
      dispatchedAt ??= clock.now();
    },
    failed: (err) => {
      failedOutcome = outcomeOfError(err);
      throw err;
    },
    settle: () => (settling ??= run()),
    cancel: () => {
      cancelled = true;
      for (const finish of [...wakers]) finish();
    },
  };
}

// Shared execution source: lifecycle.ts. Regenerate to update.
/**
 * An action may explicitly skip or stop; neither outcome claims completion. A
 * stopped action may say what is known about its dispatch (browser.ts
 * `ActionOutcome`): a stop whose action was proven never to have gone out is
 * a different fact from one that may have landed.
 */
type StepActionResult<T> =
  | { status: 'completed'; value: T }
  | { status: 'skipped' }
  | { status: 'stopped'; outcome?: 'not-dispatched' | 'dispatched' | 'effect-verified' | 'unknown' };

interface StepLifecycle<T, V> {
  prepare(): Promise<void>;
  act(): Promise<StepActionResult<T>>;
  settle(value: T): Promise<void>;
  bind(value: T): Promise<void>;
  verify(value: T): Promise<V>;
}

/**
 * The mandatory lifecycle used by replay and embedded in standalone tests.
 * Action handlers cannot bypass the obligations of a completed action. Binding
 * precedes verification because a step's checks may refer to values it minted.
 * There is deliberately no retry or catch here: a failed phase stops the step,
 * and an adapter must never mistake a verification failure for failed dispatch.
 */
async function runStepLifecycle<T, V>(phases: StepLifecycle<T, V>): Promise<{
  action: StepActionResult<T>;
  verification?: V;
}> {
  await phases.prepare();
  const action = await phases.act();
  if (action.status !== 'completed') return { action };
  await phases.settle(action.value);
  await phases.bind(action.value);
  const verification = await phases.verify(action.value);
  return { action, verification };
}

/** Reads are optional observations in both execution targets. */
function isReadAction(tool: string): boolean {
  return tool === 'read' || tool === 'read_all';
}

/** Only a nonempty identifier changed by this step is evidence of creation. */
function changedCreation(before: string | undefined, after: string | undefined): string | undefined {
  return after && after !== before ? after : undefined;
}

/** Actions that can change application data; navigation is a separate concern. */
const MUTATING_ACTIONS = new Set([
  'click', 'dblclick', 'right_click', 'modifier_click', 'fill', 'type',
  'press', 'select', 'check', 'drag', 'upload',
]);

function isMutatingAction(tool: string): boolean {
  return MUTATING_ACTIONS.has(tool);
}

interface ExecutionStepShape {
  tool: string;
  body?: readonly ExecutionStepShape[];
}

function mutatesSteps(steps: readonly ExecutionStepShape[]): boolean {
  return steps.some((step) => isMutatingAction(step.tool) || (step.body ? mutatesSteps(step.body) : false));
}

// Shared execution source: expect.ts. Regenerate to update.
/**
 * The content-expectation verdict both execution targets share: given what a
 * step recorded, what the run's params are, and what the page shows now, did
 * the step have its recorded effect? The daemon imports this (skills/replay.ts
 * calls it from its effect gate); a compiled `.flow.ts` artifact embeds its
 * exact source (spec/runtime-source.ts) and calls it from each step's verify
 * phase. One function, so the two runners cannot disagree about what a
 * recorded line means — an earlier emitter rebuilt each line as a Playwright
 * locator and never looked past the name, so `- combobox "Project": {{v1}}`
 * passed on any visible Project combobox whatever it showed. Self-contained:
 * nothing but a sibling shared module may be imported.
 */

/**
 * Page lines that describe the page in transit — spinners, progress bars,
 * and toasts (an alert that happened to be on screen, such as fwgr25's
 * "Error loading RSS feed", is not what the step did; a step's own alert is
 * carried by alertContains, which stays soft). Never a lasting effect.
 */
const TRANSIENT_LINE = /^-?\s*(status|progressbar|alert)\b/;

/** A recorded line carrying a `{{vN}}` slot: this run's own value, the HARD half of an expectation. */
const SLOT_LINE = /\{\{v\d+\}\}/;

/** A recorded line naming a dialog, whose absence is conditional UI rather than a failed effect. */
const DIALOG_LINE = /^-\s*dialog\s+"([^"]*)"/;

/**
 * An effect expectation asserts what the PROCEDURE put on the page, and the
 * procedure only ever puts values there through its own fills and choices —
 * which are slots (`{{vN}}`, or a `{{dN}}` the app minted and a url showed)
 * by the time this runs, because substitute() went first. A control's
 * displayed value that is NOT a slot is therefore the app's: a default, a
 * computed figure, the id of the record the recording happened to make.
 * atelyr's project picker recorded `- combobox "…": 13f9pv52yozr` — the
 * recording's own project id — and every replay's project had another, so
 * both add-item steps stopped at "did not show … as it did when recorded".
 *
 * Provenance, not shape: no attempt is made to recognise an identifier by
 * how it looks, which breaks on the next app. The role and name still have
 * to match; only the value after the colon is wildcarded.
 */
function maskMinted(line: string): string {
  // `- role "name" [state]: value` — the value colon is the one after the
  // (quoted) name and any state markers, never one inside the name.
  return line.replace(/^(-?\s*\S+(?:\s+"(?:[^"\\]|\\.)*")?(?:\s+\[[^\]]*\])*)(:\s*)(\S.*?)\s*$/, (whole, head: string, sep: string, value: string) =>
    value.includes('{{') ? whole : `${head}${sep}${WILDCARD}`,
  );
}

/**
 * A recorded line as it is looked for on a LIVE page: the recording's clock
 * and calendar tokens masked (a store compiled before masking existed still
 * carries them), the recording's own minted values masked, and this run's
 * params filled in. Both runners fill at run time, from the same map.
 */
function liveLines(lines: readonly string[], params: Record<string, string>): string[] {
  return lines.map((l) => fillParams(maskMinted(maskVolatile(l)), params));
}

/**
 * The expectation lines that could tell a right-element fill from a
 * wrong-element one. A recorded added-line that merely restates the fill in a
 * same-role element — `textbox "": {{v4}}` — is an ECHO: the WRONG textbox
 * produces it too, so it is no evidence at all. fwgr17-n3's 03-open passed
 * its effect gate on exactly that line after a positional fallback took the
 * step. When consequential lines exist (the heading that renders the typed
 * title, the menu button named after it), only those count; when the echo is
 * all the recording has, it is returned unchanged — a lone search-box fill
 * legitimately shows nothing else, and the caller warns instead.
 */
function isEchoLine(line: string, filledValue: string): boolean {
  return new RegExp(`^-?\\s*(textbox|searchbox|spinbutton|combobox)\\b[^:]*:\\s*${escapeRe(filledValue)}\\s*$`).test(line.trim());
}

function consequentialExpectations(lines: string[], filledValue: string | undefined): string[] {
  if (!filledValue) return lines;
  const rest = lines.filter((l) => !isEchoLine(l, filledValue));
  return rest.length ? rest : lines;
}

/** A fresh look at the live page, in the step's line dialect (see snapshot.ts captureLines). */
interface LiveLines {
  lines: string[];
  /** The look covered enough of the page for a missing line to mean absent (coverageComplete). */
  complete: boolean;
  coverage?: ObservationCoverage;
}

/** What a runner observed after the step: its diff, and a way to look again. */
interface ChangeObservation {
  /** The lines the step added (the diff), or null when that capture failed — never [] for "unavailable". */
  added: string[] | null;
  /**
   * A fresh look at the live page; null when the page cannot be read. Both
   * are rendered in the dialect the step's recorded lines are in — a diff in
   * one dialect judged against lines in another would miss by construction.
   */
  live: () => Promise<LiveLines | null>;
}

/** The step, as the verdict needs to know it. */
interface ChangeContext {
  /** Human step tag, e.g. "5", "9.2.1", or the artifact's "<stepId> <segmentId>/<index>". */
  tag: string;
  tool: string;
  /** The value a fill/type step put on the page, params filled. */
  value?: string;
  /** Some target of this step resolved through a structural (positional) candidate. */
  positionalResolution: boolean;
}

interface ChangeVerdict {
  /** The step ran but did not have its recorded effect: the reason, and the run stops. */
  stop?: string;
  /** Always applied, whatever else the verdict says. */
  warnings: string[];
  /**
   * Part of the evidence was missing: the diff leg (a failed capture, the
   * live page decided), or a live look that could not cover the page, so a
   * stop could not be confirmed as a real absence.
   */
  unobserved?: true;
  /**
   * The recorded effect was a dialog opening and no dialog opened. A dialog
   * is conditional UI — "Discard changes?" appears only when there are
   * changes — so its absence is a legitimate state, not a failed effect; the
   * steps that were going to act inside it are skipped (see namesDialogControl).
   *
   * `lines` is the dialog's own recorded subtree — the controls it listed.
   * Membership is PROVEN against it, never inferred from a target simply
   * being missing: a step whose locator names nothing the dialog contained
   * is a step of the procedure's own, and its absence is a failure.
   */
  absentDialog?: { name: string; lines: string[] };
  /**
   * The step's recorded page changes were seen in what the action ADDED — the
   * diff, not merely the live page, where a line may simply have been there
   * already — and nothing weakened that (a positional fill proven only by its
   * own echo is not confirmation). This is the evidence that lets an alert the
   * recording never saw be reported instead of stopping the run (gates.ts
   * alertVerdict): the step demonstrably did what it was recorded doing.
   */
  confirmed?: true;
}

/**
 * Page-change expectations. Lines that carry a parameter are HARD: they are
 * what distinguishes this run from the recorded one (the new title appearing
 * as a heading), so their absence means the step acted on the wrong thing
 * even though it "worked". Everything else stays soft until data says it is
 * reliable — but a plain change absent from the diff AND the live page means
 * the action did not have its recorded effect, and failing there is what
 * turns a rejected state change into a clean recovery instead of a false
 * success (the fwrd4l-n3 Ready click).
 *
 * Both halves are matched by lineShows over WHOLE snapshot lines — role,
 * name, state and the value after the colon — in the diff first and then on
 * the live page. Empty `warnings` and nothing else set means the step passed
 * with nothing to say.
 */
async function expectedChangesVerdict(
  recorded: readonly string[] | undefined,
  params: Record<string, string>,
  ctx: ChangeContext,
  obs: ChangeObservation,
): Promise<ChangeVerdict> {
  const warnings: string[] = [];
  if (!recorded?.length) return { warnings };
  const { tag } = ctx;
  // Confirmation (ChangeVerdict.confirmed) holds only while every recorded
  // group was found in the diff; any fallback below clears it.
  let confirmed = true;
  // The step diff is ONE source of evidence, not the authority. When the
  // capture failed there are no added lines to search — which must not read
  // as "the expected line was absent but harmlessly so", nor as a pass. The
  // checks below fall through to a fresh look at the live page, and a
  // required effect that cannot be found there still stops the run.
  // `added === null` means unavailable; `[]` means observed-empty.
  const added = obs.added;
  if (added === null) warnings.push(`step ${tag}: the page could not be captured after the action — its recorded effects were checked against the live page instead`);
  // A live look answers three ways. Shown is evidence. Not shown on a look
  // that covered the page is absence. Not shown on a look that could not
  // (the page unreadable, a cap reached, a visible frame unread, a
  // virtualised list) is NOT absence: the stop below still stands — nothing
  // established the effect — but it is marked unobserved and says why, and a
  // conditional branch (the absent dialog) is never taken on it.
  const look = async (lines: string[]): Promise<{ shown: boolean; complete: boolean; why: string }> => {
    const live = await obs.live();
    if (!live) return { shown: false, complete: false, why: 'the page could not be read' };
    if (lineShows(live.lines, lines)) return { shown: true, complete: live.complete, why: '' };
    return { shown: false, complete: live.complete, why: live.complete ? '' : live.coverage ? describeCoverage(live.coverage) || 'coverage unknown' : 'coverage unknown' };
  };
  // A line carrying a {{vN}} slot is HARD (below). A {{dN}} derived marker
  // is filled like any other param but stays soft — the app minted it.
  const isParam = (l: string) => SLOT_LINE.test(l);
  // Transient lines (spinners, progress bars) are dropped here too, so a
  // store compiled before TRANSIENT_LINE existed stops failing on them.
  const lines = recorded.filter((l) => !TRANSIENT_LINE.test(l));
  if (!lines.length) return { warnings: [] };
  let parameterised = liveLines(lines.filter(isParam), params);
  const plain = liveLines(lines.filter((l) => !isParam(l)), params);
  // A positionally-resolved fill must prove itself with a CONSEQUENTIAL
  // change: its own echo in a same-role element is what the wrong element
  // produces too (see consequentialExpectations). When the echo is all the
  // recording has, the old gate stands and we say so.
  if (ctx.positionalResolution && parameterised.length && typeof ctx.value === 'string' && ctx.value) {
    const value = ctx.value;
    const consequential = parameterised.filter((l) => !isEchoLine(l, value));
    if (consequential.length) parameterised = consequential;
    else {
      confirmed = false;
      warnings.push(`step ${tag}: resolved positionally and its only recorded effect is the fill's own echo — the effect gate cannot tell right element from wrong here`);
    }
  }
  if (parameterised.length && !(added !== null && lineShows(added, parameterised))) {
    confirmed = false;
    const seen = await look(parameterised);
    if (!seen.shown) {
      const shown = parameterised.map((w) => JSON.stringify(w)).join(' / ');
      if (!seen.complete) {
        return { warnings, unobserved: true, stop: `after step ${tag} the page did not show ${shown} as it did when recorded, and that could not be confirmed: capture incomplete (${seen.why}) — the step ran but its effect was not established` };
      }
      return { warnings, stop: `after step ${tag} the page did not show ${shown} as it did when recorded — the step ran but probably acted on the wrong element` };
    }
  }
  if (plain.length && !(added !== null && lineShows(added, plain))) {
    confirmed = false;
    // None of the recorded effects in the step diff — check the live page
    // before judging (a change can land outside the diff window).
    const seen = await look(plain);
    if (!seen.shown) {
      // The recorded effect was a dialog opening. A dialog is conditional
      // UI: fwgr24's create step recorded "Exit edit" → "Discard changes to
      // dashboard?" because the RECORDING had unsaved edits at that moment;
      // a replay whose earlier steps saved cleanly has none, no dialog
      // opens, and that is the app working — not the step failing. The
      // steps that would have acted inside the dialog are skipped instead.
      const dialog = plain.map((l) => DIALOG_LINE.exec(l)?.[1]).find((n) => n !== undefined);
      // ...but only on a real observation. Concluding "the dialog did not
      // open" from a capture that failed is inferring a branch from missing
      // evidence, and it would go on to skip the steps inside it.
      if (dialog !== undefined && added === null) {
        return { warnings, unobserved: true, stop: `after step ${tag} the page could not be captured, so whether the dialog ${JSON.stringify(dialog)} opened is unknown — its absence cannot be assumed` };
      }
      // The same for a live look that could not cover the page: a dialog in
      // an unread frame, or past a cap, is not a dialog that did not open.
      if (dialog !== undefined && !seen.complete) {
        return { warnings, unobserved: true, stop: `after step ${tag} the recorded dialog ${JSON.stringify(dialog)} was not seen, but the page could not be observed in full (${seen.why}) — its absence cannot be assumed` };
      }
      if (dialog !== undefined) {
        warnings.push(`step ${tag}: the recorded dialog ${JSON.stringify(dialog)} did not open — conditional UI, treated as absent; steps that name one of its controls will be skipped`);
        return { warnings, absentDialog: { name: dialog, lines: plain } };
      }
      if (!seen.complete) {
        return { warnings, unobserved: true, stop: `after step ${tag} none of the ${plain.length} recorded page change(s) appeared (e.g. ${JSON.stringify(plain[0])}), and that could not be confirmed: capture incomplete (${seen.why}) — the step ran but its effect was not established` };
      }
      return { warnings, stop: `after step ${tag} none of the ${plain.length} recorded page change(s) appeared (e.g. ${JSON.stringify(plain[0])}) — the step ran but did not have its recorded effect` };
    }
    warnings.push(`step ${tag}: none of the ${plain.length} expected page change(s) appeared in the step diff (found on the page instead)`);
  }
  if (added === null) return { warnings, unobserved: true };
  return confirmed ? { warnings, confirmed: true } : { warnings };
}

/** The locator candidates of a step, as far as the dialog-membership rule reads them. */
interface DialogControlStep {
  locators: Record<string, readonly { kind: string; name?: string; text?: string; label?: string; hasText?: string }[] | undefined>;
}

/**
 * The name a step's target candidates put on the element, for membership
 * tests against a dialog's recorded subtree. Only NAMED candidates count: a
 * css/point/testid target says where an element was, not what it was called,
 * and a positional match against a dialog's line list would be a coincidence.
 */
function targetNames(step: DialogControlStep, params: Record<string, string>): string[] {
  const out: string[] = [];
  for (const c of [...(step.locators.target ?? []), ...(step.locators.source ?? [])]) {
    const name = c.kind === 'role' ? c.name : c.kind === 'text' ? c.text : c.kind === 'label' ? c.label : c.kind === 'scoped' ? c.hasText : undefined;
    if (name) out.push(fillParams(name, params).trim());
  }
  return out.filter((n) => n.length > 0);
}

/**
 * Whether a step acts on a control the absent dialog itself listed — the
 * control's name when it does, null when it does not. The dialog's recorded
 * effect lines carry its subtree — `- button "Confirm"`, `- textbox "Reason"`
 * — so a step naming one of them was inside it. This is the evidence
 * `dropDismissedDialogs` uses at compile time, applied at run time by both
 * runners.
 */
function namesDialogControl(step: DialogControlStep, dialogLines: readonly string[], params: Record<string, string>): string | null {
  for (const name of targetNames(step, params)) {
    if (dialogLines.some((l) => l.includes(`"${name}"`))) return name;
  }
  return null;
}

/**
 * What an action's observation (src/execution/action.ts `beginAction`) polls
 * for as the step's completion: the HARD half of its recorded page changes —
 * the lines carrying this run's own `{{vN}}` values, filled — in the step's
 * line dialect. It holds when any of them shows, as the effect gate
 * (expectedChangesVerdict) accepts any of them; it does not hold when none
 * shows on a look that covered the page; and it could not be observed (null)
 * otherwise. Undefined when the step has no such line: quiet is then all the
 * observation waits for, and it never calls that an effect.
 *
 * The recorded url is not part of it. Both runners' url gates already wait on
 * the url with their own window, and a url the gate would accept as volatile
 * would never strictly match here, so every such step would sit out the whole
 * effect window first.
 */
function effectExpectation(
  page: Page,
  recorded: readonly string[] | undefined,
  params: Record<string, string>,
  d: LineDialect = 1,
): { holds(): Promise<boolean | null> } | undefined {
  const hard = liveLines((recorded ?? []).filter((l) => SLOT_LINE.test(l) && !TRANSIENT_LINE.test(l)), params);
  if (!hard.length) return undefined;
  return {
    holds: async () => {
      const live = await captureLines(page, d);
      if (!live) return null;
      if (lineShows(live.lines, hard)) return true;
      return live.complete ? false : null;
    },
  };
}

// Shared execution source: point.ts. Regenerate to update.
/**
 * Geometry as a locator kind, shared by daemon replay and the standalone
 * artifact.
 *
 * A `point` candidate says where the element WAS: its box in document
 * coordinates and the viewport it was recorded in, plus the role (or tag) it
 * had. It is resolved in two moves — `markPoint` finds the element under the
 * recorded point, walks up to the recorded KIND of thing, and tags it; then
 * `pointLocator` names the tag — so that the result is an ordinary Locator
 * that stands only when the role matches: a locator, not a blind click.
 *
 * The same box is the yardstick a positional guess is measured against (see
 * resolve.ts's plausibility rule).
 */
interface PointGeometry {
  /** Centre of the recorded element, in document coordinates. */
  x: number;
  y: number;
  w: number;
  h: number;
  /** The role it had, or null when it had none — then `tag` decides. */
  role: string | null;
  tag: string;
  /** The viewport it was recorded in: what "near" means for the box. */
  vw: number;
  vh: number;
}

/** The attribute markPoint leaves on the element it found, so a sync Locator can name it. */
const POINT_MARK = 'data-sitelooper-point';

function pointToken(c: { x: number; y: number }): string {
  return `${c.x},${c.y}`;
}

/** The Locator naming what markPoint tagged for this point. Empty until markPoint has run on this page. */
function pointLocator(page: Page, c: { x: number; y: number }): Locator {
  return page.locator(`[${POINT_MARK}=${JSON.stringify(pointToken(c))}]`);
}

/**
 * Find the element under a recorded point, walk up to its actionable
 * ancestor, and tag it for pointLocator — but only when it is the KIND of
 * thing recorded (same role, or same tag when the recording had no role).
 * Returns what it found, or null when nothing of that kind is there. Scrolls
 * the window so the point is on screen first; a point in an inner scroller
 * is found only when that scroller sits where it was recorded.
 */
async function markPoint(page: Page, c: PointGeometry): Promise<{ role: string | null; tag: string } | null> {
  try {
    return await page.evaluate(
      ({ x, y, role, tag, mark, token }) => {
        const ACTIONABLE = 'button,a[href],input,select,textarea,summary,[role],[tabindex],label';
        const targetY = y - window.innerHeight / 2;
        if (Math.abs(window.scrollY - targetY) > window.innerHeight / 2 || x - window.scrollX > window.innerWidth) {
          window.scrollTo(Math.max(0, x - window.innerWidth / 2), Math.max(0, targetY));
        }
        const hit = document.elementFromPoint(x - window.scrollX, y - window.scrollY);
        if (!hit) return null;
        const kindOf = (el: Element): { role: string | null; tag: string } => {
          const tagOf = el.tagName.toLowerCase();
          const type = (el.getAttribute('type') || '').toLowerCase();
          const implicit = (): string | null => {
            if (tagOf === 'button') return 'button';
            if (tagOf === 'a') return el.hasAttribute('href') ? 'link' : null;
            if (tagOf === 'select') return el.hasAttribute('multiple') ? 'listbox' : 'combobox';
            if (tagOf === 'textarea') return 'textbox';
            if (tagOf === 'img') return 'img';
            if (/^h[1-6]$/.test(tagOf)) return 'heading';
            if (tagOf === 'input') {
              if (type === 'checkbox') return 'checkbox';
              if (type === 'radio') return 'radio';
              if (type === 'submit' || type === 'button' || type === 'reset') return 'button';
              if (type === 'search') return 'searchbox';
              if (type === 'number') return 'spinbutton';
              if (['text', 'email', 'tel', 'url', 'password', ''].includes(type)) return 'textbox';
              return null;
            }
            return null;
          };
          return { role: el.getAttribute('role') || implicit(), tag: tagOf };
        };
        // The point lands on whatever is painted there — a heading's text
        // span, a button's icon. Walk up a few ancestors for the recorded
        // KIND (fwgr27: every heading point missed because the hit was the
        // title's inner span); failing that, the nearest actionable ancestor.
        let el: Element | null = null;
        for (let cur: Element | null = hit, hops = 0; cur && hops < 6; cur = cur.parentElement, hops++) {
          const k = kindOf(cur);
          if (role ? k.role === role : k.tag === tag) {
            el = cur;
            break;
          }
        }
        el ??= (hit.closest(ACTIONABLE) as Element | null) ?? hit;
        const { role: roleOf, tag: tagOf } = kindOf(el);
        const same = role ? roleOf === role : tagOf === tag;
        if (!same) return null;
        for (const old of Array.from(document.querySelectorAll(`[${mark}]`))) old.removeAttribute(mark);
        el.setAttribute(mark, token);
        return { role: roleOf, tag: tagOf };
      },
      { x: c.x, y: c.y, role: c.role, tag: c.tag, mark: POINT_MARK, token: pointToken(c) },
    );
  } catch {
    return null;
  }
}

// Shared execution source: resolve.ts. Regenerate to update.
/**
 * ONE locator-resolution policy, run by daemon replay and embedded verbatim
 * in the standalone artifact.
 *
 * A recorded step carries a CHAIN of ways to find its element. Picking one at
 * replay is not "the first that matches": it is a set of rules that used to
 * live only in replay's `resolveChain`, while the artifact's `pick` had one of
 * them (policy audit B8, gaps 14 and B8). The rules, in the order they apply:
 *
 *  1. ORDER. Identity (a candidate that names a RECORD) ahead of handles (a
 *     candidate that names a CONTROL) ahead of paths (a route to wherever
 *     that shape currently sits), with the recorded point last of all — each
 *     class keeping its recorded order. Within a class a candidate that later
 *     runs showed to be volatile (`retired`) goes last: the class order is a
 *     prior about what a candidate IS, retirement is a measurement of whether
 *     it WORKS.
 *  2. A POINT NAMES A PLACE. It is marked (the element under it, of the
 *     recorded kind) before its locator can name anything; nothing of that
 *     kind there is a miss.
 *  3. UNIQUE, THEN GUARDED. A candidate that resolves to exactly one element
 *     must still (a) keep the record's identity — bear every value the step
 *     was recorded against, unless it carries that value itself; the recorded
 *     primary is trusted, unless it is itself structural; (b) be plausible —
 *     a guess that resolves far from the recorded box is a different element;
 *     (c) stay on the recorded origin — a guess inside a link that leaves it
 *     cannot be the recorded control. The primary is exempt from (b) and (c)
 *     unless structural: the recording did click it.
 *  4. AMBIGUITY. Several matches are the normal shape only for a read across
 *     every match (`allowMultiple`) and for a loop body whose per-record
 *     locator matches every record (`ambiguousNth` narrows to the cursor,
 *     still identity-guarded). Otherwise an ambiguous primary that was unique
 *     when recorded is DRIFT — keep looking — and an ambiguous fallback is
 *     simply not a way of naming one thing.
 *  5. THE HOLD. A structural hit is not taken on the spot when the chain also
 *     names the element: a path resolves instantly against whatever sits in
 *     that slot while the named control is still rendering. The guess is held
 *     until the names have had the whole wait window, and stands only when
 *     none of them came.
 *  6. THE WAIT. When a pass resolves nothing, the WHOLE chain is re-walked on
 *     a poll for `waitMs` — not the primary alone — so the preference order
 *     stays intact and the best candidate wins the moment it appears. Misses
 *     are reported per pass, from the pass that resolved: a candidate that
 *     missed while the page was still painting and hits on the next poll is
 *     not volatile, it was early.
 *  7. THE RACE. A named fallback that wins while a better candidate was
 *     merely absent is confirmed once the DOM has gone quiet, and the second
 *     pass's named answer stands (see `confirm`). Drift is a better candidate
 *     that failed, never a stored index alone (`isDrift`).
 *
 * What the runners supply is OBSERVATIONS — a locator per candidate and the
 * compile-time facts about it — and how they present the result. What they
 * must not do is reinterpret any rule above.
 */

/** One candidate, as this policy sees it. The runner builds the Locator; the policy decides. */
interface CandidateObservation {
  /** The live locator for this candidate. For a point, the marker locator (see point.ts) — empty until marked. */
  locator: Locator;
  /** Its index in the STORED chain, so telemetry names the recorded candidate that took (or missed) the step. */
  index: number;
  /** Position, not identity: a path through the document, an index into a set of matches, or a point. See structuralCandidate. */
  structural: boolean;
  /** The candidate's kind ('scoped', 'role', 'css', 'point', ...). 'scoped' is the identity class; 'point' is marked before counting. */
  kind: string;
  /**
   * Text the candidate itself names, with params filled — the daemon passes
   * the candidate's JSON. An identity value found here needs no guarding:
   * the candidate already asks for it.
   */
  carries: string;
  /** The recorded match index, when the candidate was checked against the recorded element at that index. Set means ambiguity was expected. */
  nth?: number;
  /** For a point candidate: the recorded geometry. The FIRST point in the input is also the plausibility yardstick for every guess. */
  point?: PointGeometry;
  /** Demonstrated volatile by later runs (hit 0, missed repeatedly). Ordered last within its class. */
  retired?: boolean;
}

/** Policy for one resolution. Named, because seven positional flags is how a call site gets one wrong. */
interface ResolvePolicy {
  /** read_all reads across every match, so its target need not be unique. */
  allowMultiple?: boolean;
  /**
   * Loop-body cursor: when a candidate matches several records, act on THIS
   * match index (the first unprocessed record) instead of skipping to a
   * fallback. A folded loop's per-record locator is often generic across rows
   * ("Edit" on every row), so ambiguity there is the loop's normal shape, not
   * drift — and the positional fallback it used to fall through to is pinned
   * to one recorded row, which is how fwrd4l edited part A seven times.
   */
  ambiguousNth?: number;
  /**
   * Identity the step carried: values the caller vouched for that named the
   * record this step acts on ("fwrd8-n2 RD Bench Ticket"). A fallback
   * candidate is a different way of finding the SAME element, so it must
   * still land on something bearing that text — the positional and record-id
   * fallbacks recorded beside it are pinned to the recorded run's row and id,
   * and following one silently moves the whole procedure onto another record
   * (fwrd8-n2/n3 worked a seed ticket to completion this way). When no
   * fallback qualifies, the step fails to recovery, which is cheap; acting on
   * the wrong record is not. Derive it with identityValues.
   */
  requireIdentity?: readonly string[];
  /**
   * The origin the recorded step stayed on. A candidate that resolves to a
   * link leaving that origin cannot be the recorded control: diaggr1's
   * replay of fwgr26 fell from `link "New dashboard"` (its menu had been
   * toggled shut) to the structural `div > … > a:nth-of-type(1)`, which
   * matched Grafana's footer link to grafana.com; the offline box answered
   * with an error page and the whole create step went to recovery.
   */
  stayOnOrigin?: string;
  /**
   * How long to keep re-trying the WHOLE chain when nothing resolves.
   *
   * The agent never needed this: a model turn is seconds and it re-snapshots
   * each time, so anything the app was about to paint (repair-desk defers its
   * list refetch ~1s BY DESIGN) had always landed before it looked. A replay
   * has no turns, and settling only proves the DOM went quiet, which it does
   * in the gap BEFORE the refetch paints. The wait costs nothing on a healthy
   * page — it runs only after a full pass found nothing.
   *
   * Zero for a caller ASKING whether something is still there rather than
   * looking for it: the loop guard reads a null return as "the list is empty,
   * stop", so waiting there would stall every loop's normal exit.
   */
  waitMs?: number;
  /** Poll cadence inside the wait. Default RESOLVE_POLL_MS. */
  pollMs?: number;
}

/** Why a candidate ahead of the winner was passed over — the same words in both runners' telemetry. */
type MissReason =
  | 'absent' // matched nothing
  | 'unmarked' // a point with nothing of the recorded kind under it
  | 'identity' // resolved, but not to something bearing the record's identity
  | 'implausible' // resolved far from the recorded box
  | 'origin' // resolved inside a link leaving the recorded origin
  | 'ambiguous' // matched several, and this is not a place ambiguity is allowed
  | 'error'; // malformed selector or detached page

interface Resolution {
  /** The locator to act on: the candidate's own, narrowed with `.nth()` when ambiguity was allowed by cursor. */
  locator: Locator;
  /** Stored-chain index of the winning candidate. 0 is the primary; anything else is drift. */
  index: number;
  /** Set when an ambiguous candidate was narrowed to the loop cursor — the runner sinks it beside the candidate. */
  nth?: number;
  /** Whether the winner was positional — the runner sharpens its effect gate and withholds evidence on such a hit. */
  structural: boolean;
  /** Every candidate rejected in the PASS that resolved, in walk order. Empty when nothing resolved is reported as null, not here. */
  missed: { index: number; reason: MissReason }[];
}

/** Default poll cadence of the wait loop. Runs only on a page that has already failed to answer, never on the fast path. */
const RESOLVE_POLL_MS = 100;
/** Default wait window when nothing resolves, for a runner that does not configure its own. */
const RESOLVE_WAIT_MS = 3_000;

/**
 * Structural: a path through the document, or an index into a set of matches,
 * or where the element was. Position, not identity.
 *
 * Note this is NOT "kind === css". An agent-chosen `#modal-save` is a handle
 * — it names one control — while `#view > div > button:nth-of-type(2)` is a
 * route to wherever that shape currently sits. Demoting the first alongside
 * the second would push a deliberate selector below a role guess.
 */
function structuralCandidate(c: { kind: string; nth?: number; selector?: string }): boolean {
  if (c.nth !== undefined) return true;
  if (c.kind === 'point') return true; // where it was, not what it is
  if (c.kind !== 'css') return false;
  return /[>+~]|:nth-/.test(c.selector ?? '');
}

/**
 * The class a candidate belongs to, as a sort key: identity (0), handle (1),
 * path (2), point (3). A point is the last resort behind every path.
 */
function candidateRank(c: { kind: string; structural: boolean }): number {
  if (c.kind === 'scoped') return 0;
  if (c.kind === 'point') return 3;
  return c.structural ? 2 : 1;
}

/**
 * Rule 1: class order, recorded order within a class, retired last within a
 * class. Stable, so nothing shuffles for free.
 */
function orderCandidates<T extends { kind: string; structural: boolean; retired?: boolean }>(cands: readonly T[]): T[] {
  return cands
    .map((c, at) => ({ c, at }))
    .sort((a, b) => candidateRank(a.c) - candidateRank(b.c) || Number(!!a.c.retired) - Number(!!b.c.retired) || a.at - b.at)
    .map(({ c }) => c);
}

/** Does the resolved element sit inside a link that leaves the recorded origin? Rule 3(c). */
async function leavesOrigin(locator: Locator, origin: string | undefined): Promise<boolean> {
  if (!origin) return false;
  try {
    return await locator.first().evaluate((el, wanted) => {
      const a = (el as Element).closest('a[href]');
      if (!a) return false;
      try {
        const target = new URL((a as HTMLAnchorElement).href, location.href);
        // file:// pages have an opaque origin; a link there is "home" when
        // it stays on the same scheme.
        if (target.origin === 'null' || location.origin === 'null') return target.protocol !== location.protocol;
        return target.origin !== wanted;
      } catch {
        return false;
      }
    }, origin);
  } catch {
    return false;
  }
}

/**
 * Rule 3(b). The recorded geometry, when the chain carries it, is the
 * yardstick a guess is measured against: a structural fallback that resolves
 * far from where the recorded element sat is a different element — rpgr13's
 * `div > … > button` took a header button for a control in the editor's side
 * pane.
 */
async function plausible(page: Page, locator: Locator, recorded: PointGeometry | null): Promise<boolean> {
  if (!recorded) return true;
  try {
    const box = await locator.first().boundingBox();
    if (!box) return true; // nothing to measure — let the other guards judge
    const scroll = await page.evaluate(() => ({ x: window.scrollX, y: window.scrollY }));
    const cx = box.x + box.width / 2 + scroll.x;
    const cy = box.y + box.height / 2 + scroll.y;
    const limit = Math.max(recorded.vw, recorded.vh) / 3;
    return Math.hypot(cx - recorded.x, cy - recorded.y) <= limit;
  } catch {
    return true;
  }
}

/**
 * Rule 3(a). Does this candidate still identify the record the step named?
 * The recorded primary is trusted — unless it is itself structural (an
 * agent-typed positional selector at the head), which names no record.
 */
async function keepsIdentity(c: CandidateObservation, locator: Locator, requireIdentity: readonly string[]): Promise<boolean> {
  if (!requireIdentity.length || (c.index === 0 && !c.structural)) return true;
  const wanted = requireIdentity.filter((v) => !c.carries.includes(v));
  if (!wanted.length) return true;
  let text: string;
  try {
    text = ((await locator.first().textContent({ timeout: 1_000 })) ?? '').replace(/\s+/g, ' ');
  } catch {
    return false;
  }
  return wanted.every((v) => text.toLowerCase().includes(v.toLowerCase()));
}

/**
 * Whether a resolution is DRIFT: a candidate the policy tried ahead of the
 * winner failed, and the step stood on a fallback. Not merely "the winner is
 * not stored index 0": rule 1 ranks a positional primary behind the
 * candidates that name the element, and a name that wins the first try has
 * replaced nothing that missed. Reading the stored index alone filed drift
 * tickets for steps where nothing had changed (fwod41 07-change's `nth: 0`
 * path, grafana's agent-typed `div.css-qpkbik:has-text("Stat") >> nth=0`),
 * on every run, in both runners.
 */
function isDrift(hit: { index: number; missed: readonly unknown[] }): boolean {
  return hit.index > 0 && hit.missed.length > 0;
}

/**
 * Resolve one chain of candidates against the page under `policy`. `cands`
 * is given in STORED order (index ascending); this function orders it.
 * Returns null when nothing resolved within the wait.
 */
async function resolveCandidates(page: Page, cands: readonly CandidateObservation[], policy: ResolvePolicy = {}): Promise<Resolution | null> {
  const { allowMultiple = false, ambiguousNth, requireIdentity = [], stayOnOrigin, waitMs = 0, pollMs = RESOLVE_POLL_MS } = policy;
  const ordered = orderCandidates(cands);
  const recordedBox = cands.find((c) => c.kind === 'point' && c.point)?.point ?? null;

  /**
   * One pass over the chain, best candidate first, reporting which candidates
   * it REJECTED before the winner. Per pass, deliberately (rule 6).
   */
  const walk = async (): Promise<Resolution | null> => {
    const missed: Resolution['missed'] = [];
    const miss = (index: number, reason: MissReason) => missed.push({ index, reason });
    for (const c of ordered) {
      const guess = c.index > 0 || c.structural;
      try {
        // A point names a place; find what is there (of the recorded kind)
        // before a locator can name it.
        if (c.kind === 'point' && (!c.point || !(await markPoint(page, c.point)))) {
          miss(c.index, 'unmarked');
          continue;
        }
        const count = await c.locator.count();
        if (count === 1) {
          if (!(await keepsIdentity(c, c.locator, requireIdentity))) {
            miss(c.index, 'identity');
            continue;
          }
          if (guess && c.kind !== 'point' && !(await plausible(page, c.locator, recordedBox))) {
            miss(c.index, 'implausible');
            continue;
          }
          // The recorded primary is trusted even when it is such a link — the
          // recording clicked it (rpgr12-r2's sign-in skill had a stray click
          // on Grafana's "Support" footer link, and refusing it cost a
          // 19-turn recovery). Only a guess may not leave the origin.
          if (guess && (await leavesOrigin(c.locator, stayOnOrigin))) {
            miss(c.index, 'origin');
            continue;
          }
          return { locator: c.locator, index: c.index, structural: c.structural, missed };
        }
        if (count > 1) {
          if (allowMultiple) return { locator: c.locator, index: c.index, structural: c.structural, missed };
          if (ambiguousNth !== undefined && c.nth === undefined && ambiguousNth < count) {
            const picked = c.locator.nth(ambiguousNth);
            if (!(await keepsIdentity(c, picked, requireIdentity))) {
              miss(c.index, 'identity');
              continue;
            }
            return { locator: picked, index: c.index, nth: ambiguousNth, structural: c.structural, missed };
          }
          miss(c.index, 'ambiguous'); // a primary that was unique: drift; a fallback: not a way of naming one thing
          continue;
        }
        miss(c.index, 'absent');
      } catch {
        miss(c.index, 'error'); // malformed selector or detached page — try the next
      }
    }
    return null;
  };

  // Fast path first: on a page that is ready this returns immediately and the
  // wait below never runs. Rules 5 and 6: a structural hit is held while the
  // chain also names the element; the whole chain is re-walked each poll.
  const named = ordered.some((c) => !c.structural);
  const guess = (hit: Resolution | null) => !!hit && named && hit.structural;
  const first = await walk();
  if (first && !guess(first)) return confirm(first);
  let held = first;
  for (let waited = 0; waited < waitMs; waited += pollMs) {
    // A plain timer, not page.waitForTimeout: this path runs precisely when
    // the page is unhappy, and a navigating or detached page makes its own
    // clock throw.
    await new Promise((r) => setTimeout(r, pollMs));
    const hit = await walk();
    if (hit && !guess(hit)) return confirm(hit);
    if (hit) held = hit;
  }
  return held;

  /**
   * Rule 7, THE RACE. A named fallback that wins while a better candidate was
   * merely ABSENT may have won by being counted a moment later, on a page that
   * was still painting. Odoo's autocomplete does exactly this: the DOM goes
   * quiet in the gap before the search answers, so one pass counted the named
   * option (absent), then `#autocomplete_0_0` (absent), then the same id again
   * (present) — the list arrived mid-walk, and the step clicked "whatever is
   * first" by an id that only looks like a name (fwod42 02-create, two runs of
   * three). So: let the DOM go quiet once and walk again. The second answer
   * stands when it resolves to a named candidate; otherwise the first does.
   * A hit whose misses are all judgments (identity, ambiguity, origin) is
   * about the page as it is, not early, and is taken as it stands.
   */
  async function confirm(hit: Resolution): Promise<Resolution> {
    if (!isDrift(hit) || !hit.missed.some((m) => m.reason === 'absent')) return hit;
    await settleDom(page);
    const again = await walk();
    return again && !guess(again) ? again : hit;
  }
}

/** The text-bearing fields of a candidate: what it NAMES. A slot inside a css selector or a testid is an address, not a name. */
function identityFields(c: { name?: string; text?: string; label?: string; hasText?: string }): string[] {
  return [c.name, c.text, c.label, c.hasText].filter((v): v is string => typeof v === 'string');
}

/**
 * The identity values a step carried: known ({{known}}) slots whose value the
 * recorded run used to NAME the target by its visible text. `fields` are the
 * UNFILLED name/text/label/hasText strings of the WHOLE chain (identityFields
 * of every candidate) — identity is a property of the STEP, which record it
 * acts on, not of whichever candidate happens to sit first (fwrd26l: the
 * primary was an XPath stored as css and advertised nothing, while the scoped
 * anchor right behind it named the record). `known` maps a slot to its value
 * for KNOWN slots only; a value shorter than three characters is too weak to
 * pin a fallback to. Deduplicated, in first-seen order.
 */
function identityValues(known: Record<string, string | undefined>, fields: readonly string[]): string[] {
  const out = new Set<string>();
  for (const field of fields) {
    for (const m of field.matchAll(/\{\{(v\d+)\}\}/g)) {
      const value = known[m[1]];
      if (value && value.length >= 3) out.add(value);
    }
  }
  return [...out];
}

// Shared execution source: recipes.ts. Regenerate to update.
/**
 * Component recipes — the RUNNER, shared by daemon replay and the standalone
 * artifact.
 *
 * A recipe is an origin-independent micro-procedure for a third-party widget
 * that defeats the naive fill/type/select primitives (monaco, CodeMirror, a
 * contenteditable editor, a portal-rendered combobox): a short action list
 * with the payload parameterised as {{value}}, plus a mandatory verification
 * read. The honesty rule is structural: a recipe only succeeded if the
 * component's effective value re-observes the payload, and one that cannot
 * prove its effect reports failure so the caller falls back to the native
 * primitive.
 *
 * What lives here is everything that runs against a page: the family
 * recognition set, the shipped seed procedures, recognition, execution,
 * verification, and the "recipe first, then native" ladder each of fill,
 * type and select climbs. What does NOT live here is recipe SELECTION — the
 * ComponentStore in src/skills/components.ts (learned variants, statuses,
 * demotion, stats) — because that is daemon state. The daemon supplies a
 * `RecipeBook` that consults the store; the artifact supplies one built from
 * a compile-time snapshot of what the store would have chosen.
 */

type RecipeIntent = 'set-value' | 'read-value' | 'select-option' | 'open' | 'dismiss';

interface RecipeStep {
  action: 'click' | 'press' | 'insertText' | 'fill' | 'blur' | 'settle';
  /**
   * CSS relative to the component root; absent = the root itself. A
   * `page:<css>` prefix scopes to the whole page — for option lists rendered
   * into a portal outside the component's subtree.
   */
  target?: string;
  key?: string;
  /** For insertText/fill; "{{value}}" is replaced by the payload. */
  text?: string;
  /** A historical estimate of the re-render time; `settle` waits for the DOM to go quiet instead. */
  ms?: number;
  /** Restrict a page-scoped click to elements containing this (filled) text. */
  withText?: string;
}

/** The runnable part of a recipe: what both runners need, and all the artifact carries. */
interface RecipeProcedure {
  id: string;
  family: string;
  intent: RecipeIntent;
  steps: RecipeStep[];
  /** CSS relative to root for the verification read; absent = the root itself. */
  verifyRead?: string;
}

interface RecipeFamily {
  id: string;
  /** CSS the component ROOT matches (used with Element.closest). */
  root: string;
  /** Default verification read for learned recipes of this family. */
  verifyRead?: string;
}

/**
 * Recognition set. Order matters: more specific families first (CodeMirror's
 * .cm-content IS contenteditable; monaco embeds a textarea). Recognition may
 * be heuristic because being wrong is cheap: the recipe's verification read
 * fails, the action falls back to the naive primitive and then the model.
 */
const RECIPE_FAMILIES: RecipeFamily[] = [
  { id: 'monaco', root: '.monaco-editor', verifyRead: '.view-lines' },
  { id: 'codemirror6', root: '.cm-editor', verifyRead: '.cm-content' },
  { id: 'prosemirror', root: '.ProseMirror' },
  { id: 'contenteditable', root: '[contenteditable="true"]' },
  { id: 'aria-combobox', root: '[role="combobox"]' },
];

function recipeFamilyOf(id: string): RecipeFamily | undefined {
  return RECIPE_FAMILIES.find((f) => f.id === id);
}

/** Select-all → replace → commit, the shape every keyboard-driven editor takes. */
function editorSetValueSteps(clickTarget?: string, blurTarget?: string): RecipeStep[] {
  return [
    { action: 'click', ...(clickTarget ? { target: clickTarget } : {}) },
    { action: 'press', key: 'ControlOrMeta+a' },
    { action: 'insertText', text: '{{value}}' },
    { action: 'settle', ms: 400 },
    { action: 'press', key: 'Escape' },
    { action: 'blur', ...(blurTarget ? { target: blurTarget } : {}) },
    { action: 'settle', ms: 200 },
  ];
}

/** A shipped procedure before the store gives it an id, a status and stats. */
type SeedRecipe = Omit<RecipeProcedure, 'id'>;

/**
 * The shipped starter library, as procedures. Seeds are a floor, not an
 * authority: in the daemon they enter the lifecycle provisional, must verify
 * on first contact, and can be demoted or superseded by learned variants when
 * a library version changes behaviour. The store assigns their ids.
 */
const SEED_RECIPES: SeedRecipe[] = [
  { family: 'monaco', intent: 'set-value', steps: editorSetValueSteps(undefined, 'textarea'), verifyRead: '.view-lines' },
  { family: 'monaco', intent: 'read-value', steps: [], verifyRead: '.view-lines' },
  { family: 'codemirror6', intent: 'set-value', steps: editorSetValueSteps('.cm-content', '.cm-content'), verifyRead: '.cm-content' },
  { family: 'codemirror6', intent: 'read-value', steps: [], verifyRead: '.cm-content' },
  { family: 'prosemirror', intent: 'set-value', steps: editorSetValueSteps() },
  { family: 'contenteditable', intent: 'set-value', steps: editorSetValueSteps() },
  {
    family: 'aria-combobox',
    intent: 'select-option',
    steps: [
      { action: 'click' },
      { action: 'press', key: 'ControlOrMeta+a' },
      { action: 'insertText', text: '{{value}}' },
      { action: 'settle', ms: 400 },
      { action: 'click', target: 'page:[role="option"]', withText: '{{value}}' },
      { action: 'settle', ms: 200 },
    ],
  },
];

/** How long recognition waits for the target to be attached — the element must exist for `closest` to mean anything. */
const RECIPE_RECOGNIZE_MS = 1_500;
/** Per-step budget inside a recipe. */
const RECIPE_STEP_TIMEOUT_MS = 3_000;

interface RecognizedComponent {
  family: RecipeFamily;
  /**
   * The nearest matching ancestor-or-self of the target, PINNED at
   * recognition: the component root every step's `target` is relative to. A
   * handle rather than a Locator because a recipe changes what the target
   * matches — a text or placeholder target on an editor stops matching once
   * the content is replaced, and a selector that also matches a mirrored
   * preview matches more afterwards — while every click, blur and the
   * verification read must still mean the component that was recognised.
   * Whoever recognised it disposes it (`applyRecipe` does, on every exit).
   */
  root: ElementHandle;
}

/**
 * Which component (if any) the target element sits inside: nearest matching
 * ancestor, first family in RECIPE_FAMILIES order wins. The target is
 * resolved once (strictly, waiting up to RECIPE_RECOGNIZE_MS for it to
 * attach, as HEAD's `elementHandle` did); one evaluateHandle on it pins the
 * root element of the first family whose `closest` hits; one evaluate on that pinned root names the family — the first root
 * selector it matches, which is that family, since every earlier family's
 * `closest` already missed on an ancestor-or-self of the target. Null on a
 * target that is not attached, or any evaluation failure; no handle is left
 * undisposed then.
 */
async function recognizeComponent(_page: Page, target: Locator, families: readonly RecipeFamily[] = RECIPE_FAMILIES): Promise<RecognizedComponent | null> {
  const roots = families.map((f) => f.root);
  let el: ElementHandle | null = null;
  let root: ElementHandle | null = null;
  try {
    el = await target.elementHandle({ timeout: RECIPE_RECOGNIZE_MS });
    if (!el) return null;
    const found = await el.evaluateHandle((node: Element, sels: string[]) => {
      for (const sel of sels) {
        try {
          const hit = node.closest(sel);
          if (hit) return hit;
        } catch {
          // malformed selector — try the next family
        }
      }
      return null;
    }, roots);
    root = found.asElement();
    if (!root) {
      await found.dispose().catch(() => {});
      return null;
    }
    const which = await root.evaluate(
      (node: Element, sels: string[]) =>
        sels.findIndex((sel) => {
          try {
            return node.matches(sel);
          } catch {
            return false;
          }
        }),
      roots,
    );
    if (which < 0) {
      await root.dispose().catch(() => {});
      return null;
    }
    return { family: families[which], root };
  } catch {
    if (root) await root.dispose().catch(() => {});
    return null;
  } finally {
    if (el) await el.dispose().catch(() => {});
  }
}

/**
 * Run `use` on the element a root-relative step target names inside the
 * pinned root right now (the first match; the root itself when the target is
 * absent; null when it names nothing), disposing a child handle afterwards.
 */
async function withStepTarget<T>(root: ElementHandle, target: string | undefined, use: (h: ElementHandle | null) => Promise<T>): Promise<T> {
  const h = target ? await root.$(target) : root;
  try {
    return await use(h);
  } finally {
    if (h && h !== root) await h.dispose().catch(() => {});
  }
}

/** Run a recipe's steps against a recognized component root. Throws on a step that cannot run. */
async function executeRecipe(page: Page, root: ElementHandle, recipe: RecipeProcedure, payload: string): Promise<void> {
  for (const s of recipe.steps) {
    const text = s.text?.split('{{value}}').join(payload);
    const withText = s.withText?.split('{{value}}').join(payload);
    switch (s.action) {
      case 'click': {
        if (s.target?.startsWith('page:')) {
          let loc = page.locator(s.target.slice(5));
          if (withText) loc = loc.filter({ hasText: withText });
          await loc.first().click({ timeout: RECIPE_STEP_TIMEOUT_MS });
        } else {
          await withStepTarget(root, s.target, async (h) => {
            if (!h) throw new Error(`recipe ${recipe.id}: no "${s.target}" inside the component`);
            await h.click({ timeout: RECIPE_STEP_TIMEOUT_MS });
          });
        }
        break;
      }
      case 'press':
        await page.keyboard.press(String(s.key ?? ''));
        break;
      case 'insertText':
        await page.keyboard.insertText(text ?? '');
        break;
      case 'fill': {
        await withStepTarget(root, s.target, async (h) => {
          if (!h) throw new Error(`recipe ${recipe.id}: no "${s.target}" inside the component`);
          await h.fill(text ?? '', { timeout: RECIPE_STEP_TIMEOUT_MS });
        });
        break;
      }
      case 'blur': {
        // No target blurs the root itself; a blur target the recipe names but
        // the widget does not have is simply skipped.
        await withStepTarget(root, s.target, async (h) => {
          if (h) await h.evaluate((el: Element) => (el as HTMLElement).blur?.());
        });
        break;
      }
      case 'settle':
        // The recipe's `ms` was an estimate of how long the editor takes to
        // re-render; the re-render itself is observable, so wait for the DOM
        // to go quiet instead. A component that reacted already costs ~60ms
        // rather than the full estimate, and one that keeps re-rendering is
        // followed to its own end rather than cut off at a guess.
        await settleDom(page);
        break;
    }
  }
}

/** Normalise for containment checks: monaco renders spaces as NBSP, editors rewrap lines. */
function squashText(s: string): string {
  return s.replace(/ /g, ' ').replace(/\s+/g, ' ').trim();
}

/** Read the component's effective value through the recipe's verification read; null when it cannot be read. */
async function readComponentValue(root: ElementHandle, recipe: Pick<RecipeProcedure, 'verifyRead'>): Promise<string | null> {
  try {
    return await withStepTarget(root, recipe.verifyRead, async (node) => {
      if (!node) return null;
      return node.evaluate((el: Element) => {
        const anyEl = el as HTMLInputElement;
        if (typeof anyEl.value === 'string') return anyEl.value;
        return (el as HTMLElement).innerText ?? el.textContent ?? '';
      });
    });
  } catch {
    return null;
  }
}

/**
 * The honesty rule made structural: the recipe only succeeded if the
 * component's effective value re-observes the payload. A recipe that cannot
 * prove its effect reports failure and the caller falls back.
 */
async function verifyRecipe(root: ElementHandle, recipe: Pick<RecipeProcedure, 'verifyRead'>, payload: string): Promise<boolean> {
  const value = await readComponentValue(root, recipe);
  if (value === null) return false;
  if (!payload) return true;
  return squashText(value).includes(squashText(payload));
}

/** One recipe run, verified or not, for the caller's lifecycle. */
interface RecipeAttempt {
  family: string;
  intent: RecipeIntent;
  recipe: RecipeProcedure;
  /** Verified: the component re-observed the payload. */
  ok: boolean;
  /** A step that could not run at all (the recipe threw); absent when every step ran and only verification failed. */
  error?: string;
  /** The book's `onAttempt` threw (e.g. the store write failed); present only then. The attempt's outcome stands regardless. */
  warning?: string;
}

/**
 * Where a runner's recipes come from. The daemon's book consults the
 * ComponentStore; the artifact's is `snapshotBook` over a compile-time
 * snapshot. Both answer the same two questions the daemon's `tryRecipe`
 * asked: is there any usable recipe for this intent at all (if not,
 * recognising the widget can only answer null and is skipped), and which
 * recipe serves this family.
 */
interface RecipeBook {
  /** Whether ANY usable recipe exists for the intent — the gate ahead of recognition. */
  offers(intent: RecipeIntent): boolean;
  /** The recipe for a recognized family, or null when the family has none usable. */
  choose(family: string, intent: RecipeIntent): RecipeProcedure | null;
  /** Every attempt, verified or not, so a runner with a lifecycle can fold it in. */
  onAttempt?(attempt: RecipeAttempt): void;
}

/**
 * The artifact's book: a serialisable snapshot of the recipe the store would
 * choose per (family, intent) at compile time — seeds and learned variants
 * alike, demoted ones omitted. `snapshotRecipes` in src/skills/components.ts
 * builds it and says what the store holds that a static snapshot cannot
 * express.
 */
interface RecipeSnapshot {
  version: 1;
  recipes: RecipeProcedure[];
}

function snapshotBook(snapshot: RecipeSnapshot): RecipeBook {
  return {
    offers: (intent) => snapshot.recipes.some((r) => r.intent === intent),
    choose: (family, intent) => snapshot.recipes.find((r) => r.family === family && r.intent === intent) ?? null,
  };
}

/**
 * Attempt an intent through the book's recipe for whatever component the
 * target sits inside. Returns null when nothing was attempted — no recipe for
 * the intent, no recognized component, or none for its family — so the caller
 * goes straight to the native primitive; otherwise the attempt, verified or
 * not, after reporting it to the book. Execute, then verify, then report —
 * the daemon's order; a thrown step is an unverified attempt with its reason.
 */
async function applyRecipe(page: Page, target: Locator, intent: RecipeIntent, payload: string, book: RecipeBook): Promise<RecipeAttempt | null> {
  if (!book.offers(intent)) return null;
  const rec = await recognizeComponent(page, target);
  if (!rec) return null;
  let recipe: RecipeProcedure | null;
  try {
    recipe = book.choose(rec.family.id, intent);
  } catch (err) {
    await rec.root.dispose().catch(() => {});
    throw err;
  }
  if (!recipe) {
    // nothing will be attempted: release the pinned root at once
    await rec.root.dispose().catch(() => {});
    return null;
  }
  let attempt: RecipeAttempt;
  try {
    await executeRecipe(page, rec.root, recipe, payload);
    attempt = { family: rec.family.id, intent, recipe, ok: await verifyRecipe(rec.root, recipe, payload) };
  } catch (err) {
    attempt = { family: rec.family.id, intent, recipe, ok: false, error: err instanceof Error ? err.message : String(err) };
  } finally {
    await rec.root.dispose().catch(() => {});
  }
  try {
    book.onAttempt?.(attempt);
  } catch (err) {
    // Lifecycle bookkeeping (a store write the OS refused — EPERM/EBUSY on a
    // rename another session holds) must never change the action's outcome:
    // a verified recipe stays verified, and an unverified one still falls
    // back to the native primitive. The failure travels as a warning.
    attempt = { ...attempt, warning: `recipe outcome not recorded: ${err instanceof Error ? err.message : String(err)}` };
  }
  return attempt;
}

/** The words both runners report a verified recipe in. */
function describeRecipeAttempt(attempt: RecipeAttempt): string {
  const verb = attempt.intent === 'select-option' ? 'selected' : 'filled';
  const base = `${verb} via recipe ${attempt.family}/${attempt.intent} (${attempt.recipe.id}); value verified on the component`;
  return attempt.warning ? `${base} (warning: ${attempt.warning})` : base;
}

/**
 * The ladders. Each is the daemon's tool case verbatim: the recipe half
 * first, the native primitive only when nothing was verified. The verified
 * attempt is returned so the caller can say so; null means the native
 * primitive did the work.
 */
async function fillWithRecipe(page: Page, target: Locator, value: string, book: RecipeBook): Promise<RecipeAttempt | null> {
  const attempt = await applyRecipe(page, target, 'set-value', value, book);
  if (attempt?.ok) return attempt;
  await reactSafeFill(target, value);
  return null;
}

async function typeWithRecipe(
  page: Page,
  target: Locator,
  text: string,
  book: RecipeBook,
  opts: { timeout?: number; delay?: number } = {},
): Promise<RecipeAttempt | null> {
  const attempt = await applyRecipe(page, target, 'set-value', text, book);
  if (attempt?.ok) return attempt;
  await target.pressSequentially(text, opts);
  return null;
}

/** Select: the verified attempt, or the options the native select chose. */
async function selectWithRecipe(
  page: Page,
  target: Locator,
  label: string,
  book: RecipeBook,
  fallbackValue?: string,
): Promise<{ attempt: RecipeAttempt; selected: null } | { attempt: null; selected: string[] }> {
  const attempt = await applyRecipe(page, target, 'select-option', label, book);
  if (attempt?.ok) return { attempt, selected: null };
  return { attempt: null, selected: await reactSafeSelect(target, label, fallbackValue) };
}

// Shared execution source: fingerprint.ts. Regenerate to update.
/**
 * Structural page fingerprint: a fixed-size hashed bag of normalised DOM paths
 * (tags, roles, stable classes — no text, ids, or generated hashes). Two pages
 * built from the same template land close under cosine similarity; pages that
 * need a different procedure land far apart.
 *
 * Shared by both execution targets. The daemon's recorder captures it
 * (src/agent/loop.ts, src/agent/tools.ts), replay measures the live page
 * against it before a segment's soft url match (src/skills/replay.ts); a
 * compiled `.flow.ts` carries the recorded vector in its FLOW constant and
 * embeds this exact source (src/spec/runtime-source.ts) to take the same
 * measurement. Self-contained: a Playwright type is the only import, and the
 * page function below is serialised into the page, so nothing at module level
 * is in scope there.
 *
 * Shape: always FINGERPRINT_DIMS numbers, L2-normalised, each rounded to three
 * decimals at capture. `cosine` rounds its result to three decimals too, so a
 * vector carried verbatim (as the IR does) yields the very number the daemon
 * computes from the store's copy.
 */
const FINGERPRINT_DIMS = 512;

/** A page that has not answered in this long is navigating or hung: null, never a wait. */
const FINGERPRINT_CAPTURE_TIMEOUT_MS = 2_000;

/** L2-normalised vector of FINGERPRINT_DIMS, or null if the page could not be read in time. */
async function fingerprintPage(page: Page): Promise<number[] | null> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    const counts = await Promise.race([
      page.evaluate(fingerprintPathsInPage, { maxNodes: 3_000, dims: FINGERPRINT_DIMS }),
      new Promise<null>((resolve) => {
        timer = setTimeout(() => resolve(null), FINGERPRINT_CAPTURE_TIMEOUT_MS);
      }),
    ]);
    if (!counts) return null;
    return normaliseFingerprint(counts);
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Cosine similarity of two normalised vectors, rounded to three decimals; null
 * when either is missing, empty, the lengths disagree, or either holds an
 * entry that is not a finite number (nothing comparable was measured). The
 * last rule matches the IR, which omits such a stored vector, so a hand-edited
 * store makes both runners pass null rather than only the daemon measuring.
 */
function cosine(a: number[] | undefined, b: number[] | undefined): number | null {
  if (!a || !b || a.length !== b.length || !a.length) return null;
  let dot = 0;
  for (let i = 0; i < a.length; i++) {
    const x = a[i];
    const y = b[i];
    if (typeof x !== 'number' || typeof y !== 'number' || !Number.isFinite(x) || !Number.isFinite(y)) return null;
    dot += x * y;
  }
  return Math.round(dot * 1000) / 1000;
}

/** Raw bucket counts to the stored form: L2-normalised, three decimals. */
function normaliseFingerprint(counts: number[]): number[] {
  let norm = 0;
  for (const c of counts) norm += c * c;
  norm = Math.sqrt(norm) || 1;
  return counts.map((c) => Math.round((c / norm) * 1000) / 1000);
}

/**
 * Runs in the page. Emits, for every element, the path of
 * `tag[.stableClass][@role]` segments from the nearest landmark down, hashed
 * (FNV-1a) into `dims` buckets. Everything volatile is dropped: text, ids,
 * classes that look generated, inline styles, scripts.
 */
function fingerprintPathsInPage(opts: { maxNodes: number; dims: number }): number[] {
  const counts = new Array<number>(opts.dims).fill(0);
  const fnv = (s: string): number => {
    let h = 0x811c9dc5;
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193) >>> 0;
    }
    return h;
  };
  // The hex run is shape.ts CLASS_HASH_HEX_RUN, inlined because this runs in
  // the page — six, not the id rule's eight, because a build hash in a class
  // name is six; see shape.ts for why the hex rules stay three.
  const stableClass = (c: string) =>
    c.length >= 3 && c.length <= 32 && !/\d{3,}|[0-9a-f]{6,}|^(css|sc|jss|emotion)-/i.test(c) && !/^_/.test(c);
  const segment = (el: Element): string => {
    let s = el.tagName.toLowerCase();
    const role = el.getAttribute('role');
    if (role) s += '@' + role.split(' ')[0];
    const type = el.getAttribute('type');
    if (type && s.startsWith('input')) s += ':' + type.toLowerCase();
    const classes = Array.from(el.classList).filter(stableClass).sort().slice(0, 2);
    if (classes.length) s += '.' + classes.join('.');
    return s;
  };
  const skip = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'SVG', 'PATH', 'BR']);
  const segs = new Map<Element, string>();
  const all = Array.from(document.querySelectorAll('body *')).slice(0, opts.maxNodes);
  for (const el of all) {
    if (skip.has(el.tagName) || el.closest('svg')) continue;
    const own = segment(el);
    const parent = el.parentElement;
    const parentPath = parent && segs.has(parent) ? segs.get(parent)! : parent ? segment(parent) : '';
    // Keep at most four ancestors: deeper paths are all noise from the same
    // widget, shallower ones lose the region the element sits in.
    const pathParts = parentPath ? parentPath.split('/').slice(-3) : [];
    pathParts.push(own);
    const p = pathParts.join('/');
    segs.set(el, p);
    counts[fnv(p) % opts.dims] += 1;
    // Parent-child bigram and the bare segment add robustness to reordering.
    counts[fnv('seg:' + own) % opts.dims] += 0.5;
  }
  return counts;
}

// Shared execution source: echo.ts. Regenerate to update.
/**
 * The ECHO rule both execution targets share: a read-back that returns only
 * what the procedure itself typed, selected or named confirms the control's
 * display, not that the app persisted anything. grafana's time picker read
 * back "Last 6 hours" after the replay had clicked the option of that name.
 *
 * The daemon (src/skills/replay.ts) keeps one ledger per replayed segment and
 * reports an echoed label in `ReplayResult.echoedValues`, which the flow runner
 * drops from its confident values. A compiled `.flow.ts` embeds this exact
 * source (spec/runtime-source.ts), keeps the same ledger per segment, and lists
 * the label in `run.echoed`. Neither runner withholds the value from a later
 * step: an echo is a report-confidence finding, not a gate.
 *
 * Self-contained: sibling shared modules and Playwright types only.
 */

/**
 * Shortest interacted/read value worth treating as an echo. Below this the
 * coincidence rate is too high (a "1m" refresh, a "3" quantity) — a false echo
 * would wrongly drop a legitimate finding, so only substantial values qualify.
 */
const MIN_ECHO_LEN = 5;

/**
 * Tools that observe or position and SET nothing, so what they name is never
 * an interaction. A scroll to the heading "Latency by endpoint" set nothing,
 * but its target's name used to land in the ledger and the later read of that
 * heading was discounted as an echo — fwgr23 published two of three panel
 * titles on every replay and objective 1 failed each time.
 */
const OBSERVATION_TOOLS = new Set(['scroll_into_view', 'wait_for', 'hover', 'screenshot']);

/** Whether a step of this tool puts something on the page the ledger should remember. */
function setsSomething(tool: string): boolean {
  return tool !== 'read' && tool !== 'read_all' && !OBSERVATION_TOOLS.has(tool);
}

/** Loosely keyed, so "Last 6 hours" matches "last 6 hours" and "Last 6 hours." */
function echoKey(text: string): string {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

/**
 * Remember what a step put on the page: its filled `value`/typed `text`, and
 * the accessible name (else label) of every candidate of a target it resolved
 * — the name of a clicked option ("Last 6 hours") is the value it selects.
 * Callers pass only steps for which `setsSomething(tool)` holds, and the
 * candidates only once the chain RESOLVED, as replay does.
 */
function noteInteraction(ledger: Set<string>, texts: readonly unknown[]): void {
  for (const text of texts) {
    if (typeof text === 'string' && text.length >= MIN_ECHO_LEN) ledger.add(echoKey(text));
  }
}

/** The name, else the label, of each candidate: what a resolved target is known by. */
function candidateNames(candidates: readonly { name?: unknown; label?: unknown }[]): unknown[] {
  return candidates.map((c) => c.name ?? c.label);
}

/**
 * The warning for a read whose value is an echo, or null when it is not one.
 * `where` is the caller's name for the step ("step 3" in the daemon,
 * "<stepId> <segmentId>/<n>" in the artifact); `label` is the read's own key.
 */
function echoVerdict(ledger: Set<string>, label: string, value: string, where: string): string | null {
  if (!value || value.length < MIN_ECHO_LEN || !ledger.has(echoKey(value))) return null;
  return `${where}: read '${label}' returned a value the skill itself set/selected ('${clip(value, 60)}') — confirms the control, not persistence; dropped from the report's confident values`;
}

// Shared execution source: recover.ts. Regenerate to update.
/**
 * The two RECOVERY rungs both execution targets share: a navigation step whose
 * recorded affordance is gone reaching its recorded destination another way,
 * and a text wait that timed out on its resolved target while another recorded
 * candidate for that target already shows the text.
 *
 * Daemon replay (src/skills/replay.ts) calls these from runOneStep; a compiled
 * `.flow.ts` embeds this exact source (spec/runtime-source.ts) and calls them
 * from the same places in its step bodies. Each runner supplies only how it
 * clicks and navigates (its own tool layer, or the artifact's `click` adapter).
 * Self-contained: sibling shared modules and Playwright types only.
 */

/** Tools whose miss can be substituted by navigating to the step's recorded destination: plain navigation clicks. */
const NAV_FALLBACK_TOOLS = new Set(['click', 'dblclick']);

/**
 * Whether a step whose target resolved nothing may fall back to its recorded
 * destination: a plain navigation click, with a recorded url expectation the
 * browser is not already on, outside a loop body (a loop re-acts per record;
 * navigating away from the collection is never that).
 */
function mayNavigateToDestination(tool: string, destPattern: string | undefined, liveUrl: string, params: Record<string, string>, inLoopBody: boolean): destPattern is string {
  return Boolean(destPattern) && NAV_FALLBACK_TOOLS.has(tool) && !inLoopBody && !urlMatches(destPattern!, liveUrl, params);
}

/**
 * How a runner acts during recovery: its own click on a locator, its own
 * navigation. A click that fails throws as the runner's click throws, with its
 * outcome on the error (browser.ts `actionFailure`): that is what decides
 * whether the direct navigation may follow it.
 */
interface RecoveryHooks {
  /** `selector` is the css the locator was built from, for a runner that records what it clicked. */
  click(locator: Locator, selector: string): Promise<unknown>;
  goto(url: string): Promise<unknown>;
}

/**
 * The rungs a navigation step falls through when its recorded link is gone,
 * each testing how the app works for a HUMAN before the next is tried:
 *  (a) another link on the page to the same destination — click that,
 *      exercising the app's own navigation;
 *  (b) only then, and only when the destination is fully concrete
 *      (params/derived filled, nothing volatile left), navigate there
 *      directly — the last resort before recovery (the daemon's model, the
 *      artifact's stop).
 * Returns what got the browser there, or null when neither rung did — or,
 * when the rung (a) click failed without proof that nothing went out,
 * `unknown`: the click may have landed, so the direct navigation is NOT
 * tried after it (a second commit of whatever that link does), and the caller
 * stops with the note.
 */
async function navigateToDestination(
  page: Page,
  destPattern: string,
  params: Record<string, string>,
  hooks: RecoveryHooks,
): Promise<{ used: string; note: string } | { unknown: true; note: string } | null> {
  // (a) Requires the matching anchors to agree on ONE destination —
  // ambiguity (a wildcard pattern matching many records) skips the rung.
  const link = await linkToDestination(page, destPattern, params);
  if (link) {
    try {
      await hooks.click(page.locator(link.selector).first(), link.selector);
      await settleDom(page);
      if (urlMatches(destPattern, page.url(), params)) {
        return { used: `click ${link.selector}`, note: `clicked another link to the recorded destination (${link.selector})` };
      }
    } catch (err) {
      // A click proven not to have gone out: that link did not work either —
      // try the direct navigation. Anything else may have landed.
      const outcome = outcomeOfError(err);
      if (outcome !== 'not-dispatched') {
        const message = (err instanceof Error ? err.message : String(err)).split('\n')[0].slice(0, 160);
        return {
          unknown: true,
          note: `clicked another link to the recorded destination (${link.selector}), but whether that click took effect is unknown (${message}) — not navigating there directly, which could repeat it ${outcomeLabel(outcome)}`,
        };
      }
    }
  }
  // (b)
  const dest = fillParams(destPattern, params);
  const concrete = dest && !dest.includes('{{') && !/[/=#](:id|:var)(?=[/&#]|$)/.test(dest);
  if (concrete && !urlMatches(destPattern, page.url(), params)) {
    try {
      await hooks.goto(dest);
      if (urlMatches(destPattern, page.url(), params)) {
        return { used: `goto ${dest}`, note: `navigated to the step's recorded destination instead (${dest})` };
      }
    } catch {
      // destination unreachable — the caller reports the original miss
    }
  }
  return null;
}

/**
 * A visible anchor on the page whose destination matches the recorded
 * pattern. Used by the navigation fallback's first rung: when the recorded
 * link is gone, another route to the same place may exist (a sidebar entry, a
 * search result, a breadcrumb). Returns null unless every matching anchor
 * agrees on ONE destination — a wildcard-heavy pattern matching several
 * records is ambiguity, not evidence.
 */
async function linkToDestination(
  page: Page,
  pattern: string,
  params: Record<string, string>,
): Promise<{ selector: string; href: string } | null> {
  let anchors: { attr: string; abs: string }[];
  try {
    const raw = await page.evaluate(() =>
      Array.from(document.querySelectorAll('a[href]'))
        .filter((a) => (a as HTMLElement).offsetParent !== null)
        .map((a) => ({ attr: a.getAttribute('href') ?? '', abs: (a as HTMLAnchorElement).href })),
    );
    anchors = Array.isArray(raw) ? raw : [];
  } catch {
    return null;
  }
  const hits = anchors.filter((a) => a.abs && urlMatches(pattern, a.abs, params));
  if (!hits.length || new Set(hits.map((h) => h.abs)).size !== 1) return null;
  return { selector: `a[href="${hits[0].attr.replace(/(["\\])/g, '\\$1')}"]`, href: hits[0].abs };
}

/** How long the fallback candidates are given to report their text, each. */
const HELD_TEXT_READ_MS = 1_000;

/**
 * For a text wait that timed out: another recorded candidate for its target
 * that shows the text right now, if there is one. Candidates are tried in
 * STORED order after the primary (stored index 0 is never asked — it is what
 * the wait already judged, or what missed); a point is skipped (it names a
 * place, not an element with text), and a candidate must still match exactly
 * one element. The wait already gave the page its full timeout to paint.
 *
 * fwrd43's create step waited for the new ticket's title in `label "Tickets"
 * >> nth=1`, which on replay was an empty element, while the chain's own next
 * candidate — the tickets section — already showed it.
 */
async function textHeldElsewhere(
  candidates: readonly { index: number; kind: string; locator: Locator }[],
  state: unknown,
  text: unknown,
): Promise<{ index: number; locator: Locator } | null> {
  if (typeof text !== 'string' || !text.trim()) return null;
  if (state !== 'text_contains' && state !== 'text_equals') return null;
  const want = text.replace(/\s+/g, ' ').trim();
  const ordered = [...candidates].filter((c) => c.index >= 1).sort((a, b) => a.index - b.index);
  for (const candidate of ordered) {
    if (candidate.kind === 'point') continue;
    try {
      if ((await candidate.locator.count()) !== 1) continue;
      const shown = ((await candidate.locator.textContent({ timeout: HELD_TEXT_READ_MS })) ?? '').replace(/\s+/g, ' ').trim();
      if (state === 'text_equals' ? shown === want : shown.includes(want)) return { index: candidate.index, locator: candidate.locator };
    } catch {
      continue;
    }
  }
  return null;
}

/**
 * The component recipes this file drives fill/type/select through: one
 * procedure per (family, intent), the daemon's own choice at compile time.
 * Compile-time state — the daemon keeps learning and demoting; this file
 * runs what it was given. Recompile to refresh it.
 */
const RECIPES: RecipeSnapshot = {"version":1,"recipes":[{"id":"r_f2510e","family":"monaco","intent":"set-value","steps":[{"action":"click"},{"action":"press","key":"ControlOrMeta+a"},{"action":"insertText","text":"{{value}}"},{"action":"settle","ms":400},{"action":"press","key":"Escape"},{"action":"blur","target":"textarea"},{"action":"settle","ms":200}],"verifyRead":".view-lines"},{"id":"r_1f3878","family":"monaco","intent":"read-value","steps":[],"verifyRead":".view-lines"},{"id":"r_cfd806","family":"codemirror6","intent":"set-value","steps":[{"action":"click","target":".cm-content"},{"action":"press","key":"ControlOrMeta+a"},{"action":"insertText","text":"{{value}}"},{"action":"settle","ms":400},{"action":"press","key":"Escape"},{"action":"blur","target":".cm-content"},{"action":"settle","ms":200}],"verifyRead":".cm-content"},{"id":"r_8cb3a2","family":"codemirror6","intent":"read-value","steps":[],"verifyRead":".cm-content"},{"id":"r_1ab693","family":"prosemirror","intent":"set-value","steps":[{"action":"click"},{"action":"press","key":"ControlOrMeta+a"},{"action":"insertText","text":"{{value}}"},{"action":"settle","ms":400},{"action":"press","key":"Escape"},{"action":"blur"},{"action":"settle","ms":200}]},{"id":"r_7b1e49","family":"contenteditable","intent":"set-value","steps":[{"action":"click"},{"action":"press","key":"ControlOrMeta+a"},{"action":"insertText","text":"{{value}}"},{"action":"settle","ms":400},{"action":"press","key":"Escape"},{"action":"blur"},{"action":"settle","ms":200}]},{"id":"r_1e0f2f","family":"aria-combobox","intent":"select-option","steps":[{"action":"click"},{"action":"press","key":"ControlOrMeta+a"},{"action":"insertText","text":"{{value}}"},{"action":"settle","ms":400},{"action":"click","target":"page:[role=\"option\"]","withText":"{{value}}"},{"action":"settle","ms":200}]}]};
const recipeBook = snapshotBook(RECIPES);

async function settle(page: Page): Promise<void> {
  // Record the page's traffic from the first settle on, as the daemon records
  // it from the moment its session adopts a page: an action begun on it later
  // (beginAction, the shared src/execution/action.ts) has a baseline to read.
  pageTraffic(page);
  await settleDom(page);
}

const ACTION_DEADLINE_MS = 25000;

/**
 * A state-changing action that threw, rethrown with what its error proves
 * about it (the shared outcomeOfError): `[outcome: not dispatched]` when
 * nothing went out, `[outcome: unknown]` otherwise — the words replay puts
 * after its own `click failed: …`.
 */
function actionFailed(err: unknown): never {
  if (err instanceof Error && !err.message.includes('[outcome: ')) err.message += ` ${outcomeLabel(outcomeOfError(err))}`;
  throw err;
}

const URL_WAIT_MS = 5000;

/** A soft finding, in the one grep-able shape replay reports its own warnings in. */
function logWarning(line: string): void {
  console.warn(`[sitelooper warn] ${line}`);
}

/**
 * A published read whose value is only what this segment itself typed,
 * selected or named — replay's echoedValues, through the shared echoVerdict
 * (src/execution/echo.ts, embedded). It confirms the control, not that the
 * app persisted anything, so the label is listed in `run.echoed` and warned;
 * the value is still published, as replay still carries it to later steps.
 */
function echoRead(ledger: Set<string>, run: FlowRun, label: string, key: string, value: string | undefined, where: string): void {
  const echo = echoVerdict(ledger, label, value ?? '', where);
  if (!echo) return;
  run.echoed.push(key);
  logWarning(echo);
}

/** First gate after every step, as replay orders it: nothing recorded can hold on a browser error page. */
function errorPageGate(page: Page, where: string): void {
  const stop = errorPageVerdict(page.url(), where);
  if (stop) throw new Error(stop);
}

/**
 * Where the step was supposed to leave the browser — replay's expectedUrl
 * gate. The VERDICT is the shared urlEffectVerdict (src/execution/gates.ts,
 * embedded): a strict urlMatches passes, a same-shape url with 1–2 differing
 * literal segments is treated as volatile (warned, continued), anything else
 * stops. Only the WAIT is this file's own: the recorded url may still be on
 * its way (an SPA sign-in answers the click, then routes a moment later), so
 * a strict match is given URL_WAIT_MS on the navigation itself before the
 * verdict is asked once, of wherever the browser then is.
 */
async function urlEffect(page: Page, pattern: string, p: Record<string, string>, where: string): Promise<void> {
  await page.waitForURL((url) => urlMatches(pattern, url.toString(), p), { timeout: URL_WAIT_MS }).catch(() => {});
  const verdict = urlEffectVerdict(pattern, page.url(), p, where);
  for (const line of verdict.warnings) logWarning(line);
  if (verdict.stop) throw new Error(verdict.stop);
}

/**
 * The alert observation a step is judged by, taken where the daemon takes
 * its diff: after the action, once the DOM has settled (tools.ts
 * settledSignature), and before any url wait — a toast that auto-dismisses
 * inside verify's url window is seen by both runners or by neither.
 * Rendered in the step's line dialect, with whether every live region was
 * seen (the alert cap, an unread frame): "none raised" needs a full look.
 */
async function settledAlerts(page: Page, dialect: LineDialect = 1): Promise<ObservedAlerts | null> {
  await settle(page);
  return liveAlertsObserved(page, dialect);
}

/**
 * The live-region alerts a step raised, judged by the shared alertVerdict
 * (src/execution/gates.ts): an alert the recording never saw is reported,
 * and stops a state-changing step only when its recorded page changes did
 * not confirm it worked (a rejection toast that leaves the page superficially
 * intact); a recorded-but-missing one only warns.
 * Both observations are taken by the step lifecycle — `before` in prepare,
 * `after` in settle, right after the action has settled and BEFORE the url
 * wait in verify, where the daemon takes its diff (a toast that auto-dismisses
 * during a 5s url wait must not be missed) — and a page that could not be
 * read is handed over as unobserved, never as "no alert".
 */
function alertGate(before: string[], after: ObservedAlerts | null, ctx: { where: string; isRead: boolean; expectedContains?: string; params: Record<string, string>; effectConfirmed?: boolean }): void {
  const verdict = alertVerdict(before, after ? after.alerts : null, ctx, after ? after.complete : true);
  for (const line of verdict.warnings) logWarning(line);
  if (verdict.stop) throw new Error(verdict.stop);
}

/**
 * Where a segment starts — replay's start-of-segment rule, through the shared
 * preconditionVerdict (src/execution/gates.ts): a strict url match passes, a
 * same-shape url with 1–2 differing segments proceeds with a warning when the
 * page structure agrees, anything else refuses before the first step acts.
 * `similarity` is what replay's adapter passes: where the recording kept a
 * page fingerprint, the call site measures the live page with the shared
 * fingerprintPage and hands over the cosine of recorded and live — null when the page
 * could not be read, exactly as replay; null where the recording kept none
 * (the url alone decides); 'unmeasured' only for a segment of a file
 * compiled before the vector travelled, which refuses a soft match it cannot
 * measure. `url` is read at the call site BEFORE `similarity` is measured
 * (arguments evaluate left to right), as replay reads startUrl before it
 * fingerprints: both describe the page as the segment found it, not where a
 * navigation in flight landed during the measurement. Async so the call site
 * must await it: a gate that could be left un-awaited is one that can
 * silently become a no-op.
 */
async function preconditionGate(pattern: string, url: string, p: Record<string, string>, where: string, similarity: number | null | 'unmeasured'): Promise<void> {
  const verdict = preconditionVerdict(pattern, url, p, similarity);
  for (const line of verdict.warnings) logWarning(`${where}: ${line}`);
  if (verdict.refuse) throw new Error(`${where}: ${verdict.refuse} — nothing of this segment has run`);
}

/**
 * The structural page fingerprint a segment recorded, read from FLOW — the
 * source of truth, so the vector is carried once. A segment the emitter
 * asked this of always has one; its absence means FLOW was edited by hand,
 * and the gate fails closed rather than soft-match on the url alone.
 */
function recordedFingerprint(stepId: string, segmentId: string): number[] {
  const steps = FLOW.steps as unknown as readonly { id: string; segments: readonly { id: string; preconditions: { fingerprint?: number[] } }[] }[];
  const recorded = steps.find((s) => s.id === stepId)?.segments.find((g) => g.id === segmentId)?.preconditions.fingerprint;
  if (!recorded) throw new Error(`${stepId} ${segmentId}: FLOW carries no recorded page fingerprint for this segment (the file was edited) — recompile it with sitelooper`);
  return recorded;
}

/**
 * The url parts a step mints, read AFTER the navigation it started has landed.
 *
 * WHICH REPLAY RULE THIS MIRRORS. runOneStep captures the url before the
 * action and, when the action changed it, awaits settleDom before binding
 * the step's derived values — the value a spec needs is the one on the url
 * the step navigated TO, and `page.url()` read in the same tick as the
 * click still says where the page came FROM. Bound empty, every pattern
 * built from these parts (`toHaveURL`, an identity marker) can only fail.
 *
 * ALL of them together, not one at a time, because they are read into ONE
 * pattern: an app is free to populate its state fragment key by key (odoo
 * lands on `#cids=1&menu_id=81` and adds `action=` a beat later), so a part
 * that binds the instant IT is non-empty can be bound off a half-built url
 * while its neighbour is still missing. The step is not where it was
 * recorded until every part is there.
 *
 * A spec has no settleDom, so it polls on the shared resolve cadence
 * (RESOLVE_POLL_MS) within the window
 * replay effectively allows a url (URL_WAIT_MS), and takes one last reading
 * at the deadline: a step whose url genuinely does not change (the parts were
 * already there) must still bind what is there rather than hang or throw.
 *
 * The parts themselves come from the shared `urlPart` (src/execution/url.ts),
 * the daemon's own labelling; a part the url does not carry is undefined.
 */
async function urlPartsWhen(page: Page, labels: string[], urlBefore = ''): Promise<(string | undefined)[]> {
  const read = (url: string) => labels.map((label) => urlPart(url, label));
  for (let waited = 0; waited < URL_WAIT_MS; waited += RESOLVE_POLL_MS) {
    const url = page.url();
    const values = read(url);
    if (url !== urlBefore && values.every(Boolean)) {
      // The parts are there — but an app is free to redirect AGAIN from
      // the url that first carried them, and the value that matters is
      // the one on the url the step SETTLES on. Replay never sees this,
      // because it binds derived values only after settleDom absorbs the
      // whole redirect chain. So: let the DOM go quiet, and if the url
      // moved while it did, settle once more before reading.
      for (let pass = 0; pass < 2; pass++) {
        const before = page.url();
        await settle(page);
        if (page.url() === before) break;
      }
      return read(page.url());
    }
    await page.waitForTimeout(RESOLVE_POLL_MS);
  }
  return read(page.url());
}

/** One part, on the same terms. `urlBefore` is omitted where no action of this step
  * moved the page: then the wait is simply for the part to be there at all, which is
  * what the flow runner does before it publishes a step's url outputs (consumedUrlOutputs). */
async function urlPartWhen(page: Page, label: string, urlBefore = ''): Promise<string | undefined> {
  return (await urlPartsWhen(page, [label], urlBefore))[0];
}

/**
 * A derived value, bound as replay binds it: only when the url carries the
 * part. Left unset, the `{{dN}}` marker stays literal wherever it is filled,
 * which urlDiff reads as a wildcard and a locator as text no page shows.
 */
function bindPart(p: Record<string, string>, name: string, value: string | undefined): void {
  if (value !== undefined) p[name] = value;
}

const CLICK_TIER_MS = 5000;
async function click(loc: Locator, opts: { dbl?: boolean; obs?: ActionObservation | null } = {}): Promise<void> {
  // The tiers are cut to what is left of the action's deadline, and report how the click went out.
  await robustClick(loc, { timeout: CLICK_TIER_MS, dbl: opts.dbl, obs: opts.obs ?? undefined });
}

/** The words the daemon reports a verified recipe in (its tool result), as a grep-able line. */
function logRecipe(attempt: RecipeAttempt): void {
  console.log(`[sitelooper recipe] ${describeRecipeAttempt(attempt)}`);
}

/**
 * A recorded `fill`, executed as tools.ts's `case 'fill'` executes it: the
 * shared ladder `fillWithRecipe` (src/execution/recipes.ts, embedded above)
 * — the component recipe first, verified against the widget's own read,
 * and the native reactSafeFill only when nothing was verified. Both halves
 * matter. A keyboard-driven editor has no value property to set (monaco's
 * `<textarea>` is an input sink and the text you see is a rendered
 * `.view-lines` div), so a native setter writes into a box the editor never
 * reads — grafana `03-add s_e4d3e5/6` reported success on exactly that and
 * the saved panel kept its default markdown. And a plain input that commits
 * on `change` (Odoo, React controlled inputs) never sees Playwright's own
 * fill, which fires only `input` — odoo sp4od filled a quantity the form
 * never committed. The recipes themselves are the RECIPES snapshot: what the
 * daemon's component store would have chosen when this file was compiled.
 * No visibility wait ahead of recognition, as in the daemon: a recognised
 * widget's recipe clicks its root (an input sink inside it may be 0x0), and
 * the native half waits for the field itself (reactSafeFill's own 10s).
 */
async function fill(loc: Locator, value: string): Promise<void> {
  const attempt = await fillWithRecipe(loc.page(), loc, value, recipeBook);
  if (attempt) logRecipe(attempt);
}

/**
 * A recorded `type`, as tools.ts's `case 'type'`: the same set-value recipe
 * ladder a fill climbs (an editor or an aria-combobox driven by typing in
 * the recording is driven by its recipe here too), else pressSequentially
 * on the same target with the daemon's timeout and per-key delay.
 */
const TYPE_TIMEOUT_MS = 10000;
const TYPE_DELAY_MS = 20;
async function type(loc: Locator, text: string, opts: { delay?: number } = {}): Promise<void> {
  const attempt = await typeWithRecipe(loc.page(), loc, text, recipeBook, { timeout: TYPE_TIMEOUT_MS, delay: opts.delay ?? TYPE_DELAY_MS });
  if (attempt) logRecipe(attempt);
}

async function hover(loc: Locator): Promise<void> {
  await syntheticHover(loc);
}

/**
 * One recorded chain resolved against the page — the artifact's adapter to
 * the shared `resolveCandidates` (src/execution/resolve.ts, embedded above),
 * which is replay's `resolveChain` policy itself: the class order, the
 * point mark, the identity guard, plausibility, the origin guard, ambiguity
 * and its loop-cursor narrowing, the structural hold and the whole-chain
 * wait are decided THERE, in both runners. Nothing here reinterprets one.
 *
 * What this adds is presentation, exactly what replay adds around its own
 * call:
 *  - `where` (`"<stepId> <segmentId>/<stepIndex> target|source"`, baked in
 *    at each call site) turns a silent fallthrough into telemetry. A win by
 *    any candidate but the primary (stored index 0) IS drift — the recorded
 *    locator missed and a later one covered for it — so it is one stable,
 *    grep-able `[sitelooper drift]` line naming every candidate rejected
 *    ahead of the winner and WHY, in the policy's own words (MissReason).
 *  - `resolved` is the loop-body sink (replay's runOneStep `sink`): what
 *    this target resolved TO, as `<key>=<winning locator>`, with the cursor
 *    appended only when ambiguity was narrowed to it. The progress guard
 *    compares one pass's entries with the last.
 *
 * WHAT THE ARTIFACT STILL CANNOT MIRROR. Retirement (`retired`, replay's
 * evidence-based reordering of a candidate later runs showed volatile):
 * that evidence lives in the skill store, and an artifact has none, so a
 * compiled chain is ordered by class and recorded order alone. Everything
 * else the policy decides is decided here from the same observations.
 */
async function resolveTarget(
  page: Page,
  candidates: CandidateObservation[],
  where: string,
  policy: ResolvePolicy,
  opts: { drift?: string[]; resolved?: { into: string[]; key: string; check?: () => void } } = {},
): Promise<Resolution | null> {
  const hit = await resolveCandidates(page, candidates, policy);
  if (!hit) return null;
  const primary = candidates.find((c) => c.index === 0) ?? candidates[0];
  // Drift is a better candidate that FAILED (the shared isDrift), never a stored
  // index alone: a positional primary the policy ranked behind a name was not missed.
  if (isDrift(hit)) {
    const missed = hit.missed.map((m) => `#${m.index + 1} ${m.reason}`).join(', ');
    const head = hit.missed.some((m) => m.index === 0) ? `primary ${String(primary.locator)} missed; used` : 'used';
    const line = `[sitelooper drift] ${where}: ${head} #${hit.index + 1} ${String(hit.locator)} (${missed})`;
    console.warn(line);
    (opts.drift ?? DRIFT).push(line);
  }
  if (opts.resolved) {
    const won = candidates.find((c) => c.index === hit.index) ?? primary;
    opts.resolved.into.push(`${opts.resolved.key}=${String(won.locator)}${hit.nth !== undefined ? `.nth(${hit.nth})` : ''}`);
    // the loop progress guard, asked before anything acts on what just resolved
    opts.resolved.check?.();
  }
  return hit;
}

/**
 * resolveTarget for an ACTION: a chain that resolves nothing is a stop.
 *
 * `note` is passed only at a FLAGGED step (compile found the step itself
 * wrong — a demoted pin, say — see spec/diagnostics.ts). Appended to the
 * throw, it is what stops "none of 3 recorded locators resolved" from
 * reading as app drift when the recording is what needs redoing.
 */
async function pick(
  page: Page,
  candidates: CandidateObservation[],
  where: string,
  policy: ResolvePolicy,
  opts: { drift?: string[]; resolved?: { into: string[]; key: string; check?: () => void } } = {},
  note?: string,
): Promise<Resolution> {
  const hit = await resolveTarget(page, candidates, where, policy, opts);
  if (hit) return hit;
  throw pickMiss(page, candidates, where, note);
}

/** The stop for a chain that resolved nothing, shared by `pick` and `pickOrNavigate`. */
function pickMiss(page: Page, candidates: CandidateObservation[], where: string, note?: string): Error {
  return new Error(
    // The url and the recorded step are half the answer whenever a chain
    // misses wholesale: a locator that named the control on the day it was
    // recorded usually misses because the page is not the page the step
    // expected, and the log otherwise says only that nothing resolved.
    `none of ${candidates.length} recorded locators resolved at ${where} (page is at ${page.url()}): ` +
      candidates.slice(0, 3).map((c) => String(c.locator)).join(' | ') +
      (note ? `\n  ${note}` : ''),
  );
}

/**
 * `pick` for a navigation click with a recorded destination — replay's
 * navigation fallback (runOneStep), through the shared
 * mayNavigateToDestination/navigateToDestination (src/execution/recover.ts,
 * embedded). When the chain resolves nothing and the browser is not already
 * where the click was recorded to land, another visible link to that
 * destination is clicked, else a fully concrete destination is navigated to
 * directly. Arrival returns null — the step is done, logged as drift, and
 * its gates are not asked, as replay returns before them. Otherwise the
 * same stop `pick` throws. Never emitted in a loop body (replay's rule).
 */
async function pickOrNavigate(
  page: Page,
  candidates: CandidateObservation[],
  where: string,
  policy: ResolvePolicy,
  destPattern: string,
  p: Record<string, string>,
  opts: { drift?: string[]; resolved?: { into: string[]; key: string; check?: () => void } } = {},
  note?: string,
): Promise<Resolution | null> {
  const hit = await resolveTarget(page, candidates, where, policy, opts);
  if (hit) return hit;
  if (mayNavigateToDestination('click', destPattern, page.url(), p, false)) {
    const arrived = await navigateToDestination(page, destPattern, p, {
      click: async (loc) => {
        await click(loc);
      },
      goto: (url) => page.goto(url, { waitUntil: 'load', timeout: GOTO_TIMEOUT_MS }),
    });
    // The substitute link's click may have landed: a stop, never the direct navigation after it.
    if (arrived && 'unknown' in arrived) throw new Error(`${where}: none of ${candidates.length} recorded locators resolved; ${arrived.note}`);
    if (arrived) {
      const line = `[sitelooper drift] ${where}: none of ${candidates.length} recorded locators resolved; ${arrived.note}`;
      console.warn(line);
      (opts.drift ?? DRIFT).push(line);
      return null;
    }
  }
  throw pickMiss(page, candidates, where, note);
}
/** tools.ts's `goto`: the load event, within 30s. */
const GOTO_TIMEOUT_MS = 30_000;

/**
 * A recorded READ, which never fails the flow.
 *
 * WHICH REPLAY RULE THIS MIRRORS. runOneStep treats `read`/`read_all` as an
 * OBSERVATION, not a state change: a read whose target cannot be resolved —
 * or whose read itself errors — is skipped with a warning and the replay
 * CONTINUES ("skipped read — no element matched any known locator"). Failing
 * to re-capture a value says nothing about whether the procedure ran; the
 * step after it is exactly as valid as it was. A spec that threw here turned
 * a missing observation into a failed test: grafana's `panel_content` read is
 * a freshly applied text panel whose body the verifier goes on to confirm,
 * and none of the three recorded ways of naming it resolved inside the
 * resolve window — one lost value, and the run reported as a broken procedure.
 *
 * So: the resolution and the read together, and on any failure one grep-able
 * line and an EMPTY value. Assertions and outputs built from an empty read
 * are left exactly as they were — the emptiness is the honest report.
 *
 * The rules are not restated here. WHEN the resolution is asked (once, then
 * after one sweep of the page once more with no wait) is the shared
 * resolveForRead; taking the read, flattening it and turning its error into
 * a skip is the shared takeRead (src/execution/observe.ts, embedded).
 * Replay's runOneStep calls the same two; this adapter only says what it did.
 */
async function readOptional(
  page: Page,
  candidates: CandidateObservation[],
  where: string,
  policy: ResolvePolicy,
  read: (loc: Locator) => Promise<unknown>,
  opts: { drift?: string[]; resolved?: { into: string[]; key: string; check?: () => void } } = {},
): Promise<string> {
  const hit = await resolveForRead(page, (again) => resolveTarget(page, candidates, where, again ? { ...policy, waitMs: 0 } : policy, opts));
  if (!hit) {
    console.warn(`[sitelooper skip] ${where}: read target not found — value left empty`);
    return '';
  }
  const taken = await takeRead(() => read(hit.locator));
  if (taken.ok) return taken.value;
  console.warn(`[sitelooper skip] ${where}: read errored (${taken.message}) — value left empty`);
  return '';
}

/**
 * A value an earlier step had to publish, taken at the moment the step
 * that NEEDS it is handed its arguments.
 *
 * WHICH REPLAY RULE THIS MIRRORS. The flow runner resolves every {{ref}}
 * in a step's instruction and params BEFORE the step runs
 * (src/daemon/server.ts:1009-1024) and classifies what it could not fill:
 * a reference bound into a slot the pinned procedure actually USES — one a
 * recorded step types or locates by, or that names the record the
 * procedure must find — is BLOCKING (`ignorableRefs`, src/skills/flow.ts:1083),
 * so the zero-model replay is skipped and the step goes to recovery. Only a
 * reference no recorded step can be affected by replays as pinned.
 * `lookupRef` says it outright: a reference this run did not publish "goes
 * to recovery, never to a recorded literal."
 *
 * The artifact has no recovery, so blocking here is a stop. What it may NOT
 * do is what the plain `outputs[ref] ?? ''` did: carry the empty string in.
 * A read that matched nothing is left empty on purpose (see readOptional) —
 * that is honest for an observation and fatal for an argument. Empty, a
 * record-scoped locator (`li:has-text('')`) matches EVERY record and a
 * `known` slot loses the identity it exists to carry, so the blank does not
 * merely misreport the run: it does the work to the wrong record.
 *
 * Raised at CONSUMPTION, never at the read: the producing step keeps its
 * verdict, the browser is at rest, and nothing of the consuming step has
 * run when this throws.
 */
function need(outputs: Outputs, ref: string, by: string): string {
  const value = outputs[ref as keyof Outputs];
  if (value === undefined || value === '') {
    throw new Error(
      `${by} needs {{${ref}}}, and this run never published it` +
        (value === '' ? ' (it was published empty)' : '') +
        `. The step that publishes ${ref} read nothing — look above for its` +
        ` \`[sitelooper skip] … read target not found\` line, which is where this run` +
        ` diverged. Stopping here instead of passing an empty value into ${by}:` +
        ` blank, a record-scoped locator matches every record and a known slot loses` +
        ` its identity, so the step would do its work to the wrong one. Everything` +
        ` earlier steps did stands; nothing of ${by} has run.`,
    );
  }
  return value;
}

/**
 * Is this step's work already DONE on the record it names?
 *
 * WHICH REPLAY RULE THIS MIRRORS. `goalSatisfied` (src/skills/replay.ts),
 * asked of the SAME observation in the same dialect: one capture of the
 * page's snapshot lines (capturePageLines — role, name, state and the value
 * after the colon, so a marker that is only an <input>'s VALUE on a form in
 * edit mode is seen, where `getByText` never could: cloud run sp5odb died on
 * exactly that), read by lineShows. Two halves, and both are load-bearing.
 * The IDENTITY texts say the page is showing THIS record — the url and the
 * page shape only ever say "a page of this template" — and take the bounded
 * rule (`whole`: `fwgr25-n1` is not satisfied by `fwgr25-n10`); the GOAL
 * texts say that record is already in the state this step exists to
 * produce, and are a plain substring, exactly as goalSatisfied splits them.
 * Identity alone would skip a step because the right record is open; a goal
 * alone would skip it because some OTHER record happens to read "Cancelled".
 *
 * Both halves being on the PAGE is not enough, which is why the record-scope
 * check follows (scopeCheckInPage, the daemon's own, run in the page): on a
 * list, "Order A" and "Cancelled" are both present when it is order B that
 * was cancelled. They have to hold of the same record.
 *
 * Conservative by construction: no goal, no identity, or a page that cannot
 * be read — or a look that could not cover it (captureLines, dialect 2: a
 * cap reached, a visible frame unread, a virtualised list) — is never
 * satisfied. Being wrong the other way costs one re-run of a step that had
 * already happened; being wrong THIS way skips work that never happened.
 */
async function satisfied(page: Page, identity: string[], goal: string[]): Promise<boolean> {
  if (!identity.length || !goal.length) return false;
  const captured = await captureLines(page, 2);
  if (!captured || !captured.complete) return false;
  const lines = captured.lines;
  for (const want of identity) {
    if (!lineShows(lines, [want], { whole: true })) return false;
  }
  for (const want of goal) {
    if (!lineShows(lines, [want])) return false;
  }
  try {
    // The identity half goes in as regex SOURCE: scopeCheckInPage is
    // serialised into the page, so it cannot call identityRe there.
    return await page.evaluate(scopeCheckInPage, { identity: identity.map(identitySource), goal });
  } catch {
    // A page that cannot be evaluated has proven nothing. Run the step.
    return false;
  }
}

/**
 * How long a recorded page change has to appear: Playwright's own expect
 * timeout, the patience the `toBeVisible()` assertion this replaced had.
 */
const EXPECT_WAIT_MS = 5_000;

/**
 * The step's recorded page changes, judged by the daemon's own effect gate.
 *
 * WHICH REPLAY RULE THIS MIRRORS. expectedChangesVerdict (src/execution/
 * expect.ts, embedded below) IS replay's `expectedChanges` gate — the same
 * function, not a reading of it. The lines carrying this run's own values are
 * HARD, the rest are a plain group; either is looked for first in the lines
 * this step ADDED (capturePageLines before and after, diffed as the recorder
 * diffs its signatures) and then on the live page, as WHOLE snapshot lines:
 * role, name, state, and the value after the colon. An earlier cut of this
 * file rebuilt each recorded line as a Playwright locator and asserted it
 * visible, which never looked past the name — `- combobox "Project": {{v1}}`
 * passed on any visible Project combobox whatever it showed. Polled for
 * EXPECT_WAIT_MS, the patience that assertion had; the daemon reads its diff
 * once, so the artifact is the more patient of the two, never the looser.
 *
 * The verdict's warnings go to stdout as `[sitelooper warn]` lines, a missing
 * diff leg or a look that could not cover the page as `[sitelooper unobserved]`.
 * Every look is rendered in `dialect`, the one the step's lines were recorded
 * in (StepExpectation.lineDialect), exactly as replay renders its own. An absent dialog comes back to the
 * step body, which remembers it for the steps that were going to act inside.
 */
async function expectChanges(
  page: Page,
  recorded: string[],
  p: Record<string, string>,
  ctx: { tag: string; tool: string; value?: string; positionalResolution: boolean },
  linesBefore: string[] | null,
  dialect: LineDialect = 1,
): Promise<ChangeVerdict> {
  let last: ChangeVerdict = { warnings: [] };
  await expect
    .poll(
      async () => {
        last = await expectedChangesVerdict(recorded, p, ctx, {
          added: addedLines(linesBefore, await capturePageLines(page, dialect)),
          live: () => captureLines(page, dialect),
        });
        return last.stop ?? null;
      },
      { timeout: EXPECT_WAIT_MS, message: `${ctx.tag}: the recorded page change did not appear` },
    )
    .toBeNull();
  for (const warning of last.warnings) console.warn(`[sitelooper warn] ${warning}`);
  if (last.unobserved) console.warn(`[sitelooper unobserved] ${ctx.tag}: the page could not be captured, or observed in full, after the action`);
  return last;
}

/**
 * Is this step one that was going to act inside a dialog that did not open?
 *
 * WHICH REPLAY RULE THIS MIRRORS. runOneStep, while a recorded dialog is
 * absent (see ChangeVerdict.absentDialog): a step whose target cannot be
 * found AND which names one of that dialog's own controls — namesDialogControl,
 * the shared rule, proven against the dialog's recorded subtree — is skipped as
 * belonging to it. A step that resolves its target, or misses without naming
 * anything the dialog listed, is the procedure's own and runs (and fails) as
 * such; the caller clears the remembered dialog either way. A minting step is
 * never skipped, because skipping a mutation cannot be undone: the caller
 * emits none of this for one. The one look at the candidates here is what
 * replay's resolve window becomes on a page `settle` has already let go quiet.
 */
async function absentDialogSkip(
  candidates: Locator[],
  locators: Record<string, { kind: string; name?: string; text?: string; label?: string; hasText?: string }[]>,
  dialog: { name: string; lines: string[] },
  p: Record<string, string>,
  where: string,
): Promise<boolean> {
  const inside = namesDialogControl({ locators }, dialog.lines, p);
  if (inside === null) return false;
  for (const candidate of candidates) if ((await candidate.count().catch(() => 0)) > 0) return false;
  console.log(`[sitelooper skip] ${where}: acts on ${JSON.stringify(inside)}, a control of the dialog ${JSON.stringify(dialog.name)}, which did not open — skipped`);
  return true;
}

function validateInputs(vars: Vars): void {
  const missing: string[] = [];
  if (typeof vars['runid'] !== 'string' || !vars['runid'].trim()) missing.push('RUNID');
  for (const name of requiredEnvNames) {
    if (!process.env[name]?.trim()) missing.push(name);
  }
  if (missing.length) throw new Error(`missing required flow input${missing.length === 1 ? '' : 's'}: ${[...new Set(missing)].join(', ')}`);
}

