/** Runs every step in order. Each call owns its output and drift state. */
export async function runFlow(page: Page, vars: Vars, options: RunOptions = {}): Promise<Outputs> {
  validateInputs(vars);
  const run = options.run ?? createFlowRun();
  run.outputs = {};
  run.drift.length = 0;
  run.echoed = [];
  run.created = [];
  run.warnings = [];
  const outputs = run.outputs;
  try {
    const browserMismatch = profileMismatch(RECORDED_BROWSER, await readLiveBrowser(page));
    if (browserMismatch) {
      run.warnings.push(browserMismatch);
      console.warn(`[sitelooper warn] ${browserMismatch}`);
    }
    // Traffic is recorded from the start url on, as the daemon records it from adopting the page.
    pageTraffic(page);
    await page.goto(options.startUrl ?? 'http://127.0.0.1:3000/');
    await test.step('01-open: Open http://127.0.0.1:3000/ in the browser. If a login page appears, sign in with username admin and password admin; if a change-password prompt appears afterwards, click Skip. Then find and open the provisioned dashboard named \'Service health\' (for example via the Dashboards browse/search page). When it is open, report the exact titles of all its panels exactly as displayed on screen (if the dashboard uses rows or tabs, check every one so no panel is missed), and also report the dashboard\'s URL.', async () => {
      await steps['01-open'](page, { v1: 'http://127.0.0.1:3000/', v2: 'Service health' }, outputs, run);
      console.log('[sitelooper step] 01-open');
    });
    await test.step('02-create: In Grafana at http://127.0.0.1:3000/, create a NEW dashboard (Dashboards -> New dashboard -> Add visualization, or the + / New button). Add a panel of visualization type \'Stat\' (in the visualization list on the right, select \'Stat\'). Title the panel exactly \'{{runid}} Availability\' (set it in the panel options title field on the right). For the panel\'s query, set the data source to \'TestData\' (the TestData DB data source) — in the query editor\'s data source picker choose \'TestData\' and leave the default scenario (e.g. CSV Content / random walk) as is. Then save the dashboard: click the Save dashboard icon in the top bar, and in the save dialog set the dashboard NAME/TITLE to exactly \'{{runid}} Bench Dashboard\', then click Save. Confirm the save succeeded (a \'Dashboard saved\' toast appears). Then report: the dashboard title shown in the top bar, the panel title shown on the panel, the data source name shown in the query editor, and the browser page URL.', async () => {
      await steps['02-create'](page, { v1: vars.runid, v2: `${vars.runid} Availability`, v3: `${vars.runid} Bench Dashboard` }, outputs, run);
      console.log('[sitelooper step] 02-create');
    });
    await test.step('03-open: In Grafana at http://127.0.0.1:3000/, open the existing dashboard titled \'{{runid}} Bench Dashboard\' (UID {{02-create.url.p1}}, URL http://127.0.0.1:3000/d/{{02-create.url.p1}}/{{runid}}-bench-dashboard). Add a NEW panel of type \'Text\' to it (use the Add button in the top bar -> Add panel, or the dashboard\'s Add panel control, then choose the \'Text\' visualization). In the panel editor: set the panel title to exactly \'{{runid}} Notes\', and in the Text panel content editor write text that includes the runid \'{{runid}}\' (for example: \'Bench notes for run {{runid}}\'). Then click Apply/Back to exit the editor, and SAVE the dashboard (click the Save dashboard icon in the top bar and confirm Save; a \'Dashboard saved\' toast should appear). Report afterwards: the titles of all panels now visible on the dashboard, the text content shown in the Text panel on the dashboard, and whether the save toast appeared.', async () => {
      await steps['03-open'](page, { v1: `${vars.runid} Bench Dashboard`, v2: vars.runid, v3: outputs['02-create.url.p1'] ?? '', v4: `${vars.runid}-bench-dashboard`, v5: 'Save', v6: 'Dashboard saved', v7: `${vars.runid} Notes`, v8: `Bench notes for run ${vars.runid}` }, outputs, run);
      console.log('[sitelooper step] 03-open');
    });
    await test.step('04-open: In Grafana at http://127.0.0.1:3000/, open the dashboard titled \'{{runid}} Bench Dashboard\' (UID {{02-create.url.p1}}, URL http://127.0.0.1:3000/d/{{02-create.url.p1}}/{{runid}}-bench-dashboard). Do two things and make sure BOTH are persisted by saving: (1) Add the tag \'bench\' to the dashboard — open the dashboard settings (gear icon in the top bar), go to the General settings page, find the Tags field, add the tag \'bench\', then click Save. (2) Set the dashboard time range to \'Last 6 hours\' — click the time picker in the top bar and choose the \'Last 6 hours\' quick range. Then click the Save dashboard icon in the top bar; in the save dialog that appears, TICK the checkbox labeled \'Update default time range\' (so the 6-hour range is persisted into the saved dashboard), then click Save and confirm the \'Dashboard saved\' toast appears. Afterwards report: the tags shown in the dashboard settings General page (or wherever tags are visible), the time range currently shown in the top-bar time picker, whether the \'Update default time range\' checkbox was ticked before saving, and whether the save toast appeared.', async () => {
      await steps['04-open'](page, { v1: `${vars.runid} Bench Dashboard`, v2: vars.runid, v3: outputs['02-create.url.p1'] ?? '', v5: 'Save', v6: 'Dashboard saved', v7: `http://127.0.0.1:3000/d/${need(outputs, '02-create.url.p1', '04-open')}/${vars.runid}-bench-dashboard` }, outputs, run);
      console.log('[sitelooper step] 04-open');
    });
    await test.step('05-open: In Grafana at http://127.0.0.1:3000/, open the dashboard titled \'{{runid}} Bench Dashboard\' (UID {{02-create.url.p1}}, URL http://127.0.0.1:3000/d/{{02-create.url.p1}}/{{runid}}-bench-dashboard). Set the dashboard\'s auto-refresh interval to \'1m\': click the refresh-rate selector in the top bar (next to the time picker, the one showing the current refresh interval such as \'Off\' or \'5m\'), and choose \'1m\' from the list. Then SAVE the dashboard so the refresh interval is persisted: click the Save dashboard icon in the top bar and click Save in the dialog (a \'Dashboard saved\' toast should appear). Afterwards verify the persistence by opening dashboard Settings (gear icon) -> General and reporting the \'Auto refresh\' value shown there, and also report the refresh interval currently shown in the top bar, and whether the save toast appeared.', async () => {
      await steps['05-open'](page, { v1: `${vars.runid} Bench Dashboard`, v2: vars.runid, v3: outputs['02-create.url.p1'] ?? '', v5: 'Save', v6: 'Dashboard saved', v7: `http://127.0.0.1:3000/d/${need(outputs, '02-create.url.p1', '05-open')}/${vars.runid}-bench-dashboard` }, outputs, run);
      console.log('[sitelooper step] 05-open');
    });
    await test.step('06-open: In Grafana at http://127.0.0.1:3000/, do a final verification of the dashboard titled \'{{runid}} Bench Dashboard\'. Navigate to it fresh (e.g. open http://127.0.0.1:3000/d/{{02-create.url.p1}}/{{runid}}-bench-dashboard directly, or find it via Dashboards search). Then report, reading each value from the page as currently displayed: (a) the browser\'s current page URL exactly as shown in the address bar / window.location.href; (b) the dashboard title shown in the top bar; (c) the titles of all panels on the dashboard; (d) the text content rendered in the \'{{runid}} Notes\' text panel; (e) the time range shown in the top-bar time picker; (f) the refresh interval shown in the top-bar refresh picker; (g) the dashboard\'s tags (visible in dashboard Settings -> General, or wherever shown). Do not change anything — this is read-only verification.', async () => {
      await steps['06-open'](page, { v1: `${vars.runid} Bench Dashboard`, v2: vars.runid, v5: 'Dashboards', v6: `http://127.0.0.1:3000/d/${need(outputs, '02-create.url.p1', '06-open')}/${vars.runid}-bench-dashboard` }, outputs, run);
      console.log('[sitelooper step] 06-open');
    });
    return outputs;
  } finally {
    DRIFT.splice(0, DRIFT.length, ...run.drift);
  }
}
